CREATE TABLE _legal_release_20261026 (
 document_id TEXT PRIMARY KEY, previous_json TEXT NOT NULL, next_json TEXT,
 reviewed_version TEXT, reviewed_json TEXT, eligible INTEGER NOT NULL DEFAULT 0
);

INSERT INTO _legal_release_20261026(document_id,previous_json) VALUES('terms','{"title":"Términos y condiciones de uso","description":"Términos de Chile3X para visitantes, cuentas, anunciantes, agencias, arriendos, publicaciones y contenido exclusivo.","summary":"Estas condiciones regulan el acceso y uso de **chile3x.cl**, un directorio para adultos con publicaciones de escorts, agencias y arriendos en Chile. Su lectura es necesaria antes de crear una cuenta, publicar o interactuar con un anuncio.","notice":"","sections":[{"id":"alcance","title":"Alcance y aceptación","blocks":[{"id":"block-2","type":"paragraph","text":"Estos términos constituyen el acuerdo entre quien visita, crea una cuenta o utiliza cualquier función de Chile3X (la “persona usuaria”) y Chile3X respecto del uso del sitio **chile3x.cl** y sus servicios asociados. La [Política de privacidad](/privacidad) y las [Reglas de publicación](/reglas-de-publicacion) forman parte de este marco."},{"id":"block-4","type":"paragraph","text":"Crear una cuenta, enviar una publicación o utilizar funciones reservadas exige aceptar estas condiciones de manera libre e informada. La sola visita al sitio no crea una obligación de pago. Quien no acepte estas condiciones deberá abstenerse de utilizar funciones que requieran su aceptación."}]},{"id":"adultos","title":"Acceso exclusivo para personas adultas","blocks":[{"id":"block-2","type":"paragraph","text":"Chile3X está destinado exclusivamente a personas de **18 años o más**. Al ingresar, la persona usuaria declara cumplir esa edad y se obliga a no facilitar el acceso ni entregar sus credenciales a personas menores de edad."},{"id":"block-4","type":"paragraph","text":"La confirmación de mayoría de edad del aviso de entrada no equivale por sí sola a una verificación de identidad. Chile3X puede solicitar antecedentes adicionales para determinadas cuentas o publicaciones y rechazar, suspender o eliminar accesos cuando existan dudas razonables sobre la edad o identidad."}]},{"id":"rol","title":"Rol y límites de Chile3X","blocks":[{"id":"block-2","type":"paragraph","text":"Chile3X es una plataforma tecnológica de publicación, búsqueda y contacto. No presta servicios personales anunciados, no representa a visitantes o anunciantes y no es parte de citas, arriendos, viajes, comunicaciones, transferencias, pagos ni acuerdos que se realicen fuera del portal."},{"id":"block-4","type":"paragraph","text":"La aprobación de un anuncio, una etiqueta o un distintivo de verificación indica únicamente que Chile3X realizó una revisión administrativa con los antecedentes disponibles en ese momento. No certifica identidad permanente, conducta futura, condiciones sanitarias, disponibilidad, legalidad de un acuerdo externo ni ausencia total de riesgos."}]},{"id":"cuentas","title":"Cuentas, credenciales y datos de registro","blocks":[{"id":"block-2","type":"list","text":"","items":["La información entregada debe ser veraz, actual y corresponder a la persona que crea la cuenta o a quien tenga autorización suficiente para actuar.","Cada persona es responsable de mantener segura su contraseña y de las acciones efectuadas desde su cuenta. Debe avisar de inmediato si detecta un acceso no autorizado.","No se permite vender, ceder, prestar ni compartir una cuenta para eludir una suspensión o permitir que otra persona se haga pasar por su titular.","Chile3X puede solicitar corrección de datos, confirmación de correo, edad, identidad, autorización o representación antes de publicar o mantener un anuncio.","Los accesos federados admitidos deben corresponder a una identidad compatible y respetar las validaciones de registro. Google se encuentra disponible; Apple y X permanecen preparados e inactivos mientras no se habiliten expresamente. Las identidades administrativas continúan separadas e ingresan mediante GitHub.","La desvinculación de un proveedor exige configurar y confirmar una contraseña de acceso. No elimina la cuenta ni deja sin verificar un correo previamente verificado. Los cambios de método de acceso se registran para su consulta por la persona titular y administración autorizada.","Los datos legales y documentos privados de una cuenta no se muestran en el anuncio salvo que su titular los incorpore voluntariamente a un campo público."],"ordered":false}]},{"id":"publicaciones","title":"Publicaciones, revisión y distintivo de verificación","blocks":[{"id":"block-2","type":"paragraph","text":"Los perfiles de escort, agencia y arriendo se envían a revisión manual antes de publicarse. Chile3X puede pedir cambios, rechazar material, limitar su alcance, pausar el anuncio o retirarlo cuando incumpla estas condiciones, las reglas de publicación, la ley o criterios razonables de seguridad."},{"id":"block-4","type":"paragraph","text":"El distintivo verde de “verificado” es opcional y se concede manualmente. Refleja una comprobación adicional realizada con la información disponible al momento de la revisión; puede retirarse si los datos cambian, caducan, resultan inconsistentes o existe una alerta fundada."},{"id":"block-6","type":"paragraph","text":"La revisión del anuncio y la aprobación de sus archivos son controles distintos. Los archivos nuevos o reemplazados se someten a su revisión correspondiente; su carga no implica, por sí sola, que toda la publicación cambie de estado. El equipo puede revisar, limitar o retirar un anuncio cuando existan cambios o antecedentes que lo justifiquen."},{"id":"block-8","type":"paragraph","text":"La persona titular y administración autorizada pueden consultar una vista previa privada de anuncios no publicados. Esa vista no constituye aprobación ni permite su acceso público. Administración puede editar datos, revisar documentos privados y publicar historias por cuenta del anunciante dentro de sus permisos; estas actuaciones deben responder a una solicitud, autorización o finalidad operativa legítima y quedan registradas."}]},{"id":"agencias-arriendos","title":"Reglas especiales para agencias y arriendos","blocks":[{"id":"block-2","type":"subheading","text":"Agencias","numbered":true},{"id":"block-4","type":"paragraph","text":"Una agencia solo puede vincular a una escort con autorización expresa de esa persona. La invitación debe ser aceptada por la cuenta correspondiente; está prohibido crear relaciones aparentes, reutilizar identidades o agregar personas sin consentimiento. La agencia responde por la veracidad de su información institucional y por sus propios actos, sin adquirir propiedad ni control sobre las cuentas vinculadas."},{"id":"block-6","type":"subheading","text":"Arriendos","numbered":true},{"id":"block-8","type":"paragraph","text":"Quien publica un arriendo declara tener derecho para ofrecer el espacio, entregar información veraz y cumplir las normas civiles, sanitarias, de copropiedad, seguridad y demás obligaciones aplicables. Chile3X no inspecciona inmuebles ni garantiza disponibilidad, condiciones, permisos o acuerdos entre las partes."},{"id":"block-10","type":"paragraph","text":"Las categorías de visibilidad y etiquetas propias de escorts, como VIP, Premium, Bronze, MILF, Trans, Hombres o Masajes, no se aplican a agencias ni arriendos."}]},{"id":"obligaciones","title":"Obligaciones de quien publica","blocks":[{"id":"block-2","type":"paragraph","text":"Quien envía un anuncio declara y garantiza que:"},{"id":"block-4","type":"list","text":"","items":["es mayor de edad y actúa de forma libre, consciente y sin coacción;","la descripción, ciudad, disponibilidad, servicios, precios, contactos, viajes y demás datos son auténticos y se mantienen actualizados;","posee los derechos o autorizaciones necesarias sobre cada imagen, video, texto, marca y dato publicado;","todas las personas identificables que aparecen en el material son adultas y autorizaron expresamente su captura y publicación;","retirará o solicitará el retiro del material si pierde una autorización necesaria;","no utilizará la plataforma para controlar, explotar, amenazar, endeudar, trasladar o beneficiarse abusivamente de otra persona."],"ordered":false}]},{"id":"prohibiciones","title":"Contenido y conductas estrictamente prohibidos","blocks":[{"id":"block-2","type":"paragraph","text":"Está prohibido publicar, solicitar, enlazar, distribuir o utilizar Chile3X para:"},{"id":"block-4","type":"list","text":"","items":["cualquier contenido, servicio o interacción que involucre a una persona menor de 18 años, incluso mediante apariencia simulada, edición digital o inteligencia artificial;","trata de personas, explotación sexual, trabajo forzado, servidumbre, coacción, violencia, abuso de poder o aprovechamiento de vulnerabilidad o dependencia;","difundir imágenes o sonidos íntimos sin autorización expresa, material obtenido de forma clandestina, “revenge porn”, sextorsión o amenazas de publicación;","mostrar a una persona inconsciente, incapacitada para consentir, bajo violencia real o en una situación que razonablemente sugiera ausencia de consentimiento;","suplantar identidades, crear perfiles falsos, utilizar deepfakes o contenido sintético para atribuir actos reales a otra persona, o alterar documentos;","publicar datos privados de terceros, domicilios exactos no autorizados, documentos, teléfonos o información destinada a acosar, perseguir o extorsionar;","ofrecer actividades con animales, armas, drogas, lesiones reales, delitos o cualquier prestación prohibida por la legislación aplicable;","estafar, lavar activos, enviar spam, manipular reseñas o métricas, captar credenciales, introducir malware, vulnerar medidas de seguridad o extraer datos masivamente sin autorización;","discriminar, hostigar, amenazar o incitar violencia contra una persona o grupo."],"ordered":false},{"id":"block-6","type":"callout","text":"Ante indicios de minoría de edad, explotación, trata, violencia o difusión íntima no consentida, Chile3X puede retirar preventivamente el contenido, preservar antecedentes necesarios y colaborar con las autoridades competentes conforme a la ley."}]},{"id":"comunidad","title":"Favoritos, likes, reseñas, mensajes, Telegram, bloqueos y reportes","blocks":[{"id":"block-2","type":"paragraph","text":"Las cuentas pueden utilizar funciones de comunidad de acuerdo con su disponibilidad. Las reseñas y comentarios deben referirse a experiencias reales, expresarse con respeto y no contener datos personales, amenazas, extorsión, publicidad, acusaciones deliberadamente falsas ni contenido ilícito."},{"id":"block-4","type":"paragraph","text":"Bloquear un anuncio solo lo oculta para la cuenta que realizó la acción; no sanciona al anunciante. Reportar inicia una revisión, no determina culpabilidad. El uso coordinado de votos, likes, reportes o reseñas para manipular resultados está prohibido."},{"id":"block-6","type":"paragraph","text":"El chat interno vincula cada conversación con un anuncio y exige una cuenta activa. Está prohibido usarlo para spam, acoso, amenazas, suplantación, captación ilícita, envío de malware o intercambio de contenido ilegal. Silenciar detiene avisos; bloquear impide mensajes nuevos y mantiene el historial disponible mientras corresponda. Si una cuenta se deshabilita o elimina, su identidad visible se reemplaza por “Usuario de Chile3X” para el otro participante y no se admiten mensajes nuevos. Esta sustitución no garantiza la anonimización del contenido previo: los propios mensajes podrían contener referencias identificables."},{"id":"block-8","type":"paragraph","text":"El centro de ayuda beta, denominado “Johnny Sins”, es un bot de búsqueda guiada basado en documentación revisada del sitio. No constituye atención humana, asesoría profesional ni inteligencia artificial generativa; sus respuestas pueden contener errores y no ejecutan modificaciones de cuentas. La persona usuaria debe verificar los pasos y recurrir a los canales oficiales cuando no se resuelva su consulta. El nombre y la imagen no implican participación, afiliación ni respaldo del actor."},{"id":"block-10","type":"paragraph","text":"El foro se encuentra en una beta privada accesible exclusivamente a administración autorizada. No admite participación de usuarios generales ni constituye una sección pública. Publicar exige confirmar las normas vigentes, que pueden consultarse en su sección propia. Sus temas, respuestas y adjuntos están sujetos a las prohibiciones de estos términos: no se permite incluir documentos privados ni datos personales de terceros. Todo adjunto requiere derechos de publicación y consentimiento de las personas adultas representadas, queda pendiente de revisión y está sujeto a límites de frecuencia, tamaño y almacenamiento. Una aprobación administrativa no certifica identidad, legalidad ni ausencia de riesgos."},{"id":"block-12","type":"paragraph","text":"Las herramientas del foro permiten solicitar revisión o rectificación de mensajes, registrar decisiones de moderación y seguir temas con notificaciones internas propias, sin correos automáticos. Los adjuntos retirados, rechazados o asociados a mensajes o temas en papelera se depuran tras 30 días; las notificaciones, tras 90 días, y las denuncias cerradas, tras 180 días, conforme a la Política de privacidad y sus excepciones fundadas. Una apertura posterior requerirá informar previamente sus reglas y condiciones y revisar expresamente los permisos de acceso."},{"id":"block-14","type":"paragraph","text":"La comunidad pública de Telegram puede utilizarse sin cuenta Chile3X. El acceso al espacio privado de Miembros requiere una cuenta activa, correo verificado y vinculación voluntaria con el bot. Los mensajes quedan sujetos a las reglas de la comunidad, a las condiciones de Telegram y a moderación manual o automática por spam, fraude, amenazas, acoso, contenido ilícito o reincidencia. Una medida en Telegram no reemplaza por sí sola una decisión sobre la cuenta del sitio."}]},{"id":"medios","title":"Fotos, videos, historias y estados","blocks":[{"id":"block-2","type":"paragraph","text":"Todo material enviado queda sujeto a moderación. El sistema puede redimensionar, comprimir y convertir técnicamente archivos para su publicación. La marca de agua en fotos y videos y el difuminado de rostros en fotografías se aplican cuando se seleccionan las opciones correspondientes; el difuminado de videos no se encuentra habilitado. La preparación se realiza en el dispositivo cuando la función lo permite y se almacena el archivo final, sin conservar una segunda copia del original por ese procesamiento. Estas medidas no garantizan impedir copias ni ocultar correctamente todos los rostros; el resultado debe revisarse antes de enviarlo."},{"id":"block-4","type":"paragraph","text":"La galería del anuncio admite fotografías finales de hasta 10 MB y videos finales de hasta 12 MB y 15 segundos. Las historias admiten hasta cinco fotografías finales de 5 MB, cinco estados de texto y tres videos de hasta 12 MB y 15 segundos activos por anuncio. Los formularios informan los formatos y demás restricciones aplicables; documentos privados y otros tipos de archivo tienen controles específicos."},{"id":"block-6","type":"paragraph","text":"Las historias de fotografía, video y texto expiran públicamente a las 24 horas. Una tarea programada elimina los archivos y registros vencidos del almacenamiento activo; su ejecución puede demorarse ante errores técnicos o acumulación de tareas, sin prolongar el acceso público. Las copias transitorias de respaldo o caché se rigen por la Política de privacidad. El contenido temporal sigue sujeto a estas condiciones durante toda su existencia."}]},{"id":"exclusivo","title":"Galería de contenido exclusivo","blocks":[{"id":"block-2","type":"paragraph","text":"Cuando esté habilitada, la persona anunciante puede cargar material en una galería privada y autorizar cuentas concretas mediante su correo registrado. El material se muestra bloqueado o difuminado a quienes no tengan acceso. La autorización puede revocarse, pero no permite controlar copias que una persona autorizada haya realizado fuera del portal."},{"id":"block-4","type":"paragraph","text":"Chile3X no procesa actualmente el pago por ese acceso ni actúa como vendedor, comprador, representante o garante de acuerdos económicos externos. Solo puede subirse material propio, consentido y lícito. Está prohibido conceder acceso a menores de edad o compartir las credenciales de una cuenta autorizada."}]},{"id":"reportes","title":"Reportes, evidencias y moderación","blocks":[{"id":"block-2","type":"paragraph","text":"Una cuenta iniciada puede reportar un anuncio, explicar el motivo y adjuntar hasta el límite de evidencias informado en el formulario. Esos antecedentes son privados y se muestran al equipo autorizado y a la persona que reportó en su panel; no se publican en el anuncio."},{"id":"block-4","type":"paragraph","text":"Chile3X puede solicitar información, ocultar contenido preventivamente, dejar una publicación pendiente, rechazar cambios, desactivar cuentas, revocar verificaciones o eliminar material. La gravedad, reiteración, riesgo para terceros y colaboración durante la revisión pueden considerarse. Las solicitudes de reconsideración se reciben en el canal oficial de contacto, sin perjuicio de las denuncias que correspondan ante autoridades."}]},{"id":"propiedad","title":"Propiedad intelectual y licencia de publicación","blocks":[{"id":"block-2","type":"paragraph","text":"Cada titular conserva los derechos sobre el contenido que aporta. Al enviarlo concede a Chile3X una licencia no exclusiva, gratuita, revocable respecto de usos futuros y limitada a operar, almacenar, respaldar, adaptar técnicamente, moderar, proteger, promocionar el propio anuncio y mostrar el contenido dentro del portal y sus vistas previas."},{"id":"block-4","type":"paragraph","text":"La parte pública de un anuncio puede ser indexada por buscadores y aparecer al compartir enlaces en redes sociales. Retirar el anuncio detiene usos futuros controlados por Chile3X, pero la desindexación, cachés o copias de terceros pueden tardar y dependen de esos servicios."},{"id":"block-6","type":"paragraph","text":"Las marcas, diseño, código, textos institucionales y elementos propios de Chile3X no pueden copiarse, comercializarse ni reutilizarse sin autorización. Las reclamaciones por uso no autorizado de material se reciben en [chile3x.site@gmail.com](mailto:chile3x.site@gmail.com), indicando el contenido y la relación de quien reclama con él."}]},{"id":"contacto-externo","title":"Contactos, redes y servicios externos","blocks":[{"id":"block-2","type":"paragraph","text":"Los botones de teléfono, WhatsApp, Telegram, Instagram, Arsmate, OnlyFans y otros enlaces conducen a servicios de terceros con sus propias reglas y políticas. Chile3X no controla sus mensajes, cobros, disponibilidad, seguridad ni tratamiento de datos."},{"id":"block-4","type":"paragraph","text":"Dentro de un anuncio con contacto disponible, el panel de WhatsApp distingue y presenta primero al anunciante, seguido de los canales del equipo de Chile3X. Soporte y marketing no representan al anunciante ni coordinan sus servicios. Los contadores registran pulsaciones, no mensajes enviados ni una garantía de contacto efectivo."},{"id":"block-6","type":"paragraph","text":"Cuando una persona vincula Telegram, el bot puede comprobar su identidad del sitio, administrar invitaciones, sincronizar Novedades y aplicar las medidas descritas en las reglas. Chile3X no solicita la contraseña de Telegram. El botón de Apple permanece inactivo mientras no exista una configuración completa; si se habilita, la autenticación se realizará en los servidores de Apple y el correo asociado quedará bloqueado en Chile3X."},{"id":"block-8","type":"paragraph","text":"La agenda de viajes y los horarios son información declarada por el anunciante. Mostrar “24/7” resume una configuración de atención durante las 24 horas de los siete días y no acredita disponibilidad real en cada momento. La agenda no modifica automáticamente la ciudad principal ni constituye intermediación, transporte o garantía. Está prohibido utilizarla para captar, trasladar o explotar personas o facilitar conductas contrarias a los artículos 411 ter y 411 quáter del Código Penal u otras normas aplicables."}]},{"id":"disponibilidad","title":"Disponibilidad, mantenimiento y cambios técnicos","blocks":[{"id":"block-2","type":"paragraph","text":"Chile3X procura mantener el servicio disponible, pero puede realizar mantenimiento, corregir fallas, cambiar funciones, limitar cargas o suspender temporalmente áreas por seguridad, capacidad, cumplimiento legal o causas fuera de su control. No se garantiza funcionamiento continuo ni compatibilidad con todos los dispositivos."},{"id":"block-4","type":"paragraph","text":"Las copias de respaldo y medidas de recuperación reducen riesgos, pero no reemplazan el deber de cada anunciante de conservar sus propios archivos y antecedentes originales."}]},{"id":"pagos-futuros","title":"Publicación gratuita actual, planes y funciones futuras","blocks":[{"id":"block-2","type":"paragraph","text":"Mientras Chile3X no informe expresamente lo contrario, el registro y los flujos actuales no generan un cobro automático. Los pagos integrados, suscripciones automatizadas, venta de contenido y billeteras no forman parte del servicio vigente."},{"id":"block-4","type":"paragraph","text":"Si se habilitan funciones pagadas, antes de contratar se informarán de forma clara el precio en pesos chilenos, duración, renovación, medios de pago, impuestos, forma de terminación, retracto cuando legalmente proceda y condiciones particulares. La aceptación se solicitará separadamente y se entregará una confirmación que pueda conservarse, conforme a la Ley N.º 19.496 y demás normas aplicables."}]},{"id":"responsabilidad","title":"Responsabilidad y seguridad personal","blocks":[{"id":"block-2","type":"paragraph","text":"Las personas usuarias deben evaluar por sí mismas cualquier contacto o acuerdo externo, proteger sus datos, evitar anticipos sospechosos y adoptar medidas razonables de seguridad. Chile3X no garantiza la identidad permanente, solvencia, ubicación, conducta, calidad, salud ni cumplimiento de otra persona."},{"id":"block-4","type":"paragraph","text":"Nada en estos términos excluye responsabilidades que no puedan limitarse conforme a la ley, derechos irrenunciables de consumidores cuando sean aplicables ni responsabilidad propia de Chile3X por dolo o culpa grave. La plataforma responderá dentro del alcance exigido por la legislación chilena."}]},{"id":"termino","title":"Pausa, suspensión, cierre y eliminación","blocks":[{"id":"block-2","type":"paragraph","text":"La persona anunciante puede ocultar temporalmente sus publicaciones y solicitar el cierre de su cuenta mediante las funciones disponibles o el canal de soporte. Chile3X puede restringir o terminar el acceso por incumplimiento, riesgo, requerimiento de autoridad, fraude, inactividad prolongada o necesidad operativa fundada."},{"id":"block-4","type":"paragraph","text":"El cierre no elimina de inmediato antecedentes que deban conservarse para resolver reportes, prevenir abuso, ejercer o defender derechos, cumplir obligaciones legales o mantener respaldos transitorios. El tratamiento posterior se rige por la Política de privacidad."},{"id":"block-6","type":"paragraph","text":"Los plazos ordinarios de conservación se describen en la [sección 15 de la Política de privacidad](/privacidad#conservacion): documentos de identidad hasta 90 días, archivos médicos hasta 30 días, reportes resueltos hasta 180 días, conversaciones sin nuevos mensajes y auditoría hasta 365 días. Las historias conservan su duración de 24 horas. La transición de la nueva depuración no posterga solicitudes de eliminación ni permite mantener una historia vencida visible."},{"id":"block-8","type":"paragraph","text":"Una sesión del navegador no puede operar simultáneamente como cuenta pública y como identidad administrativa. Iniciar sesión en otro panel cierra la sesión anterior de ese navegador; los correos administrativos reservados no pueden utilizarse para crear o recuperar cuentas públicas. Los accesos contradictorios se rechazan y requieren una nueva autenticación."},{"id":"block-10","type":"paragraph","text":"Deshabilitar o eliminar una cuenta revoca su acceso al espacio privado de Telegram. Cuando una cuenta creada con Apple se elimine permanentemente y el proveedor esté activo, Chile3X intentará además revocar la autorización externa antes de borrar localmente la identidad."}]},{"id":"cambios","title":"Cambios de estos términos","blocks":[{"id":"block-2","type":"paragraph","text":"Chile3X puede actualizar estas condiciones por cambios funcionales, legales, técnicos o de seguridad. La versión y fecha vigentes se mostrarán en esta página. Los cambios materiales se comunicarán con una anticipación razonable por el sitio, la cuenta o correo, salvo que una medida urgente de seguridad o una obligación legal requiera aplicación inmediata."},{"id":"block-4","type":"paragraph","text":"Cuando una modificación necesite un consentimiento nuevo, se solicitará antes de aplicar la función correspondiente. El uso posterior a la entrada en vigor no convalida cláusulas que legalmente requieran aceptación expresa."}]},{"id":"ley","title":"Legislación chilena, autoridades y contacto","blocks":[{"id":"block-2","type":"paragraph","text":"Estos términos se interpretan conforme a las leyes de la República de Chile, incluyendo, según corresponda, la Ley N.º 19.628 sobre protección de la vida privada, la Ley N.º 19.496 sobre protección de los derechos de los consumidores, la Ley N.º 19.799 sobre documentos y firma electrónica, el Código Penal y la Ley N.º 21.719 desde su entrada en vigencia el **1 de diciembre de 2026**."},{"id":"block-4","type":"paragraph","text":"Antes de iniciar una controversia, puede solicitarse una revisión escribiendo a [chile3x.site@gmail.com](mailto:chile3x.site@gmail.com). Esto no limita el derecho a acudir a SERNAC, tribunales, policías, Ministerio Público, la Agencia de Protección de Datos Personales cuando ejerza sus atribuciones u otra autoridad competente."},{"id":"block-6","type":"sources","text":"Fuentes legales oficiales","items":["[Ley N.º 19.628 sobre protección de la vida privada](https://www.bcn.cl/leychile/navegar?idNorma=141599)","[Ley N.º 21.719 sobre protección de datos personales](https://www.bcn.cl/leychile/navegar?idNorma=1209272)","[Ley N.º 19.496 sobre protección de los derechos de los consumidores](https://www.bcn.cl/leychile/navegar?idNorma=61438)"]}]}]}');

UPDATE _legal_release_20261026 SET next_json='{"title":"Términos y condiciones de uso","description":"Términos de Chile3X para visitantes, cuentas, anunciantes, agencias, arriendos, publicaciones y contenido exclusivo.","summary":"Estas condiciones regulan el acceso y uso de **chile3x.cl**, un directorio para personas adultas con anuncios de escorts, agencias y arriendos en Chile. Explican los derechos y obligaciones de visitantes, cuentas y anunciantes, el tratamiento responsable del contenido y las condiciones que deberán cumplirse antes de habilitar servicios pagados.","notice":"**Operador y contacto:** **Pedro Enrique Reyes González**, persona natural, RUT **15.771.562-3**, que opera bajo el nombre comercial **Chile3X**. Consultas, reclamaciones y solicitudes de privacidad: [chile3x.site@gmail.com](mailto:chile3x.site@gmail.com). La aceptación de estas condiciones no sustituye el consentimiento específico que corresponda para tratar datos sensibles ni una autorización de pago.","sections":[{"id":"alcance","title":"Alcance y aceptación","blocks":[{"id":"block-2","type":"paragraph","text":"Estos términos constituyen el acuerdo entre quien visita, crea una cuenta o utiliza cualquier función de Chile3X (la “persona usuaria”) y Chile3X respecto del uso del sitio **chile3x.cl** y sus servicios asociados. La [Política de privacidad](/privacidad) y las [Reglas de publicación](/reglas-de-publicacion) forman parte de este marco."},{"id":"block-4","type":"paragraph","text":"Crear una cuenta, enviar una publicación o utilizar funciones reservadas exige aceptar estas condiciones de manera libre e informada. La sola visita al sitio no crea una obligación de pago. Quien no acepte estas condiciones deberá abstenerse de utilizar funciones que requieran su aceptación."},{"id":"extended-3","type":"paragraph","text":"El operador del portal y contraparte de los servicios propios de Chile3X es **Pedro Enrique Reyes González**, persona natural, RUT **15.771.562-3**, que opera bajo el nombre comercial **Chile3X**. El medio electrónico de contacto es [chile3x.site@gmail.com](mailto:chile3x.site@gmail.com). Chile3X es un nombre comercial y no se presenta como una sociedad distinta de esa persona. Antes de habilitar contratación pagada se informarán también el domicilio legal y los restantes antecedentes comerciales exigibles."},{"id":"extended-4","type":"paragraph","text":"Aceptar estos términos regula la relación de uso; conocer la Política de privacidad satisface una finalidad informativa. Ninguna de esas acciones equivale por sí sola a autorizar toda utilización de datos, publicidad, publicación de información íntima, cesión a terceros o cobros. Los consentimientos que correspondan deben referirse a una finalidad concreta y permitir su retirada."},{"id":"extended-5","type":"paragraph","text":"La versión del 26 de octubre de 2026 distingue el régimen de la Ley N.º 19.628 actualmente vigente del texto reformado por la Ley N.º 21.719, cuya entrada general en vigor está fijada para el **1 de diciembre de 2026** en el texto legal consultado. Las reglas futuras se aplicarán desde su vigencia efectiva; un proyecto de aplazamiento no cambia esa fecha por sí solo. No se exige a la persona usuaria renunciar anticipadamente a derechos actuales o futuros."}]},{"id":"adultos","title":"Acceso exclusivo para personas adultas","blocks":[{"id":"block-2","type":"paragraph","text":"Chile3X está destinado exclusivamente a personas de **18 años o más**. Al ingresar, la persona usuaria declara cumplir esa edad y se obliga a no facilitar el acceso ni entregar sus credenciales a personas menores de edad."},{"id":"block-4","type":"paragraph","text":"La confirmación de mayoría de edad del aviso de entrada no equivale por sí sola a una verificación de identidad. Chile3X puede solicitar antecedentes adicionales para determinadas cuentas o publicaciones y rechazar, suspender o eliminar accesos cuando existan dudas razonables sobre la edad o identidad."},{"id":"extended-3","type":"paragraph","text":"El permiso de un padre, madre, representante o tercero no habilita a una persona menor de 18 años para utilizar este directorio. No se debe subir documentación de una persona menor para intentar completar un registro. Frente a indicios de minoría de edad se limitará la difusión y solo podrán conservarse antecedentes estrictamente necesarios para protección, denuncia o una obligación legal aplicable."}]},{"id":"rol","title":"Rol y límites de Chile3X","blocks":[{"id":"block-2","type":"paragraph","text":"Chile3X es una plataforma tecnológica de publicación, búsqueda y contacto. No presta servicios personales anunciados, no representa a visitantes o anunciantes y no es parte de citas, arriendos, viajes, comunicaciones, transferencias, pagos ni acuerdos que se realicen fuera del portal."},{"id":"block-4","type":"paragraph","text":"La aprobación de un anuncio, una etiqueta o un distintivo de verificación indica únicamente que Chile3X realizó una revisión administrativa con los antecedentes disponibles en ese momento. No certifica identidad permanente, conducta futura, condiciones sanitarias, disponibilidad, legalidad de un acuerdo externo ni ausencia total de riesgos."},{"id":"extended-3","type":"paragraph","text":"Si Chile3X ofrece un servicio propio pagado de publicación, visibilidad o acceso tecnológico, responderá por ese servicio dentro de la ley y las condiciones informadas al contratar. Esa relación debe distinguirse de los acuerdos personales entre visitantes y anunciantes. La referencia a proveedores externos no excluye los deberes de Chile3X por sus propios actos, instrucciones o selección y gestión de encargados."}]},{"id":"cuentas","title":"Cuentas, credenciales y datos de registro","blocks":[{"id":"block-2","type":"list","text":"","items":["La información entregada debe ser veraz, actual y corresponder a la persona que crea la cuenta o a quien tenga autorización suficiente para actuar.","Cada persona es responsable de mantener segura su contraseña y de las acciones efectuadas desde su cuenta. Debe avisar de inmediato si detecta un acceso no autorizado.","No se permite vender, ceder, prestar ni compartir una cuenta para eludir una suspensión o permitir que otra persona se haga pasar por su titular.","Chile3X puede solicitar corrección de datos, confirmación de correo, edad, identidad, autorización o representación antes de publicar o mantener un anuncio.","Los accesos federados admitidos deben corresponder a una identidad compatible y respetar las validaciones de registro. Google se encuentra disponible; Apple y X permanecen preparados e inactivos mientras no se habiliten expresamente. Las identidades administrativas continúan separadas e ingresan mediante GitHub.","La desvinculación de un proveedor exige configurar y confirmar una contraseña de acceso. No elimina la cuenta ni deja sin verificar un correo previamente verificado. Los cambios de método de acceso se registran para su consulta por la persona titular y administración autorizada.","Los datos privados de la cuenta y sus documentos no se incorporan al anuncio. Solo se publican los campos públicos admitidos, con la autorización correspondiente; está prohibido utilizar esos campos para divulgar documentos de identidad, antecedentes de salud o datos privados de terceros."],"ordered":false},{"id":"extended-2","type":"paragraph","text":"El registro conserva constancia de las versiones de términos y privacidad aceptadas, junto con la cuenta y la fecha. Esa constancia acredita la aceptación registrada, pero no se presenta como prueba de un consentimiento independiente para cada dato sensible o finalidad opcional. No es necesario aceptar publicidad o medición opcional para abrir una cuenta."},{"id":"extended-3","type":"paragraph","text":"La persona usuaria debe facilitar solamente datos pertinentes. No debe enviar contraseñas, códigos de autenticación, claves bancarias, datos completos de tarjetas ni documentos de terceros por soporte, chat o formularios de texto libre. Si se requiere acreditar representación o identidad se indicará un método proporcionado, evitando copias completas cuando baste otra comprobación."}]},{"id":"publicaciones","title":"Publicaciones, revisión y distintivo de verificación","blocks":[{"id":"block-2","type":"paragraph","text":"Los perfiles de escort, agencia y arriendo se envían a revisión manual antes de publicarse. Chile3X puede pedir cambios, rechazar material, limitar su alcance, pausar el anuncio o retirarlo cuando incumpla estas condiciones, las reglas de publicación, la ley o criterios razonables de seguridad."},{"id":"block-4","type":"paragraph","text":"El distintivo verde de “verificado” es opcional y se concede manualmente. Refleja una comprobación adicional realizada con la información disponible al momento de la revisión; puede retirarse si los datos cambian, caducan, resultan inconsistentes o existe una alerta fundada."},{"id":"block-6","type":"paragraph","text":"La revisión del anuncio y la aprobación de sus archivos son controles distintos. Los archivos nuevos o reemplazados se someten a su revisión correspondiente; su carga no implica, por sí sola, que toda la publicación cambie de estado. El equipo puede revisar, limitar o retirar un anuncio cuando existan cambios o antecedentes que lo justifiquen."},{"id":"block-8","type":"paragraph","text":"La persona titular y administración autorizada pueden consultar una vista previa privada de anuncios no publicados. Esa vista no constituye aprobación ni permite su acceso público. Administración puede editar datos, revisar documentos privados y publicar historias por cuenta del anunciante dentro de sus permisos; estas actuaciones deben responder a una solicitud, autorización o finalidad operativa legítima y quedan registradas."},{"id":"extended-5","type":"paragraph","text":"Antes de destinar datos sensibles a una publicación debe existir una autorización expresa de su titular, con información sobre los campos, contactos, archivos y alcance público. Un alias, el difuminado parcial o la omisión del rostro no garantizan anonimato. Las autorizaciones para preparar una vista privada, publicar en el portal y difundir en otro canal son finalidades distintas; una no concede automáticamente las demás."},{"id":"extended-6","type":"paragraph","text":"La verificación de identidad no es una evaluación de salud ni una autorización para difundir documentos privados. No se debe interpretar ningún distintivo como garantía de ausencia de infecciones, consentimiento para un encuentro o evaluación sanitaria. Una revisión de documentos no permite ampliar su uso a publicidad, discriminación o decisiones ajenas a la finalidad autorizada."}]},{"id":"agencias-arriendos","title":"Reglas especiales para agencias y arriendos","blocks":[{"id":"block-2","type":"subheading","text":"Agencias","numbered":true},{"id":"block-4","type":"paragraph","text":"Una agencia solo puede vincular a una escort con autorización expresa de esa persona. La invitación debe ser aceptada por la cuenta correspondiente; está prohibido crear relaciones aparentes, reutilizar identidades o agregar personas sin consentimiento. La agencia responde por la veracidad de su información institucional y por sus propios actos, sin adquirir propiedad ni control sobre las cuentas vinculadas."},{"id":"block-6","type":"subheading","text":"Arriendos","numbered":true},{"id":"block-8","type":"paragraph","text":"Quien publica un arriendo declara tener derecho para ofrecer el espacio, entregar información veraz y cumplir las normas civiles, sanitarias, de copropiedad, seguridad y demás obligaciones aplicables. Chile3X no inspecciona inmuebles ni garantiza disponibilidad, condiciones, permisos o acuerdos entre las partes."},{"id":"block-10","type":"paragraph","text":"Las categorías de visibilidad y etiquetas propias de escorts, como VIP, Premium, Bronze, MILF, Trans, Hombres o Masajes, no se aplican a agencias ni arriendos."},{"id":"extended-6","type":"paragraph","text":"Cuando una agencia o representante aporta información de una persona natural, debe acreditar un mandato o autorización suficiente para cada uso y facilitar el ejercicio de sus derechos. La aceptación de un vínculo entre cuentas no equivale a autorizar cualquier fotografía, dato íntimo o documento. Chile3X conserva sus propias obligaciones como responsable del tratamiento que decide; no las traslada íntegramente a la agencia ni al anunciante."}]},{"id":"muestras-privadas","title":"Muestras privadas, procedencia y conversión a anuncio","blocks":[{"id":"block-1","type":"paragraph","text":"Una muestra privada permite preparar y revisar una presentación antes de crear o publicar un anuncio. No constituye una oferta pública, una cuenta de la persona representada ni una aceptación de estas condiciones por esa persona. Su preparación exige una finalidad lícita y autorización suficiente; que una fotografía o un teléfono se encuentre en otro portal no habilita por sí solo su reutilización."},{"id":"block-2","type":"paragraph","text":"La muestra y sus archivos requieren acceso autorizado o un enlace con token. Quien reciba el enlace debe mantenerlo reservado y no reenviarlo sin autorización. La protección mediante enlace reduce exposición, pero cualquier destinatario que conozca un enlace vigente podría acceder; se debe solicitar su revocación si se comparte indebidamente."},{"id":"block-3","type":"paragraph","text":"La vigencia inicial es de siete días y puede ampliarse o renovarse mediante las funciones autorizadas. El vencimiento o envío a papelera retira el acceso ordinario; la conservación en papelera y las muestras convertidas se rigen por la Política de privacidad. Convertir una muestra no reemplaza la autorización de la persona titular ni la aceptación de las condiciones aplicables por la cuenta correspondiente."}]},{"id":"obligaciones","title":"Obligaciones de quien publica","blocks":[{"id":"block-2","type":"paragraph","text":"Quien envía un anuncio declara y garantiza que:"},{"id":"block-4","type":"list","text":"","items":["es mayor de edad y actúa de forma libre, consciente y sin coacción;","la descripción, ciudad, disponibilidad, servicios, precios, contactos, viajes y demás datos son auténticos y se mantienen actualizados;","posee los derechos o autorizaciones necesarias sobre cada imagen, video, texto, marca y dato publicado;","todas las personas identificables que aparecen en el material son adultas y autorizaron expresamente su captura y publicación;","retirará o solicitará el retiro del material si pierde una autorización necesaria;","no utilizará la plataforma para controlar, explotar, amenazar, endeudar, trasladar o beneficiarse abusivamente de otra persona."],"ordered":false}]},{"id":"prohibiciones","title":"Contenido y conductas estrictamente prohibidos","blocks":[{"id":"block-2","type":"paragraph","text":"Está prohibido publicar, solicitar, enlazar, distribuir o utilizar Chile3X para:"},{"id":"block-4","type":"list","text":"","items":["cualquier contenido, servicio o interacción que involucre a una persona menor de 18 años, incluso mediante apariencia simulada, edición digital o inteligencia artificial;","trata de personas, explotación sexual, trabajo forzado, servidumbre, coacción, violencia, abuso de poder o aprovechamiento de vulnerabilidad o dependencia;","difundir imágenes o sonidos íntimos sin autorización expresa, material obtenido de forma clandestina, “revenge porn”, sextorsión o amenazas de publicación;","mostrar a una persona inconsciente, incapacitada para consentir, bajo violencia real o en una situación que razonablemente sugiera ausencia de consentimiento;","suplantar identidades, crear perfiles falsos, utilizar deepfakes o contenido sintético para atribuir actos reales a otra persona, o alterar documentos;","publicar datos privados de terceros, domicilios exactos no autorizados, documentos, teléfonos o información destinada a acosar, perseguir o extorsionar;","ofrecer actividades con animales, armas, drogas, lesiones reales, delitos o cualquier prestación prohibida por la legislación aplicable;","estafar, lavar activos, enviar spam, manipular reseñas o métricas, captar credenciales, introducir malware, vulnerar medidas de seguridad o extraer datos masivamente sin autorización;","discriminar, hostigar, amenazar o incitar violencia contra una persona o grupo."],"ordered":false},{"id":"block-6","type":"callout","text":"Ante indicios de minoría de edad, explotación, trata, violencia o difusión íntima no consentida, Chile3X puede retirar preventivamente el contenido, preservar antecedentes necesarios y colaborar con las autoridades competentes conforme a la ley."}]},{"id":"comunidad","title":"Favoritos, likes, reseñas, mensajes, Telegram, bloqueos y reportes","blocks":[{"id":"block-2","type":"paragraph","text":"Las cuentas pueden utilizar funciones de comunidad de acuerdo con su disponibilidad. Las reseñas y comentarios deben referirse a experiencias reales, expresarse con respeto y no contener datos personales, amenazas, extorsión, publicidad, acusaciones deliberadamente falsas ni contenido ilícito."},{"id":"block-4","type":"paragraph","text":"Bloquear un anuncio solo lo oculta para la cuenta que realizó la acción; no sanciona al anunciante. Reportar inicia una revisión, no determina culpabilidad. El uso coordinado de votos, likes, reportes o reseñas para manipular resultados está prohibido."},{"id":"block-6","type":"paragraph","text":"El chat interno vincula cada conversación con un anuncio y exige una cuenta activa. Está prohibido usarlo para spam, acoso, amenazas, suplantación, captación ilícita, envío de malware o intercambio de contenido ilegal. Silenciar detiene avisos; bloquear impide mensajes nuevos y mantiene el historial disponible mientras corresponda. Si una cuenta se deshabilita o elimina, su identidad visible se reemplaza por “Usuario de Chile3X” para el otro participante y no se admiten mensajes nuevos. Esta sustitución no garantiza la anonimización del contenido previo: los propios mensajes podrían contener referencias identificables."},{"id":"block-8","type":"paragraph","text":"El centro de ayuda beta, denominado “Johnny Sins”, es un bot de búsqueda guiada basado en documentación revisada del sitio. No constituye atención humana, asesoría profesional ni inteligencia artificial generativa; sus respuestas pueden contener errores y no ejecutan modificaciones de cuentas. La persona usuaria debe verificar los pasos y recurrir a los canales oficiales cuando no se resuelva su consulta. El nombre y la imagen no implican participación, afiliación ni respaldo del actor."},{"id":"block-10","type":"paragraph","text":"El foro se encuentra en una beta privada accesible exclusivamente a administración autorizada. No admite participación de usuarios generales ni constituye una sección pública. Publicar exige confirmar las normas vigentes, que pueden consultarse en su sección propia. Sus temas, respuestas y adjuntos están sujetos a las prohibiciones de estos términos: no se permite incluir documentos privados ni datos personales de terceros. Todo adjunto requiere derechos de publicación y consentimiento de las personas adultas representadas, queda pendiente de revisión y está sujeto a límites de frecuencia, tamaño y almacenamiento. Una aprobación administrativa no certifica identidad, legalidad ni ausencia de riesgos."},{"id":"block-12","type":"paragraph","text":"Las herramientas del foro permiten solicitar revisión o rectificación de mensajes, registrar decisiones de moderación y seguir temas con notificaciones internas propias, sin correos automáticos. Los adjuntos retirados, rechazados o asociados a mensajes o temas en papelera se depuran tras 30 días; las notificaciones, tras 90 días, y las denuncias cerradas, tras 180 días, conforme a la Política de privacidad y sus excepciones fundadas. Una apertura posterior requerirá informar previamente sus reglas y condiciones y revisar expresamente los permisos de acceso."},{"id":"block-14","type":"paragraph","text":"La comunidad pública de Telegram puede utilizarse sin cuenta Chile3X. El acceso al espacio privado de Miembros requiere una cuenta activa, correo verificado y vinculación voluntaria con el bot. Los mensajes quedan sujetos a las reglas de la comunidad, a las condiciones de Telegram y a moderación manual o automática por spam, fraude, amenazas, acoso, contenido ilícito o reincidencia. Una medida en Telegram no reemplaza por sí sola una decisión sobre la cuenta del sitio."}]},{"id":"medios","title":"Fotos, videos, historias y estados","blocks":[{"id":"block-2","type":"paragraph","text":"Todo material enviado queda sujeto a moderación. El sistema puede redimensionar, comprimir y convertir técnicamente archivos para su publicación. La marca de agua en fotos y videos y el difuminado de rostros en fotografías se aplican cuando se seleccionan las opciones correspondientes; el difuminado de videos no se encuentra habilitado. La preparación se realiza en el dispositivo cuando la función lo permite y se almacena el archivo final, sin conservar una segunda copia del original por ese procesamiento. Estas medidas no garantizan impedir copias ni ocultar correctamente todos los rostros; el resultado debe revisarse antes de enviarlo."},{"id":"block-4","type":"paragraph","text":"La galería del anuncio admite fotografías finales de hasta 10 MB y videos finales de hasta 12 MB y 15 segundos. Las historias admiten hasta cinco fotografías finales de 5 MB, cinco estados de texto y tres videos de hasta 12 MB y 15 segundos activos por anuncio. Los formularios informan los formatos y demás restricciones aplicables; documentos privados y otros tipos de archivo tienen controles específicos."},{"id":"block-6","type":"paragraph","text":"Las historias de fotografía, video y texto expiran públicamente a las 24 horas. Una tarea programada elimina los archivos y registros vencidos del almacenamiento activo; su ejecución puede demorarse ante errores técnicos o acumulación de tareas, sin prolongar el acceso público. Las copias transitorias de respaldo o caché se rigen por la Política de privacidad. El contenido temporal sigue sujeto a estas condiciones durante toda su existencia."}]},{"id":"exclusivo","title":"Galería de contenido exclusivo","blocks":[{"id":"block-2","type":"paragraph","text":"Cuando esté habilitada, la persona anunciante puede cargar material en una galería privada y autorizar cuentas concretas mediante su correo registrado. El material se muestra bloqueado o difuminado a quienes no tengan acceso. La autorización puede revocarse, pero no permite controlar copias que una persona autorizada haya realizado fuera del portal."},{"id":"block-4","type":"paragraph","text":"Chile3X no procesa actualmente el pago por ese acceso ni actúa como vendedor, comprador, representante o garante de acuerdos económicos externos. Solo puede subirse material propio, consentido y lícito. Está prohibido conceder acceso a menores de edad o compartir las credenciales de una cuenta autorizada."}]},{"id":"reportes","title":"Reportes, evidencias y moderación","blocks":[{"id":"block-2","type":"paragraph","text":"Una cuenta iniciada puede reportar un anuncio, explicar el motivo y adjuntar hasta el límite de evidencias informado en el formulario. Esos antecedentes son privados y se muestran al equipo autorizado y a la persona que reportó en su panel; no se publican en el anuncio."},{"id":"block-4","type":"paragraph","text":"Chile3X puede solicitar información, ocultar contenido preventivamente, dejar una publicación pendiente, rechazar cambios, desactivar cuentas, revocar verificaciones o eliminar material. La gravedad, reiteración, riesgo para terceros y colaboración durante la revisión pueden considerarse. Las solicitudes de reconsideración se reciben en el canal oficial de contacto, sin perjuicio de las denuncias que correspondan ante autoridades."}]},{"id":"propiedad","title":"Propiedad intelectual y licencia de publicación","blocks":[{"id":"block-2","type":"paragraph","text":"Cada titular conserva los derechos sobre el contenido que aporta. Al enviarlo concede a Chile3X una licencia no exclusiva, gratuita, revocable respecto de usos futuros y limitada a operar, almacenar, respaldar, adaptar técnicamente, moderar, proteger, promocionar el propio anuncio y mostrar el contenido dentro del portal y sus vistas previas."},{"id":"block-4","type":"paragraph","text":"La parte pública de un anuncio puede ser indexada por buscadores y aparecer al compartir enlaces en redes sociales. Retirar el anuncio detiene usos futuros controlados por Chile3X, pero la desindexación, cachés o copias de terceros pueden tardar y dependen de esos servicios."},{"id":"block-6","type":"paragraph","text":"Las marcas, diseño, código, textos institucionales y elementos propios de Chile3X no pueden copiarse, comercializarse ni reutilizarse sin autorización. Las reclamaciones por uso no autorizado de material se reciben en [chile3x.site@gmail.com](mailto:chile3x.site@gmail.com), indicando el contenido y la relación de quien reclama con él."},{"id":"extended-4","type":"paragraph","text":"La licencia técnica no implica renunciar a derechos de protección de datos, imagen, intimidad o autoría. No autoriza vender una base de datos, entrenar sistemas de inteligencia artificial, crear material sintético que suplante a una persona ni reutilizar contenido íntimo en campañas ajenas. La difusión fuera del portal que exceda la finalidad originalmente informada requiere la autorización o fundamento legal que corresponda."},{"id":"extended-5","type":"paragraph","text":"Ante una retirada de consentimiento o reclamación de imagen se evaluará la publicación y las copias bajo control del portal. La preservación de evidencia para una reclamación debe restringirse al expediente necesario y no permite mantener el anuncio accesible al público."}]},{"id":"contacto-externo","title":"Contactos, redes y servicios externos","blocks":[{"id":"block-2","type":"paragraph","text":"Los botones de teléfono, WhatsApp, Telegram, Instagram, Arsmate, OnlyFans y otros enlaces conducen a servicios de terceros con sus propias reglas y políticas. Chile3X no controla sus mensajes, cobros, disponibilidad, seguridad ni tratamiento de datos."},{"id":"block-4","type":"paragraph","text":"Dentro de un anuncio con contacto disponible, el panel de WhatsApp distingue y presenta primero al anunciante, seguido de los canales del equipo de Chile3X. Soporte y marketing no representan al anunciante ni coordinan sus servicios. Los contadores registran pulsaciones, no mensajes enviados ni una garantía de contacto efectivo."},{"id":"block-6","type":"paragraph","text":"Cuando una persona vincula Telegram, el bot puede comprobar su identidad del sitio, administrar invitaciones, sincronizar Novedades y aplicar las medidas descritas en las reglas. Chile3X no solicita la contraseña de Telegram. El botón de Apple permanece inactivo mientras no exista una configuración completa; si se habilita, la autenticación se realizará en los servidores de Apple y el correo asociado quedará bloqueado en Chile3X."},{"id":"block-8","type":"paragraph","text":"La agenda de viajes y los horarios son información declarada por el anunciante. Mostrar “24/7” resume una configuración de atención durante las 24 horas de los siete días y no acredita disponibilidad real en cada momento. La agenda no modifica automáticamente la ciudad principal ni constituye intermediación, transporte o garantía. Está prohibido utilizarla para captar, trasladar o explotar personas o facilitar conductas contrarias a los artículos 411 ter y 411 quáter del Código Penal u otras normas aplicables."}]},{"id":"disponibilidad","title":"Disponibilidad, mantenimiento y cambios técnicos","blocks":[{"id":"block-2","type":"paragraph","text":"Chile3X procura mantener el servicio disponible, pero puede realizar mantenimiento, corregir fallas, cambiar funciones, limitar cargas o suspender temporalmente áreas por seguridad, capacidad, cumplimiento legal o causas fuera de su control. No se garantiza funcionamiento continuo ni compatibilidad con todos los dispositivos."},{"id":"block-4","type":"paragraph","text":"Las copias de respaldo y medidas de recuperación reducen riesgos, pero no reemplazan el deber de cada anunciante de conservar sus propios archivos y antecedentes originales."}]},{"id":"pagos-futuros","title":"Estado actual y condiciones de los servicios pagados futuros","blocks":[{"id":"block-1","type":"callout","text":"**Actualmente Chile3X no integra transferencias bancarias, pasarelas de pago, billeteras ni suscripciones con cobro automático.** Estas cláusulas fijan condiciones para una eventual habilitación. Su publicación no activa cobros, no facilita una cuenta bancaria de recaudación y no autoriza a nadie a cobrar en nombre del portal."},{"id":"block-2","type":"paragraph","text":"La sola visita, el registro, la aceptación de estos términos o una etiqueta VIP, Premium o Bronze no constituyen una orden de pago. No se generará una deuda ni se transformará automáticamente un servicio gratuito en pagado. Una contratación futura requerirá información previa y una acción expresa de aceptación de la oferta concreta."},{"id":"block-3","type":"list","text":"","items":["**Oferta previa:** identificación del prestador y domicilio legal, servicio contratado, prestaciones y límites, precio total en pesos chilenos, impuestos y cargos incluidos o desglosados según corresponda, duración, fecha o condición de inicio, disponibilidad, soporte, terminación y condiciones de devolución.","**Contratación verificable:** oportunidad de revisar y corregir los datos antes de confirmar, acceso claro a las condiciones y confirmación del contrato íntegro por un medio que permita conservarlo. No se usará una casilla premarcada ni la aceptación de privacidad como autorización de cargo.","**Planes y renovaciones:** se indicará si el servicio es de pago único o periódico. La renovación y cada autorización de cargo deberán informarse y aceptarse expresamente, con un mecanismo claro para evitar renovaciones posteriores. No se establecerá un método de terminación más gravoso que el legalmente permitido.","**Activación:** dependerá del cumplimiento de las condiciones informadas y de la confirmación del pago por un canal fiable. Una captura de pantalla, un correo aparente o el retorno del navegador desde una pasarela no probarán por sí solos la recepción del dinero."],"ordered":false},{"id":"block-4","type":"paragraph","text":"Los precios y condiciones particulares aceptados integrarán el contrato. Un cambio posterior no podrá modificar retroactivamente lo ya contratado ni justificar un cobro no consentido. La moderación y las prohibiciones legales se mantendrán aunque se contrate un plan; el pago no compra una aprobación ni permite contenido ilícito."}]},{"id":"transferencias-pasarelas","title":"Transferencias y pasarelas: condiciones previas a su habilitación","blocks":[{"id":"block-1","type":"paragraph","text":"Si se habilitan transferencias, el sitio identificará al beneficiario autorizado, el canal oficial, la referencia de la orden y las condiciones de conciliación. Solo se solicitará la información necesaria para vincular el abono con la contratación. Los comprobantes no deben incluir saldos, movimientos ajenos ni claves. No se considerará pagada una orden hasta verificar el abono efectivo y su correspondencia."},{"id":"block-2","type":"paragraph","text":"Si se habilita una pasarela, se informará su identidad y el medio de pago admitido antes de continuar. Se preferirán formularios alojados o componentes tokenizados del proveedor; Chile3X no solicitará ni almacenará el número completo de tarjeta, CVV, PIN, claves bancarias ni códigos de un solo uso. La autenticación que exija el banco o la pasarela se realizará en su entorno autorizado."},{"id":"block-3","type":"paragraph","text":"Antes de activar cualquier cobro deberán aplicarse los controles de seguridad, acceso restringido, minimización, trazabilidad, confirmación y tratamiento de datos descritos en la Política de privacidad y exigidos por la ley. Deberán verificarse las autorizaciones del proveedor para este giro, el manejo de incidentes y devoluciones, y la autenticidad de las confirmaciones para evitar cobros duplicados o activaciones fraudulentas."},{"id":"block-4","type":"paragraph","text":"Un rechazo o revisión de una operación debe permitir aclarar el estado y solicitar asistencia. Los reintegros se tramitarán por un medio seguro, con verificación proporcionada y sin exigir claves. Ninguna revisión antifraude autoriza una retención indefinida del dinero o de los documentos, ni elimina los derechos frente a cobros no autorizados que resulten aplicables."},{"id":"block-5","type":"paragraph","text":"Estas previsiones se refieren a servicios propios del portal. Cualquier futura recaudación por cuenta de anunciantes, intermediación de pagos, billetera o custodia de fondos requerirá un diseño, una revisión jurídica y condiciones específicas previas; no queda habilitada por este documento."}]},{"id":"retracto-devoluciones","title":"Retracto, devoluciones y reclamos en contrataciones futuras","blocks":[{"id":"block-1","type":"paragraph","text":"Cuando exista una relación de consumo, se respetarán los derechos irrenunciables de la Ley N.º 19.496. Para servicios contratados a distancia, el retracto procede, como regla del artículo 3 bis, dentro de diez días desde la contratación y antes de la prestación del servicio, sujeto a las condiciones legales aplicables. La falta de confirmación escrita del artículo 12 A puede extender ese plazo a noventa días."},{"id":"block-2","type":"paragraph","text":"Esta cláusula no excluye el retracto. Si para un servicio futuro se decide una exclusión legalmente permitida, deberá comunicarse antes de contratar y pagar, de manera inequívoca, destacada, fácilmente accesible y junto a la información del precio, conforme al Decreto N.º 52. No bastará esconderla en estos términos. El inicio del servicio se comunicará conforme a la normativa aplicable."},{"id":"block-3","type":"paragraph","text":"Ejercido válidamente el retracto, la restitución se efectuará a la brevedad y dentro del máximo legal de cuarenta y cinco días desde su comunicación, con el alcance que corresponda a la prestación efectivamente realizada. Lo anterior no impide plazos más favorables informados al contratar ni los derechos por incumplimiento, cobros erróneos o no autorizados."},{"id":"block-4","type":"paragraph","text":"Las reclamaciones se recibirán en [chile3x.site@gmail.com](mailto:chile3x.site@gmail.com) y, si se habilita, en el canal de la orden correspondiente. Se solicitará solo la referencia y antecedentes mínimos necesarios. La atención directa no es requisito para acudir a SERNAC, tribunales u otra autoridad competente ni impone arbitraje obligatorio, una jurisdicción excluyente o una renuncia de derechos."}]},{"id":"responsabilidad","title":"Responsabilidad y seguridad personal","blocks":[{"id":"block-2","type":"paragraph","text":"Las personas usuarias deben evaluar por sí mismas cualquier contacto o acuerdo externo, proteger sus datos, evitar anticipos sospechosos y adoptar medidas razonables de seguridad. Chile3X no garantiza la identidad permanente, solvencia, ubicación, conducta, calidad, salud ni cumplimiento de otra persona."},{"id":"block-4","type":"paragraph","text":"Nada en estos términos excluye responsabilidades que no puedan limitarse conforme a la ley, derechos irrenunciables de consumidores cuando sean aplicables ni responsabilidad propia de Chile3X por dolo o culpa grave. La plataforma responderá dentro del alcance exigido por la legislación chilena."},{"id":"extended-3","type":"paragraph","text":"La persona usuaria no asume los riesgos que legalmente corresponden al operador. No se excluye responsabilidad por incumplir obligaciones propias de seguridad, protección de datos o consumo, ni se invierte en perjuicio de la persona consumidora una carga de prueba establecida por ley. Cualquier cláusula incompatible con una norma imperativa se interpretará y limitará conforme a esa norma, sin extender una exención inválida."}]},{"id":"termino","title":"Pausa, suspensión, cierre y eliminación","blocks":[{"id":"block-2","type":"paragraph","text":"La persona anunciante puede ocultar temporalmente sus publicaciones y solicitar el cierre de su cuenta mediante las funciones disponibles o el canal de soporte. Chile3X puede restringir o terminar el acceso por incumplimiento, riesgo, requerimiento de autoridad, fraude, inactividad prolongada o necesidad operativa fundada."},{"id":"block-4","type":"paragraph","text":"El cierre no elimina de inmediato antecedentes que deban conservarse para resolver reportes, prevenir abuso, ejercer o defender derechos, cumplir obligaciones legales o mantener respaldos transitorios. El tratamiento posterior se rige por la Política de privacidad."},{"id":"block-6","type":"paragraph","text":"Los plazos se detallan en la [Política de privacidad: conservación](/privacidad#conservacion), incluida la transición de la depuración ordinaria al 13 de noviembre de 2026. Son plazos operativos propios y no una autorización para mantener datos innecesarios. La información médica requiere además una finalidad legalmente admisible; su plazo técnico no legitima por sí mismo su recolección."},{"id":"block-8","type":"paragraph","text":"Una sesión del navegador no puede operar simultáneamente como cuenta pública y como identidad administrativa. Iniciar sesión en otro panel cierra la sesión anterior de ese navegador; los correos administrativos reservados no pueden utilizarse para crear o recuperar cuentas públicas. Los accesos contradictorios se rechazan y requieren una nueva autenticación."},{"id":"block-10","type":"paragraph","text":"Deshabilitar o eliminar una cuenta revoca su acceso al espacio privado de Telegram. Cuando una cuenta creada con Apple se elimine permanentemente y el proveedor esté activo, Chile3X intentará además revocar la autorización externa antes de borrar localmente la identidad."},{"id":"extended-6","type":"paragraph","text":"La pausa, ocultamiento, deshabilitación y eliminación definitiva tienen efectos distintos. El derecho a pedir supresión o bloqueo no depende de utilizar un único botón: también puede ejercerse por el canal de privacidad. Una conservación excepcional debe estar fundada, ser proporcionada y limitarse al dato necesario; no podrá invocarse una deuda o controversia para mantener un anuncio íntimo público."},{"id":"extended-7","type":"paragraph","text":"Si existiera un servicio propio pagado, las medidas sobre una cuenta deberán considerar las condiciones del contrato, las prestaciones efectivamente realizadas y las devoluciones que procedan. La cancelación del acceso no justifica por sí sola perder todo importe pagado ni mantener autorizaciones de cargo futuras."}]},{"id":"privacidad-derechos","title":"Privacidad, autorización y ejercicio de derechos","blocks":[{"id":"block-1","type":"paragraph","text":"La Política de privacidad identifica datos, finalidades, fundamentos, destinatarios, conservación, riesgos de publicación, seguridad y canales de atención. El uso del servicio no autoriza finalidades incompatibles. Las decisiones sobre datos sensibles, medición opcional y comunicaciones comerciales deben poder distinguirse de la aceptación contractual."},{"id":"block-2","type":"paragraph","text":"Es posible solicitar acceso, corrección, supresión, oposición y los demás derechos que correspondan en cada régimen temporal, retirar consentimientos y pedir revisión humana de decisiones automatizadas cuando proceda. El procedimiento y los plazos se explican en [Ejercicio de derechos](/privacidad#ejercicio). No se cobra por el uso de ese canal ni se exige aceptar una nueva política para ejercer un derecho."},{"id":"block-3","type":"paragraph","text":"Una agencia, anunciante o visitante que trate datos ajenos por su cuenta debe respetar las normas aplicables: no puede recopilar el directorio, elaborar listas de vida sexual, acosar, revender información ni reutilizar contactos para publicidad incompatible. La disponibilidad pública no elimina los derechos de la persona representada."}]},{"id":"cambios","title":"Cambios de estos términos","blocks":[{"id":"block-2","type":"paragraph","text":"Chile3X puede actualizar estas condiciones por cambios funcionales, legales, técnicos o de seguridad. La versión y fecha vigentes se mostrarán en esta página. Los cambios materiales se comunicarán con una anticipación razonable por el sitio, la cuenta o correo, salvo que una medida urgente de seguridad o una obligación legal requiera aplicación inmediata."},{"id":"block-4","type":"paragraph","text":"Cuando una modificación necesite un consentimiento nuevo, se solicitará antes de aplicar la función correspondiente. El uso posterior a la entrada en vigor no convalida cláusulas que legalmente requieran aceptación expresa."}]},{"id":"ley","title":"Legislación chilena, contacto y bibliografía","blocks":[{"id":"block-1","type":"paragraph","text":"Estas condiciones se interpretan conforme a las leyes de Chile, especialmente la Constitución, la Ley N.º 19.628, las modificaciones de la Ley N.º 21.719 desde su vigencia efectiva, la legislación de consumo cuando corresponda y las normas sobre documentos electrónicos, propiedad intelectual y responsabilidad civil y penal aplicables. Las referencias no amplían el giro del portal ni afirman una certificación de cumplimiento."},{"id":"block-2","type":"paragraph","text":"El operador es **Pedro Enrique Reyes González**, persona natural, RUT **15.771.562-3**, que opera bajo el nombre comercial **Chile3X**. Las consultas y reclamaciones pueden dirigirse a [chile3x.site@gmail.com](mailto:chile3x.site@gmail.com). La revisión por el equipo no limita acudir a tribunales, SERNAC, policías, Ministerio Público ni a la Agencia de Protección de Datos Personales desde que ejerza las atribuciones pertinentes."},{"id":"block-3","type":"sources","text":"Normativa oficial consultada el 26 de octubre de 2026","items":["[Constitución Política, artículo 19 N.º 4: vida privada y datos personales](https://www.bcn.cl/leychile/navegar?idNorma=242302)","[Ley N.º 19.628: régimen vigente hasta el 30 de noviembre de 2026](https://www.bcn.cl/leychile/navegar?idNorma=141599&idVersion=2023-05-09)","[Ley N.º 21.719 y sus disposiciones transitorias](https://www.bcn.cl/leychile/navegar?idNorma=1209272)","[Ley N.º 19.628, texto reformado con vigencia desde el 1 de diciembre de 2026: principios, derechos, consentimiento, seguridad, categorías especiales y transferencias](https://www.bcn.cl/leychile/navegar?idNorma=141599&idVersion=2026-12-01)","[Ley N.º 19.496, texto refundido por DFL N.º 3 de 2019: artículos 3 bis, 4, 12 A, 16 y 28 B, según corresponda](https://www.bcn.cl/leychile/navegar?idNorma=1160403)","[Ley N.º 19.799 sobre documentos electrónicos y firma electrónica](https://www.bcn.cl/leychile/navegar?idNorma=196640)","[Decreto N.º 6 de 2021, Reglamento de Comercio Electrónico](https://www.bcn.cl/leychile/navegar?idNorma=1165504)","[Decreto N.º 52 de 2022, publicado en 2024: comunicación de exclusión del retracto](https://www.bcn.cl/leychile/navegar?idNorma=1206144)"]},{"id":"block-4","type":"sources","text":"Bibliografía de apoyo y criterio de uso","items":["Fernández, Fernando / AltLegal Ltda. El Registro de Actividades de Tratamiento (RAT): Manual para entrevistadores, 14 de agosto de 2026, versión 1.0, 112 páginas. Fernández Acevedo, Fernando / AltLegal: El Registro de Actividades de Tratamiento (RAT), taller MUTUCAR, 9 de septiembre de 2026. Materiales aportados para esta revisión; no constituyen instrucciones de la autoridad ni una certificación del sitio.","Fernández, Fernando / AltLegal Ltda. (2026). Protección de datos personales aplicado al trabajo universitario: Principios, derechos y obligaciones de la Ley N.º 21.719; y Taller de aplicación: Protección de datos personales en la universidad. Versiones UCN y Universidad de Talca identificadas en los archivos como 21 de agosto y 7 de octubre de 2026. Los supuestos universitarios se utilizan solo en cuanto son pertinentes al directorio.","Fernández, Fernando / AltLegal Ltda. (2026). Protección de datos personales: un imperativo estratégico para la educación superior, Universidad de Talca; archivo identificado como 6 de octubre de 2026. Referencia organizativa y de gestión del riesgo.","Comisión Asesora Ministerial para la Implementación de la Ley N.º 21.719 (2025–2026). Informes y recomendaciones incluidos en la colección aportada, especialmente el Cuarto Informe de 16 de enero de 2026. Son antecedentes consultivos, distintos de una norma vigente o una resolución de la Agencia."]},{"id":"block-5","type":"paragraph","text":"Los textos legales oficiales prevalecen sobre las presentaciones y los ejemplos. Las guías extranjeras y los materiales de educación superior se consideran referencias de buenas prácticas; no se convierten automáticamente en obligaciones chilenas ni acreditan que sus autores asesoren, aprueben o certifiquen Chile3X."}]}]}' WHERE document_id='terms';

INSERT INTO _legal_release_20261026(document_id,previous_json) VALUES('privacy','{"title":"Política de privacidad y tratamiento de datos","description":"Cómo Chile3X recopila, utiliza, protege, publica y elimina datos de visitantes, cuentas y anunciantes.","summary":"Esta política informa los datos tratados por Chile3X, sus finalidades, la información que puede hacerse pública y los mecanismos para ejercer los derechos de sus titulares. Describe el funcionamiento actual del directorio y distingue los datos públicos de los archivos privados.","notice":"**Canal de privacidad:** las solicitudes de acceso, rectificación, eliminación, bloqueo y consultas se reciben en [chile3x.site@gmail.com](mailto:chile3x.site@gmail.com). No deben enviarse contraseñas ni documentos completos por correo; si se requieren antecedentes, el equipo deberá indicar un canal adecuado.","sections":[{"id":"responsable","title":"Responsable, contacto y alcance","blocks":[{"id":"block-2","type":"paragraph","text":"**Chile3X**, nombre comercial del portal disponible en **chile3x.cl**, es responsable del tratamiento descrito en esta política. El canal oficial para consultas y ejercicio de derechos es [chile3x.site@gmail.com](mailto:chile3x.site@gmail.com)."},{"id":"block-4","type":"paragraph","text":"Esta política se aplica a visitantes, personas registradas, anunciantes, agencias, responsables de arriendos, personas que aparecen en publicaciones, quienes reportan contenido y quienes interactúan con las funciones del sitio. Los servicios externos enlazados, como WhatsApp, Telegram, Instagram, Arsmate u OnlyFans, tienen políticas propias."}]},{"id":"principios","title":"Principios que aplicamos","blocks":[{"id":"block-2","type":"paragraph","text":"Chile3X procura tratar datos de forma lícita, leal y transparente; limitar su uso a finalidades informadas; solicitar solo lo necesario; mantenerlos razonablemente actualizados; protegerlos frente a accesos no autorizados y conservarlos únicamente mientras exista una finalidad legítima o una obligación aplicable."},{"id":"block-4","type":"paragraph","text":"No vendemos bases de datos personales. Tampoco utilizamos documentos de identidad, antecedentes médicos, mensajes de reportes ni contenido privado para publicidad dirigida."}]},{"id":"datos","title":"Categorías de datos que tratamos","blocks":[{"id":"block-2","type":"subheading","text":"Visitantes","numbered":true},{"id":"block-4","type":"list","text":"","items":["dirección IP, fecha y hora, ruta solicitada, navegador, dispositivo, registros de error y señales técnicas de seguridad;","confirmación de mayoría de edad, preferencias de privacidad y datos mínimos para mantener la sesión;","datos generales de navegación y eventos únicamente con consentimiento de medición opcional."],"ordered":false},{"id":"block-6","type":"subheading","text":"Cuentas","numbered":true},{"id":"block-8","type":"list","text":"","items":["correo electrónico, nombre visible, nombre completo opcional, tipo y número de documento, país del documento extranjero cuando corresponda, fecha de nacimiento, ciudad y teléfono opcional;","contraseña protegida mediante un resumen criptográfico; Chile3X no almacena contraseñas en texto legible;","estado de verificación del correo, rol, estado de la cuenta, fechas de creación y actividad administrativa;","historial de cambios en métodos de acceso y desvinculación de proveedores, sin contraseñas ni secretos legibles."],"ordered":false},{"id":"block-10","type":"subheading","text":"Anuncios","numbered":true},{"id":"block-12","type":"list","text":"","items":["tipo de perfil, nombre público, alias, URL personalizada, ciudad y región, descripción, características, servicios, idiomas, horarios, precios, agenda de viajes y disponibilidad;","teléfono, WhatsApp y las redes o plataformas que el anunciante decida publicar;","foto de perfil, galería, videos, historias, estados, archivos privados y contenido exclusivo;","estado de publicación, revisión, verificación, moderación, pausa y relaciones autorizadas entre agencias y escorts."],"ordered":false},{"id":"block-14","type":"subheading","text":"Interacciones y seguridad","numbered":true},{"id":"block-16","type":"list","text":"","items":["favoritos, likes, bloqueos, reseñas, comentarios y su estado de moderación;","reportes, motivo, texto y capturas de evidencia, además de las actuaciones administrativas asociadas;","visualizaciones de anuncios y clics en botones de contacto, agrupados por fecha y tipo de acción, incluyendo el número agregado de pulsaciones. Solo con consentimiento de medición, un clic de WhatsApp puede asociarse a la cuenta iniciada y agregar país, región o ciudad aproximada entregada por Cloudflare, tipo de dispositivo y ruta de origen. Sin ese permiso se conserva únicamente un identificador opaco para el conteo diario y nunca se guarda la IP en ese registro;","mensajes privados enviados dentro de Chile3X, anuncio de origen, participantes, fecha, estado de lectura, silencio y bloqueos necesarios para mantener el historial y prevenir abuso;","última actividad reciente de cuentas con anuncios, utilizada únicamente para mostrar un indicador temporal “Online”; el público no recibe la fecha exacta;","si se vincula Telegram: identificador numérico, usuario y nombre que Telegram comparte, estado de vinculación y membresía, invitaciones, medidas de moderación y registros técnicos necesarios para operar el bot;","si se elige Apple una vez habilitado: identificador estable, correo verificado —incluido un posible correo privado de retransmisión—, nombre compartido la primera vez y autorización cifrada necesaria para revocar el acceso al eliminar la cuenta;","actuaciones administrativas: identidad de quien intervino, fecha, operación, elemento afectado, resultado y cambios relevantes. Incluyen aprobación de archivos, modificaciones de anuncios, publicación de historias por administración y configuración. No se duplican archivos de identidad, contraseñas, secretos ni cuerpos de historias en esos registros;","en el foro privado beta: identificador y nombre administrativo de autoría, sección, título, texto, fechas, estados de edición y moderación, versión de las normas aceptadas, declaración de derechos y consentimiento para adjuntos, temas seguidos, notificaciones internas propias y denuncias con su decisión. Esta información no se publica ni se ofrece a usuarios generales; no se deben cargar documentos privados."],"ordered":false}]},{"id":"sensibles","title":"Datos sensibles, íntimos y de especial protección","blocks":[{"id":"block-2","type":"paragraph","text":"Por la naturaleza del directorio, una publicación puede revelar o permitir inferir información sobre vida sexual, identidad o expresión de género, preferencias, apariencia y salud. Además, un anunciante puede cargar voluntariamente antecedentes médicos o material íntimo. Chile3X trata estas categorías con acceso restringido y para las finalidades concretas descritas en esta política."},{"id":"block-4","type":"paragraph","text":"Publicar una etiqueta, descripción o imagen es una decisión de la persona titular del anuncio. Los documentos de identidad, fechas de nacimiento, antecedentes médicos, reportes y galerías exclusivas **no se hacen públicos por defecto**. La persona puede retirar contenido público o solicitar su revisión, sin afectar tratamientos anteriores realizados lícitamente."}]},{"id":"origen","title":"De dónde obtenemos los datos","blocks":[{"id":"block-2","type":"paragraph","text":"Recibimos datos directamente de la persona que visita, se registra, publica, comenta o reporta; de una agencia cuando invita a vincular un perfil, sujeto a aceptación de la escort; del funcionamiento técnico del sitio; y de proveedores que confirman entregas de correo, seguridad o funcionamiento."},{"id":"block-4","type":"paragraph","text":"Si alguien entrega datos de otra persona, declara tener autorización suficiente y debe informarle este tratamiento. Chile3X puede solicitar prueba de esa autorización y eliminar el contenido si no se acredita."}]},{"id":"finalidades","title":"Para qué utilizamos la información","blocks":[{"id":"block-2","type":"list","text":"","items":["crear, autenticar, recuperar, administrar, suspender o cerrar cuentas;","comprobar mayoría de edad y, cuando corresponda, revisar identidad o antecedentes voluntarios;","crear borradores, moderar cambios, publicar, ordenar, buscar, pausar y mostrar anuncios;","gestionar historias, galerías, medios, relaciones agencia–escort y accesos exclusivos;","habilitar favoritos, likes, reseñas, comentarios, mensajería privada, bloqueos, reportes y paneles de rendimiento;","ordenar anuncios según la ciudad o comuna de cobertura seleccionada manualmente; la persona usuaria puede borrar esa preferencia y volver a Todo Chile. Esta función no solicita coordenadas GPS;","vincular voluntariamente Telegram, administrar el acceso a Miembros, sincronizar Novedades, moderar la comunidad y avisar al equipo sobre medidas relevantes;","enviar correos transaccionales como verificación, recuperación, aprobación, rechazo, suspensión y avisos importantes de la cuenta;","prevenir fraude, spam, suplantación, explotación, contenido ilícito, ataques y uso indebido;","resolver solicitudes, cumplir obligaciones legales, colaborar con autoridades competentes y ejercer o defender derechos;","medir y mejorar el sitio con datos generales cuando exista consentimiento para Analytics."],"ordered":false}]},{"id":"bases","title":"Fundamentos del tratamiento","blocks":[{"id":"block-2","type":"paragraph","text":"Según el dato y la finalidad, el tratamiento se apoya en el consentimiento de su titular; la ejecución de las funciones solicitadas al crear una cuenta o publicación; el cumplimiento de obligaciones legales; y la necesidad de proteger la seguridad, prevenir abuso y ejercer o defender derechos, dentro de los límites admitidos por la legislación aplicable."},{"id":"block-4","type":"paragraph","text":"El consentimiento para medición es separado y opcional. La carga voluntaria de documentos médicos o material íntimo requiere una decisión afirmativa de quien lo aporta y puede retirarse para usos futuros. Cuando la ley exija una autorización específica adicional, Chile3X la solicitará antes del tratamiento correspondiente."}]},{"id":"publicos","title":"Perfiles públicos, buscadores y redes sociales","blocks":[{"id":"block-2","type":"paragraph","text":"Una publicación aprobada puede mostrar su nombre público, alias, ciudad, descripción, atributos, disponibilidad, precios, agenda, contactos, imágenes, videos, historias, distintivos, reseñas aprobadas y demás campos que el anunciante haya destinado al perfil público."},{"id":"block-4","type":"paragraph","text":"Las páginas públicas pueden ser encontradas por buscadores, guardadas en caché y generar vistas previas al compartir enlaces. Incluso después de despublicar o modificar una página, Google, redes sociales y otros terceros pueden tardar en actualizar o eliminar sus copias. Chile3X puede solicitar una actualización, pero no controla esos plazos."},{"id":"block-6","type":"paragraph","text":"No publicamos el número de documento, fecha de nacimiento, nombre legal opcional, teléfono privado de la cuenta, carnet, antecedentes médicos ni evidencia de reportes, salvo que la propia persona incorpore voluntariamente un dato equivalente en un campo público."}]},{"id":"documentos","title":"Documentos de identidad y antecedentes médicos opcionales","blocks":[{"id":"block-2","type":"paragraph","text":"Una persona anunciante puede adjuntar voluntariamente imágenes o PDF de identidad y/o antecedentes médicos para revisión interna. Estos archivos se almacenan de forma privada, no tienen una URL pública de listado, no se indexan y solo pueden ser consultados por la persona dueña del anuncio y administradores autorizados que los necesiten para revisar."},{"id":"block-4","type":"paragraph","text":"Un archivo nuevo puede reemplazar al anterior y la persona puede eliminarlo desde las funciones disponibles o pedir su retiro. Chile3X no diagnostica, no certifica vigencia médica ni garantiza que un documento refleje el estado actual de una persona. El resultado de una revisión puede conservarse separadamente como registro de moderación."},{"id":"block-6","type":"paragraph","text":"El acceso a documentos y las actuaciones de carga, reemplazo o eliminación se registran para trazabilidad. El historial no contiene una segunda copia del documento. Los permisos administrativos se asignan por función; disponer de acceso general al panel no autoriza por sí solo la consulta de todos los archivos privados."}]},{"id":"exclusivo","title":"Galería privada y autorizaciones de acceso","blocks":[{"id":"block-2","type":"paragraph","text":"El material exclusivo permanece bloqueado para el público. La persona dueña del anuncio administra el acceso añadiendo el correo de una cuenta registrada. Para operar la función tratamos la relación entre anuncio, cuenta autorizada, archivos y fechas relevantes."},{"id":"block-4","type":"paragraph","text":"La persona anunciante es responsable de confirmar que quien autoriza es adulta y de retirar el acceso cuando corresponda. Aunque Chile3X aplica controles técnicos, ninguna medida puede impedir por completo capturas o copias realizadas por alguien que recibió acceso legítimo. No utilizamos esa galería para entrenar sistemas de inteligencia artificial ni para publicidad."}]},{"id":"comunidad","title":"Reseñas, Telegram, bloqueos, reportes y evidencias","blocks":[{"id":"block-2","type":"paragraph","text":"Las reseñas o comentarios aprobados por el anunciante pueden mostrar el nombre visible de su autor y su contenido. Antes de aprobarse solo pueden consultarlos su autor, el propietario del anuncio y administración. El autor puede retirar su reseña pendiente; el anunciante puede aprobarla, rechazarla o eliminarla, y administración puede consultarla o eliminarla. Favoritos, bloqueos y listas personales no se muestran públicamente. Los reportes y sus capturas son privados y accesibles para el equipo autorizado y para la cuenta que los envió dentro de su panel."},{"id":"block-4","type":"paragraph","text":"Podemos utilizar esos antecedentes para investigar, contactar a las partes cuando sea seguro y necesario, moderar, preservar evidencia, prevenir reiteración y responder a una autoridad. No revelaremos la identidad de quien reporta al perfil denunciado salvo consentimiento, obligación legal o necesidad fundada de defensa, aplicando minimización."},{"id":"block-6","type":"paragraph","text":"Vincular Telegram es opcional. El sitio conserva la relación entre la cuenta y el identificador que entrega Telegram para comprobar acceso, crear invitaciones individuales y aplicar o retirar medidas. Los mensajes procesados por el bot pueden conservarse temporalmente para evitar duplicados, detectar envíos masivos o spam y ejecutar las tareas pendientes; una evidencia breve y la medida aplicada pueden mantenerse mientras sea necesario para revisar el caso y prevenir reincidencia. Desvincular, deshabilitar o eliminar la cuenta retira el acceso a Miembros, pero Telegram puede conservar mensajes conforme a sus propias reglas."},{"id":"block-8","type":"paragraph","text":"El chat interno requiere sesión. Cada participante puede silenciar o bloquear la conversación. Si una de las cuentas se deshabilita o elimina, la otra puede conservar el texto del historial, pero Chile3X sustituye la identidad visible de la persona retirada por “Usuario de Chile3X” y bloquea mensajes nuevos; las relaciones directas con la cuenta eliminada se desprenden de la conversación. Si ya no queda ningún participante con acceso, la conversación se elimina. Los indicadores de no leído y los avisos del navegador se usan solo para comunicar mensajes; Chile3X puede aplicar límites automáticos de frecuencia para reducir spam. No deben enviarse contraseñas, códigos, documentos ni datos bancarios."},{"id":"block-10","type":"paragraph","text":"La sustitución del nombre de una cuenta no anonimiza automáticamente el texto de sus mensajes. Las referencias identificables incorporadas en conversaciones se evalúan conforme a los derechos aplicables y a la finalidad de conservación del historial."},{"id":"block-12","type":"paragraph","text":"El centro de ayuda “Johnny Sins” funciona mediante búsqueda guiada en documentación revisada. Las consultas y valoraciones se mantienen únicamente en la memoria de la pestaña durante la visita; no se guardan como conversación en la base de datos ni se envían a un proveedor de IA generativa. Los enlaces de ayuda pueden referirse a anuncios pertenecientes a la cuenta, consultados con su sesión. Al abrir un WhatsApp de soporte, no se adjunta automáticamente la conversación. No deben ingresarse contraseñas, códigos, documentos ni datos privados de terceros."},{"id":"block-14","type":"paragraph","text":"El foro privado beta se utiliza para desarrollo y pruebas administrativas. Sus contenidos y archivos solo pueden ser consultados por administración habilitada para el foro. Los adjuntos requieren declaración de autorización y consentimiento, están sujetos a cuotas y quedan pendientes de revisión; esto no equivale a una certificación de identidad o legalidad. Las notificaciones se limitan a temas seguidos y a su destinatario; no se envían correos automáticos. Archivar una sección o enviar un tema a papelera no equivale a borrar inmediatamente sus datos. Las denuncias permiten solicitar revisión y rectificación; sus decisiones quedan registradas, sin duplicar los textos de las respuestas en la auditoría. Los contadores de frecuencia ayudan a limitar cargas y publicaciones abusivas."}]},{"id":"medicion","title":"Cookies, almacenamiento local y medición opcional","blocks":[{"id":"block-2","type":"subheading","text":"Funciones necesarias","numbered":true},{"id":"block-4","type":"paragraph","text":"Utilizamos cookies o almacenamiento equivalente para mantener la sesión, recordar la confirmación de mayoría de edad, conservar preferencias de privacidad, proteger formularios, limitar abuso, recordar historias vistas y operar funciones solicitadas. Estas tecnologías son necesarias para que ciertas partes del sitio funcionen y no se utilizan para publicidad conductual."},{"id":"block-6","type":"subheading","text":"Inicio de sesión con Google","numbered":true},{"id":"block-8","type":"paragraph","text":"Si se elige continuar con Google, recibimos el identificador estable de la cuenta de Google, el correo verificado y el nombre que Google comparte. Usamos el identificador y el correo para comprobar la identidad, vincular o crear la cuenta y evitar accesos duplicados; el nombre solo completa inicialmente campos editables durante el registro."},{"id":"block-10","type":"paragraph","text":"No solicitamos acceso a Gmail, Drive, contactos, archivos ni calendario, y no almacenamos tokens de acceso de Google. El correo queda vinculado y no puede modificarse desde la cuenta. Si abandonas el registro, los datos del intento se eliminan automáticamente al vencer el plazo breve de seguridad."},{"id":"block-12","type":"paragraph","text":"La persona titular puede desvincular un proveedor desde Mis datos después de configurar y confirmar una contraseña. Esto no elimina la cuenta ni revierte la verificación de su correo. Conservamos un historial de cambios de acceso, consultable por la persona titular y administración autorizada, para proteger la cuenta."},{"id":"block-14","type":"subheading","text":"Inicio de sesión con Apple preparado, aún inactivo","numbered":true},{"id":"block-16","type":"paragraph","text":"Chile3X muestra un botón de Apple deshabilitado mientras el proveedor no se encuentre habilitado con una configuración completa. En ese estado no se abre Apple ni se le envían datos. Si se habilita en el futuro y la persona elige utilizarlo, recibiremos el identificador estable, correo verificado y, únicamente en la primera autorización, el nombre que Apple comparta. Esos nombres solo completarán campos editables del registro; el correo quedará bloqueado."},{"id":"block-18","type":"paragraph","text":"El flujo rechazará identidades incompatibles, incluido un correo vinculado a otro proveedor o a una identidad administrativa. La autorización de larga duración que Apple entregue se almacenará cifrada y se utilizará para revocarla cuando corresponda, incluida la eliminación permanente de la cuenta. Chile3X no recibirá la contraseña de Apple ni acceso a iCloud, fotos, contactos o archivos."},{"id":"block-20","type":"subheading","text":"Google Tag Manager y Google Analytics","numbered":true},{"id":"block-22","type":"paragraph","text":"Los WhatsApp del equipo usan contadores internos agregados por día, área y acceso: aperturas del panel y clics para abrir WhatsApp. No guardan IP, cuenta, número del visitante ni el contenido de mensajes, y no acreditan que se haya enviado un mensaje. Son independientes de los contactos de anunciantes."},{"id":"block-24","type":"paragraph","text":"El contacto del anunciante destacado dentro del panel de WhatsApp utiliza el registro de contactos del anuncio, no el contador del equipo. El contador de pulsaciones de WhatsApp del anuncio es visible únicamente para administración autorizada. El equipo no recibe el contenido de las conversaciones mantenidas en WhatsApp."},{"id":"block-26","type":"paragraph","text":"La medición es opcional y solo se carga cuando la persona selecciona **“Aceptar medición”** en el aviso de privacidad. Con esa autorización se miden visitas y acciones generales como registros, envíos de anuncios, clics de contacto, favoritos, likes y reseñas para entender el uso y mejorar Chile3X."},{"id":"block-28","type":"paragraph","text":"No configuramos el envío a Google de nombres, correos, teléfonos, RUT, direcciones, archivos privados, texto libre ni identificadores internos de perfiles como parámetros de Analytics. Google puede tratar información técnica como dirección IP, navegador, dispositivo y señales de interacción conforme a sus propias condiciones y medidas disponibles."},{"id":"block-30","type":"paragraph","text":"Al seleccionar **“Solo necesarias”**, el sitio seguirá funcionando sin cargar Google Tag Manager ni Google Analytics. La elección puede retirarse o modificarse en cualquier momento; el cambio no invalida el tratamiento anterior basado en consentimiento."},{"id":"block-32","type":"paragraph","text":"[Cambiar mi elección de medición →](/privacidad?medicion=editar#medicion)"},{"id":"block-34","type":"subheading","text":"Inicio de sesión con X preparado, aún inactivo","numbered":true},{"id":"block-36","type":"paragraph","text":"Mientras el acceso con X esté deshabilitado no se abre ese proveedor ni se le envían datos. Si se habilita y la persona elige utilizarlo, recibiremos su identificador estable, nombre, nombre de usuario y el correo confirmado que X autorice compartir. Si no entrega un correo confirmado, la persona deberá completar y verificar uno mediante el proceso del sitio. El nombre solo completa campos editables del registro."},{"id":"block-38","type":"paragraph","text":"No solicitamos permiso para publicar, enviar mensajes privados ni acceder a mensajes. El token se utiliza únicamente para obtener la identidad y se solicita su revocación al terminar; no se almacena como credencial permanente. X podrá desvincularse con los mismos controles de contraseña e historial que los demás proveedores."},{"id":"block-40","type":"subheading","text":"Mapas referenciales de Google Maps","numbered":true},{"id":"block-42","type":"paragraph","text":"Los anuncios incluyen un mapa referencial de su ciudad, que se carga de forma diferida. Solo enviamos el nombre de la ciudad, región y país: no enviamos el nombre del anunciante, su cuenta, dirección, notas de ubicación ni coordenadas privadas. Al cargarse el mapa o abrir Maps, Google puede recibir información técnica del navegador y aplicar sus propias condiciones y política de privacidad. No solicitamos la ubicación de la persona visitante para mostrar estos mapas."}]},{"id":"proveedores","title":"Proveedores tecnológicos y transferencias internacionales","blocks":[{"id":"block-2","type":"paragraph","text":"Para operar Chile3X utilizamos proveedores que tratan datos por cuenta del portal o prestan infraestructura bajo sus propios términos:"},{"id":"block-4","type":"list","text":"","items":["**Cloudflare:** alojamiento del sitio, base de datos, almacenamiento de archivos, red de entrega, certificados, seguridad y Turnstile para combatir bots;","**Google:** autenticación cuando se elige “Continuar con Google”, correo transaccional, mapas referenciales de ciudades y, solo con consentimiento, Google Tag Manager y Google Analytics;","**Telegram:** comunidad pública, vinculación voluntaria de cuentas, invitaciones a Miembros, Novedades y moderación mediante el bot;","**Apple:** solo si el proveedor llega a habilitarse y la persona lo elige, autenticación y revocación de la autorización asociada;","**X:** solo si el acceso llega a habilitarse y la persona lo elige, autenticación e identidad autorizada para crear o vincular su cuenta;","**proveedores de navegador, sistema operativo o redes externas:** únicamente cuando la persona utiliza esas aplicaciones o sigue un enlace."],"ordered":false},{"id":"block-6","type":"paragraph","text":"Estos servicios pueden procesar o respaldar información fuera de Chile. Chile3X procura escoger proveedores reconocidos, limitar los datos enviados, configurar accesos y aplicar salvaguardas contractuales y técnicas razonables. La ubicación de la infraestructura puede cambiar sin que ello signifique una venta de datos."}]},{"id":"autoridades","title":"Cuándo podemos comunicar datos","blocks":[{"id":"block-2","type":"paragraph","text":"Podemos comunicar la información mínima necesaria a proveedores que operan el servicio; a asesores sujetos a deberes de confidencialidad; a autoridades judiciales, policiales, administrativas o al Ministerio Público ante una orden o requerimiento válido; o cuando sea necesario para denunciar o prevenir una amenaza seria, explotación, trata, abuso de menores, difusión íntima no consentida, fraude o ataque."},{"id":"block-4","type":"paragraph","text":"No entregamos bases de datos a anunciantes ni permitimos que una agencia acceda a los documentos privados de una escort por el solo hecho de estar vinculadas. Una reorganización futura del negocio deberá proteger los datos, informar el cambio de responsable cuando corresponda y respetar los derechos de sus titulares."}]},{"id":"conservacion","title":"Conservación, publicación temporal y eliminación","blocks":[{"id":"block-2","type":"paragraph","text":"Chile3X establece los siguientes plazos operativos propios, atendiendo a la finalidad y sensibilidad de cada dato. No se presentan como plazos generales exigidos por una ley ni impiden atender antes una solicitud de eliminación procedente."},{"id":"block-4","type":"list","text":"","items":["**Cuenta, anuncios y medios ordinarios:** mientras la persona mantenga su cuenta y publicaciones, incluidas las pausadas o recuperables. Deshabilitar no equivale a eliminar. La eliminación definitiva retira los datos operativos y el acceso al contenido; los archivos asociados se borran al completar el proceso o mediante reintentos restringidos. No se conservan originales adicionales por aplicar marca de agua.","**Historias de fotografías, videos y texto:** 24 horas desde su publicación. La limpieza de registros y archivos se ejecuta normalmente en el siguiente ciclo de cinco minutos. Ante una falla se reintenta sin prolongar su acceso público.","**Archivos de identidad:** hasta 90 días desde su última carga o reemplazo. **Exámenes y certificados médicos:** hasta 30 días desde su última carga o reemplazo. Después se restringe su consulta y se elimina el archivo; el resultado y fecha de la revisión pueden mantenerse mientras exista el anuncio, sin conservar el documento original ni constituir una garantía de salud.","**Reportes y pruebas adjuntas:** durante la tramitación y hasta 180 días después de su resolución o desestimación. Los casos pendientes no se eliminan por el mero transcurso de ese plazo.","**Conversaciones internas:** hasta 365 días después del último mensaje, salvo una conservación excepcional fundada. La eliminación de una cuenta puede dejar a la otra persona participante su conversación con la identidad desvinculada; no autoriza conservar indefinidamente ese historial.","**Foro beta privado:** los temas y textos se mantienen mientras se utilicen para el desarrollo o la moderación de la beta, sujetos a solicitudes de eliminación procedentes. Los adjuntos retirados, rechazados o asociados a mensajes o temas en papelera se eliminan al cumplir 30 días en ese estado. Las notificaciones internas se conservan hasta 90 días; las denuncias cerradas, hasta 180 días desde la decisión. Los contadores de frecuencia se depuran tras un día sin actividad. La constancia de aceptación de normas y los seguimientos se mantienen mientras la cuenta participe o siga el tema; dejar de seguirlo elimina ese seguimiento.","**Auditoría administrativa:** hasta 365 días desde cada actuación. **Diagnósticos operativos propios:** hasta 30 días. Los registros de sesiones vencidas se depuran hasta 30 días después de su vencimiento; los enlaces de acceso o recuperación no amplían su vigencia al permanecer transitoriamente registrados.","**Historial de correos transaccionales:** hasta 90 días desde cada intento. Registra destinatario, cuenta asociada cuando exista, asunto, tipo, fecha, servicio utilizado y resultado técnico. Su consulta se restringe a administradores autorizados para gestionar cuentas, auditoría y datos privados. No conserva el cuerpo del mensaje, contraseñas ni enlaces o tokens de recuperación. La aceptación por el servicio de envío no acredita recepción, lectura ni entrega en la bandeja principal. La eliminación definitiva de una cuenta retira los registros asociados y los del correo registrado.","**Constancia mínima de eliminación de cuenta:** hasta 180 días. Contiene una huella del correo y los datos mínimos de la eliminación, no el perfil, documentos ni medios; una huella se trata como dato seudonimizado, no como anonimato absoluto.","**Respaldos automáticos de la base de datos:** la ventana técnica de recuperación de Cloudflare D1 es de 7 a 30 días según el plan del proveedor. Una eliminación no borra simultáneamente cada estado de recuperación. Esos respaldos no se utilizan para volver a publicar contenido eliminado; al restaurar se deben reaplicar eliminaciones y vencimientos."],"ordered":false},{"id":"block-6","type":"paragraph","text":"La política se aplica desde el 14 de octubre de 2026. La depuración ordinaria de los plazos no temporales comienza el 13 de noviembre de 2026, con una transición de 30 días para los datos existentes. Esto no cambia el vencimiento de historias ni posterga las solicitudes de eliminación definitiva realizadas mediante las funciones del sitio."},{"id":"block-8","type":"paragraph","text":"Una orden válida, una investigación documentada o la necesidad concreta de ejercer o defender derechos puede justificar conservar únicamente los antecedentes indispensables por un período mayor. La conservación excepcional se registra, se restringe al caso y debe revisarse al cesar su fundamento. Los errores de almacenamiento pueden requerir reintentos: el contenido afectado no vuelve a quedar accesible por ese motivo."}]},{"id":"derechos","title":"Derechos de la persona titular","blocks":[{"id":"block-2","type":"paragraph","text":"De acuerdo con la Ley N.º 19.628 vigente, la persona titular puede solicitar información y acceso a sus datos, su rectificación cuando sean inexactos o estén desactualizados, su eliminación o cancelación cuando proceda y el bloqueo de determinados tratamientos en los casos legales."},{"id":"block-4","type":"paragraph","text":"La Ley N.º 21.719 prevé su entrada en vigor el **1 de diciembre de 2026**, conforme al texto legal publicado consultado para esta versión. Refuerza el marco chileno e incorpora derechos de acceso, rectificación, supresión, oposición, portabilidad y bloqueo temporal, junto con reglas sobre decisiones automatizadas. Su aplicación se realizará conforme a la vigencia y exigencias legales efectivas; una propuesta de modificación de plazos no altera por sí sola la ley publicada."},{"id":"block-6","type":"paragraph","text":"Estos derechos no son absolutos: una solicitud puede limitarse cuando sea necesario conservar antecedentes para obligaciones legales, seguridad, derechos de terceros, libertad de expresión, investigación de ilícitos o defensa de reclamaciones, explicando el fundamento aplicable."}]},{"id":"ejercicio","title":"Ejercicio de los derechos","blocks":[{"id":"block-2","type":"paragraph","text":"La persona titular puede editar parte de su información desde [Mi cuenta](/mi-cuenta) o presentar una solicitud en [chile3x.site@gmail.com](mailto:chile3x.site@gmail.com) indicando:"},{"id":"block-4","type":"list","text":"","items":["el derecho o solicitud que desea ejercer;","el correo asociado a su cuenta y los datos necesarios para ubicar el anuncio;","una explicación clara y, si corresponde, el dato correcto o el contenido cuya eliminación solicitas."],"ordered":false},{"id":"block-6","type":"paragraph","text":"Podemos verificar la identidad mediante el método menos invasivo razonablemente disponible antes de entregar o modificar información. No debe enviarse una contraseña. Las solicitudes se responderán dentro de los plazos de la ley vigente y serán gratuitas en los casos legalmente previstos."},{"id":"block-8","type":"paragraph","text":"También puede retirarse el consentimiento de medición desde esta página, revocarse el acceso a la galería exclusiva, ocultarse un anuncio, eliminarse historias o solicitarse el cierre de la cuenta mediante las opciones disponibles. Si la respuesta resulta insatisfactoria, la persona titular puede acudir a tribunales o a la autoridad competente, incluida la Agencia de Protección de Datos Personales una vez que ejerza sus atribuciones."}]},{"id":"seguridad","title":"Medidas de seguridad y respuesta a incidentes","blocks":[{"id":"block-2","type":"paragraph","text":"Aplicamos controles de acceso por rol y titularidad, almacenamiento privado para archivos sensibles, conexiones cifradas HTTPS, contraseñas resumidas criptográficamente, validación de formularios, protección anti-bot, registros de seguridad, copias de respaldo y revisión administrativa."},{"id":"block-4","type":"paragraph","text":"Ningún sistema conectado a Internet es infalible. Si detectamos un incidente que afecte datos personales, investigaremos, limitaremos el daño, preservaremos evidencia y notificaremos a personas o autoridades cuando la ley lo exija o sea razonablemente necesario para reducir riesgos. Puedes informar una vulnerabilidad sin explotar ni divulgar datos ajenos escribiendo al canal oficial."}]},{"id":"menores","title":"Protección de niñas, niños y adolescentes","blocks":[{"id":"block-2","type":"paragraph","text":"Chile3X no está dirigido a menores de 18 años y no acepta su registro, publicación ni aparición en material. Si tomamos conocimiento o tenemos una sospecha razonable, bloquearemos el contenido o cuenta, podremos preservar la evidencia estrictamente necesaria y actuaremos conforme a la legislación y los requerimientos de las autoridades."},{"id":"block-4","type":"paragraph","text":"La posible presencia de una persona menor de edad debe informarse mediante el botón de reporte, cuando se disponga de una cuenta, o inmediatamente a [chile3x.site@gmail.com](mailto:chile3x.site@gmail.com). No debe descargarse, reenviarse ni difundirse el material."}]},{"id":"automatizacion","title":"Moderación y decisiones automatizadas","blocks":[{"id":"block-2","type":"paragraph","text":"Podemos utilizar validaciones automáticas para detectar formatos inválidos, spam, límites de carga, riesgo técnico o señales de abuso. Las decisiones relevantes de publicación, verificación y sanción contemplan revisión administrativa y no se basan exclusivamente en perfilamiento automatizado con efectos jurídicos equivalentes."},{"id":"block-4","type":"paragraph","text":"Si una validación automática produce un error, puede solicitarse intervención humana y revisión mediante el canal de soporte."},{"id":"block-6","type":"paragraph","text":"Las respuestas del bot de ayuda son orientativas y pueden contener errores. La búsqueda guiada no decide aprobaciones, sanciones, verificaciones ni accesos, y puede ser desactivada por administración. La persona interesada puede solicitar asistencia humana por los canales oficiales."}]},{"id":"cambios","title":"Vigencia, cambios y legislación aplicable","blocks":[{"id":"block-2","type":"paragraph","text":"Esta política se rige por la legislación chilena, especialmente la Ley N.º 19.628 y, desde el 1 de diciembre de 2026, sus modificaciones introducidas por la Ley N.º 21.719. También pueden resultar aplicables la Ley N.º 19.496, la Ley N.º 19.799, el Código Penal y otras normas sectoriales."},{"id":"block-4","type":"paragraph","text":"Podemos actualizar la política por cambios legales, técnicos o funcionales. Mostraremos la versión y fecha vigentes; si el cambio altera materialmente una finalidad o requiere consentimiento, lo informaremos y solicitaremos la autorización correspondiente antes de aplicarlo."},{"id":"block-6","type":"sources","text":"Fuentes legales y políticas relacionadas","items":["[Ley N.º 19.628 sobre protección de la vida privada](https://www.bcn.cl/leychile/navegar?idNorma=141599)","[Ley N.º 21.719 sobre protección de datos personales](https://www.bcn.cl/leychile/navegar?idNorma=1209272)","[Ley N.º 19.496 sobre protección de los derechos de los consumidores](https://www.bcn.cl/leychile/navegar?idNorma=61438)","[Términos y condiciones de Chile3X](/terminos)","[Reglas de publicación](/reglas-de-publicacion)"]}]}]}');

UPDATE _legal_release_20261026 SET next_json='{"title":"Política de privacidad y tratamiento de datos","description":"Datos, finalidades, bases legales, derechos, conservación, seguridad, cookies y condiciones de pagos futuros de Chile3X.","summary":"Esta política explica cómo Chile3X trata los datos de visitantes, cuentas, anunciantes, personas representadas y quienes contactan al portal. Distingue información pública, archivos privados, funciones opcionales y pagos futuros. La aceptación de términos no sustituye una autorización específica para tratar datos sensibles.","notice":"**Responsable:** **Pedro Enrique Reyes González**, persona natural, RUT **15.771.562-3**, que opera bajo el nombre comercial **Chile3X**. **Privacidad y ejercicio de derechos:** [chile3x.site@gmail.com](mailto:chile3x.site@gmail.com). No envíes contraseñas, códigos ni documentos completos por correo. Para acreditar identidad se utilizará un medio proporcionado. Puedes solicitar atención aunque no tengas cuenta.","sections":[{"id":"responsable","title":"Responsable, contacto y alcance","blocks":[{"id":"block-1","type":"paragraph","text":"El responsable de los tratamientos que decide Chile3X es **Pedro Enrique Reyes González**, persona natural, RUT **15.771.562-3**, que opera bajo el nombre comercial **Chile3X**, operador de **chile3x.cl**. El correo [chile3x.site@gmail.com](mailto:chile3x.site@gmail.com) constituye el canal electrónico público para consultas, solicitudes y notificaciones de privacidad. No se afirma la existencia de una sociedad, un delegado certificado ni una certificación que no hayan sido acreditados."},{"id":"block-2","type":"paragraph","text":"Esta política alcanza a visitantes, cuentas, anunciantes, agencias, responsables de arriendos, personas que aparecen en medios, participantes de mensajes o comunidad, personas representadas en muestras privadas, representantes y quienes presentan consultas, reclamos o reportes. Abarca los tratamientos bajo control del portal, sin convertir en propios los que un anunciante o un servicio externo decide independientemente."},{"id":"block-3","type":"paragraph","text":"Se aplica la Ley N.º 19.628 vigente. Las reglas expresamente identificadas como propias del texto reformado por la Ley N.º 21.719 rigen desde su entrada en vigor, fijada en el **1 de diciembre de 2026** en el texto oficial consultado. No se anticipa una base de licitud futura para justificar un tratamiento actual. Un anuncio o proyecto legislativo no modifica la vigencia por sí solo."},{"id":"block-4","type":"paragraph","text":"La información esencial de cada formulario debe permitir conocer qué datos son obligatorios para la función solicitada, cuáles son opcionales y qué ocurre si no se facilitan. Si no se entrega un dato indispensable puede no ser posible completar esa función; rechazar datos opcionales, publicidad o medición no debe impedir el uso de funciones que no los necesitan."}]},{"id":"principios","title":"Principios que aplicamos","blocks":[{"id":"block-2","type":"paragraph","text":"Chile3X procura tratar datos de forma lícita, leal y transparente; limitar su uso a finalidades informadas; solicitar solo lo necesario; mantenerlos razonablemente actualizados; protegerlos frente a accesos no autorizados y conservarlos únicamente mientras exista una finalidad legítima o una obligación aplicable."},{"id":"block-4","type":"paragraph","text":"No vendemos bases de datos personales. Tampoco utilizamos documentos de identidad, antecedentes médicos, mensajes de reportes ni contenido privado para publicidad dirigida."},{"id":"extended-3","type":"paragraph","text":"Aplicamos finalidad, proporcionalidad, calidad, seguridad, transparencia y confidencialidad, con responsabilidad sobre las decisiones y la evidencia que debe respaldarlas. La minimización abarca lo que se recoge, su visibilidad, los permisos, las copias, la conservación y los datos entregados a proveedores. Un dato seudonimizado, un identificador aleatorio o una huella pueden seguir siendo personales; solo una anonimización irreversible permite dejar de tratarlos como tales."},{"id":"extended-4","type":"paragraph","text":"La protección desde el diseño y por defecto exige evaluar riesgos antes de incorporar nuevas funciones, especialmente cuando involucran intimidad, ubicación, identidad o pagos. La existencia de controles técnicos y de esta política no equivale a afirmar que se ha certificado o auditado exhaustivamente todo el sistema."}]},{"id":"datos","title":"Categorías de datos que tratamos","blocks":[{"id":"block-2","type":"subheading","text":"Visitantes","numbered":true},{"id":"block-4","type":"list","text":"","items":["dirección IP, fecha y hora, ruta solicitada, navegador, dispositivo, registros de error y señales técnicas de seguridad;","confirmación de mayoría de edad, preferencias de privacidad y datos mínimos para mantener la sesión;","datos y eventos de medición externa opcional, cuando exista consentimiento; los registros técnicos y contadores propios se explican separadamente en esta política."],"ordered":false},{"id":"block-6","type":"subheading","text":"Cuentas","numbered":true},{"id":"block-8","type":"list","text":"","items":["correo electrónico, nombre visible, nombre completo opcional, tipo y número de documento, país del documento extranjero cuando corresponda, fecha de nacimiento, ciudad y teléfono opcional;","contraseña protegida mediante un resumen criptográfico; Chile3X no almacena contraseñas en texto legible;","estado de verificación del correo, rol, estado de la cuenta, fechas de creación y actividad administrativa;","historial de cambios en métodos de acceso y desvinculación de proveedores, sin contraseñas ni secretos legibles."],"ordered":false},{"id":"block-10","type":"subheading","text":"Anuncios","numbered":true},{"id":"block-12","type":"list","text":"","items":["tipo de perfil, nombre público, alias, URL personalizada, ciudad y región, descripción, características, servicios, idiomas, horarios, precios, agenda de viajes y disponibilidad;","teléfono, WhatsApp y las redes o plataformas que el anunciante decida publicar;","foto de perfil, galería, videos, historias, estados, archivos privados y contenido exclusivo;","estado de publicación, revisión, verificación, moderación, pausa y relaciones autorizadas entre agencias y escorts."],"ordered":false},{"id":"block-14","type":"subheading","text":"Interacciones y seguridad","numbered":true},{"id":"block-16","type":"list","text":"","items":["favoritos, likes, bloqueos, reseñas, comentarios y su estado de moderación;","reportes, motivo, texto y capturas de evidencia, además de las actuaciones administrativas asociadas;","visualizaciones de anuncios y clics en botones de contacto, agrupados por fecha y tipo de acción, incluyendo un identificador persistente del navegador y el número de pulsaciones. Solo con consentimiento de medición, un clic de WhatsApp puede asociarse a la cuenta iniciada y agregar país, región o ciudad aproximada entregada por Cloudflare, tipo de dispositivo y ruta de origen. Sin ese permiso se conserva únicamente un identificador opaco para el conteo diario y nunca se guarda la IP en ese registro;","mensajes privados enviados dentro de Chile3X, anuncio de origen, participantes, fecha, estado de lectura, silencio y bloqueos necesarios para mantener el historial y prevenir abuso;","última actividad reciente de cuentas con anuncios, utilizada únicamente para mostrar un indicador temporal “Online”; el público no recibe la fecha exacta;","si se vincula Telegram: identificador numérico, usuario y nombre que Telegram comparte, estado de vinculación y membresía, invitaciones, medidas de moderación y registros técnicos necesarios para operar el bot;","si se elige Apple una vez habilitado: identificador estable, correo verificado —incluido un posible correo privado de retransmisión—, nombre compartido la primera vez y autorización cifrada necesaria para revocar el acceso al eliminar la cuenta;","actuaciones administrativas: identidad de quien intervino, fecha, operación, elemento afectado, resultado y cambios relevantes. Incluyen aprobación de archivos, modificaciones de anuncios, publicación de historias por administración y configuración. No se duplican archivos de identidad, contraseñas, secretos ni cuerpos de historias en esos registros;","en el foro privado beta: identificador y nombre administrativo de autoría, sección, título, texto, fechas, estados de edición y moderación, versión de las normas aceptadas, declaración de derechos y consentimiento para adjuntos, temas seguidos, notificaciones internas propias y denuncias con su decisión. Esta información no se publica ni se ofrece a usuarios generales; no se deben cargar documentos privados."],"ordered":false},{"id":"extended-9","type":"paragraph","text":"Las muestras privadas pueden contener alias, contactos, ciudad, fotografías, videos, texto, procedencia informada, autorización declarada, vigencia y seguimiento administrativo de contacto. Los enlaces de acceso y sus tokens son credenciales que no deben difundirse. La preparación privada también constituye tratamiento de datos aunque no exista una cuenta ni un anuncio público."},{"id":"extended-10","type":"paragraph","text":"Si se habilitan servicios pagados, podrán tratarse datos de identificación y facturación exigibles, referencia de orden, importe, moneda, medio de pago, estado, fechas, identificador de transacción y devolución, y los datos mínimos del comprobante de transferencia. No se recabarán claves bancarias, CVV, PIN o números completos de tarjetas en los sistemas del portal. No existen actualmente esos cobros integrados."}]},{"id":"sensibles","title":"Datos sensibles, intimidad y límites especiales","blocks":[{"id":"block-1","type":"paragraph","text":"Por la naturaleza del directorio, los anuncios, categorías, imágenes, conversaciones y registros de interacción pueden revelar o permitir inferir aspectos de la vida sexual, orientación sexual, identidad de género, características personales o salud. El riesgo de identificación, estigmatización, acoso o extorsión obliga a limitar estos tratamientos y sus destinatarios. No se necesita mostrar el nombre legal para que una persona resulte identificable."},{"id":"block-2","type":"paragraph","text":"La publicación de datos íntimos debe basarse en una autorización expresa, específica e informada de su titular u otro supuesto legal estrictamente aplicable. La persona debe conocer qué se publica, con qué finalidad, quién podrá acceder y que pueden intervenir buscadores y copias ajenas. Aceptar los términos, cargar un archivo o usar un alias no se considerará una autorización ilimitada ni permite presumir consentimiento para nuevas finalidades."},{"id":"block-3","type":"paragraph","text":"El contrato y el interés legítimo previstos para datos ordinarios no desplazan las restricciones especiales. La excepción relativa a datos manifiestamente públicos no permite reutilizar indiscriminadamente información sensible: requiere respetar los presupuestos legales y los fines de la publicación. Encontrar una foto, un teléfono o un anuncio en otra web no acredita una licencia ni una autorización para preparar una muestra o republicar."},{"id":"block-4","type":"paragraph","text":"Los datos de salud y del perfil biológico están sujetos, desde la vigencia del texto reformado, a la restricción específica del artículo 16 bis: incluso mediando consentimiento, su tratamiento debe responder a los fines permitidos por las leyes especiales sanitarias, salvo las excepciones legales correspondientes. Una verificación comercial o un consentimiento genérico no convierten al portal en prestador sanitario ni habilitan a certificar salud."},{"id":"block-5","type":"paragraph","text":"No se utiliza un sistema de identificación biométrica mediante plantillas faciales, de voz, huella o iris como función descrita de este portal. Una fotografía no se convierte automáticamente en dato biométrico por existir como imagen; sí puede ser un dato sensible por su contexto. El recorte o difuminado manual no constituye por sí solo reconocimiento biométrico ni garantiza anonimización. Cualquier sistema biométrico futuro requerirá revisión previa, información específica y fundamento legal suficiente."},{"id":"block-6","type":"paragraph","text":"No vendemos bases de datos ni utilizamos documentos de identidad, información médica, evidencias, mensajes o material privado para publicidad dirigida o entrenamiento de modelos de inteligencia artificial. La persona puede retirar una autorización para usos futuros por el canal de privacidad; una conservación exigible debe fundarse y limitarse, sin mantener el contenido íntimo públicamente disponible."}]},{"id":"origen","title":"De dónde obtenemos los datos","blocks":[{"id":"block-2","type":"paragraph","text":"Recibimos datos directamente de la persona que visita, se registra, publica, comenta o reporta; de una agencia cuando invita a vincular un perfil, sujeto a aceptación de la escort; del funcionamiento técnico del sitio; y de proveedores que confirman entregas de correo, seguridad o funcionamiento."},{"id":"block-4","type":"paragraph","text":"Si alguien entrega datos de otra persona, declara tener autorización suficiente y debe informarle este tratamiento. Chile3X puede solicitar prueba de esa autorización y eliminar el contenido si no se acredita."},{"id":"extended-3","type":"paragraph","text":"Cuando los datos no provengan de la persona representada, deben registrarse su procedencia y la autorización o fundamento aplicable. La información accesible públicamente conserva protección. Las declaraciones de quien carga material no sustituyen la obligación del responsable de comprobar la licitud cuando existan dudas, atender a la persona afectada y retirar o restringir datos tratados sin fundamento."}]},{"id":"finalidades","title":"Para qué utilizamos la información","blocks":[{"id":"block-2","type":"list","text":"","items":["crear, autenticar, recuperar, administrar, suspender o cerrar cuentas;","comprobar mayoría de edad y, cuando corresponda, revisar identidad o antecedentes voluntarios;","crear borradores, moderar cambios, publicar, ordenar, buscar, pausar y mostrar anuncios;","gestionar historias, galerías, medios, relaciones agencia–escort y accesos exclusivos;","habilitar favoritos, likes, reseñas, comentarios, mensajería privada, bloqueos, reportes y paneles de rendimiento;","ordenar anuncios según la ciudad o comuna de cobertura seleccionada manualmente; la persona usuaria puede borrar esa preferencia y volver a Todo Chile. Esta función no solicita coordenadas GPS;","vincular voluntariamente Telegram, administrar el acceso a Miembros, sincronizar Novedades, moderar la comunidad y avisar al equipo sobre medidas relevantes;","enviar correos transaccionales como verificación, recuperación, aprobación, rechazo, suspensión y avisos importantes de la cuenta;","prevenir fraude, spam, suplantación, explotación, contenido ilícito, ataques y uso indebido;","resolver solicitudes, cumplir obligaciones legales, colaborar con autoridades competentes y ejercer o defender derechos;","medir y mejorar el sitio con datos generales cuando exista consentimiento para Analytics."],"ordered":false}]},{"id":"bases","title":"Finalidades y bases de licitud: distinción entre regímenes","blocks":[{"id":"block-1","type":"paragraph","text":"Hasta la entrada en vigor de la reforma, se requiere autorización expresa e informada de la persona titular o una habilitación legal en los términos de la Ley N.º 19.628 vigente, incluidas las restricciones de su artículo 10 para datos sensibles. No se invoca anticipadamente el catálogo del futuro artículo 13 como permiso actual."},{"id":"block-2","type":"paragraph","text":"Desde la vigencia del texto reformado, la base se determinará por operación y finalidad, y deberá poder acreditarse. El siguiente marco no autoriza a recolectar más datos que los necesarios ni sustituye las reglas de categorías especiales:"},{"id":"block-3","type":"list","text":"","items":["**Cuenta y funciones solicitadas:** los datos ordinarios imprescindibles para autenticar, recuperar y administrar la cuenta o ejecutar una función pedida podrán apoyarse en la celebración o ejecución contractual del artículo 13 letra c), o en el consentimiento cuando corresponda. Un dato que no es necesario no se vuelve obligatorio por incluirlo en el contrato.","**Publicación íntima y otras operaciones sensibles:** consentimiento expreso específico conforme al artículo 16, salvo una excepción legal acreditada. Se distinguen creación de una muestra privada, publicación abierta, accesos exclusivos y difusión en otros canales. Para salud y biometría se aplican, además, los artículos 16 bis y 16 ter.","**Medición opcional y comunicaciones comerciales:** consentimiento cuando sea la base aplicable, separado de registro y contratación. No se utilizan intereses de la audiencia adulta para campañas incompatibles. La oposición al marketing directo se atenderá conforme a la ley.","**Seguridad y prevención de fraude sobre datos ordinarios:** cumplimiento de una obligación concreta, defensa de derechos o interés legítimo cuando sea jurídicamente procedente. En este último caso deben identificarse el interés, la necesidad, alternativas menos invasivas, la ponderación frente a los derechos de la persona y las garantías. No constituye una autorización general para rastrear vida sexual.","**Solicitudes y autoridad:** cumplimiento de deberes legales de atención, seguridad o una orden válida; defensa de derechos cuando corresponda. Se verificará el alcance y se comunicará solo lo pertinente.","**Pagos propios futuros:** ejecución del contrato para tramitar orden, pago y devolución; obligación legal para documentos tributarios; controles antifraude proporcionados con base acreditada. El banco o pasarela podrá tener obligaciones y decisiones propias que deberá informar."],"ordered":false},{"id":"block-4","type":"paragraph","text":"Cuando se invoque interés legítimo se podrá solicitar información sobre el tratamiento y el interés concreto y ejercer oposición. No se lo utilizará para evitar un consentimiento necesario. La publicación de esta política no acredita que estén completadas todas las evaluaciones de ponderación o contratos de proveedores; esos antecedentes deben mantenerse y ponerse a disposición en los términos legales."}]},{"id":"consentimiento","title":"Consentimiento, retirada y cambios de finalidad","blocks":[{"id":"block-1","type":"paragraph","text":"La autorización debe ser previa, libre, específica, informada e inequívoca; para datos sensibles debe ser expresa. Las finalidades opcionales se presentarán por separado y sin casillas premarcadas. La persona debe poder distinguir qué acepta respecto del servicio y qué autoriza respecto de sus datos, sin quedar obligada a usos que no sean necesarios para lo solicitado."},{"id":"block-2","type":"paragraph","text":"El registro actual conserva la cuenta, fecha y versiones de los documentos aceptados. El sitio conserva además la elección de medición en una cookie. Esas evidencias tienen alcances distintos y no se presentan como un registro completo de consentimiento para todo tratamiento sensible. Cuando una operación requiera autorización adicional, debe obtenerse y poder acreditarse antes de realizarla."},{"id":"block-3","type":"paragraph","text":"El consentimiento puede retirarse en cualquier momento, sin expresión de causa y gratuitamente. Para medición existe el enlace de [preferencias](/privacidad?medicion=editar#medicion); para publicación o usos sensibles se pueden utilizar las funciones de retirada disponibles o escribir a [chile3x.site@gmail.com](mailto:chile3x.site@gmail.com). Se ofrecerá un medio equivalente y proporcionado al usado para autorizar. La retirada no invalida el tratamiento previo lícito ni elimina una obligación legal de conservación debidamente fundada."},{"id":"block-4","type":"paragraph","text":"Si retirar una autorización impide mantener un contenido o una función que depende de ella, se explicará ese efecto concreto. No se cancelarán funciones independientes como sanción por retirar un consentimiento opcional. Un nuevo uso incompatible, una difusión adicional o una cesión que requiera autorización no se legitiman mediante un aviso genérico o por continuar navegando."}]},{"id":"publicos","title":"Perfiles públicos, buscadores y redes sociales","blocks":[{"id":"block-2","type":"paragraph","text":"Una publicación aprobada puede mostrar su nombre público, alias, ciudad, descripción, atributos, disponibilidad, precios, agenda, contactos, imágenes, videos, historias, distintivos, reseñas aprobadas y demás campos que el anunciante haya destinado al perfil público."},{"id":"block-4","type":"paragraph","text":"Las páginas públicas pueden ser encontradas por buscadores, guardadas en caché y generar vistas previas al compartir enlaces. Incluso después de despublicar o modificar una página, Google, redes sociales y otros terceros pueden tardar en actualizar o eliminar sus copias. Chile3X puede solicitar una actualización, pero no controla esos plazos."},{"id":"block-6","type":"paragraph","text":"Los datos privados de la cuenta no se incorporan automáticamente al anuncio. La persona puede elegir publicar los datos de contacto o identificación pública admitidos por el formulario. No deben publicarse documentos de identidad, antecedentes médicos, evidencia de reportes ni datos privados de terceros."},{"id":"extended-4","type":"paragraph","text":"La publicación puede permitir contactos desde fuera del sitio y asociar a una persona con categorías o servicios sensibles. Un campo público no es un lugar adecuado para el RUT, domicilio particular, diagnósticos o datos de otra persona. La selección manual de una ciudad no implica rastreo GPS de visitantes; los horarios y viajes son declaraciones del anunciante y no una verificación de su ubicación en tiempo real."},{"id":"extended-5","type":"paragraph","text":"La solicitud de rectificación, supresión o retirada se aplicará a los sistemas bajo control del portal y, cuando proceda, se comunicará a destinatarios a quienes se hayan entregado los datos. Se podrán facilitar antecedentes para pedir actualización o desindexación a terceros, sin garantizar un borrado universal o instantáneo de todas las copias de Internet."}]},{"id":"documentos","title":"Identidad, documentos privados y antecedentes de salud","blocks":[{"id":"block-1","type":"paragraph","text":"El sitio dispone de carga opcional de imágenes o PDF de identidad y antecedentes médicos para revisión privada. Los archivos se almacenan con acceso restringido a la persona titular y administración con facultades de consulta, mediante rutas autenticadas y sin indexación pública. La mera existencia de la función o el carácter opcional no acreditan la licitud de cada carga ni una finalidad sanitaria."},{"id":"block-2","type":"paragraph","text":"La finalidad de una comprobación de identidad debe limitarse a edad, titularidad, autorización o prevención de suplantación cuando resulte necesaria. Deben preferirse medios menos invasivos y permitir ocultar datos no pertinentes cuando ello no impida la comprobación. No se publican documentos ni se autoriza a una agencia a consultarlos por el solo vínculo con un anuncio."},{"id":"block-3","type":"paragraph","text":"Chile3X no diagnostica ni certifica condiciones sanitarias. No deben aportarse exámenes, diagnósticos o certificados para promocionar supuestas garantías de salud. Los antecedentes ya recibidos quedan sujetos a revisión de necesidad, base jurídica, acceso y eliminación. Desde la vigencia del artículo 16 bis reformado solo podrá mantenerse o iniciarse tratamiento de salud si se acredita una finalidad admitida por las leyes sanitarias o una excepción legal aplicable; una casilla de consentimiento no basta para suplir esa exigencia."},{"id":"block-4","type":"paragraph","text":"La persona puede retirar o reemplazar archivos mediante las opciones disponibles o solicitar su eliminación por el canal de privacidad. El plazo técnico de conservación no habilita un uso indebido ni impide eliminar antes. Un resultado de revisión que revele salud también es información de salud: no puede conservarse indefinidamente ni convertirse en una garantía pública por haber borrado el certificado."},{"id":"block-5","type":"paragraph","text":"Se registra el acceso administrativo y las actuaciones de carga, reemplazo o eliminación para trazabilidad, sin duplicar el documento en la auditoría. Los permisos deben responder a la función y necesidad de quien interviene, y el deber de confidencialidad se mantiene después de finalizar su vínculo con el portal."}]},{"id":"exclusivo","title":"Galería privada y autorizaciones de acceso","blocks":[{"id":"block-2","type":"paragraph","text":"El material exclusivo permanece bloqueado para el público. La persona dueña del anuncio administra el acceso añadiendo el correo de una cuenta registrada. Para operar la función tratamos la relación entre anuncio, cuenta autorizada, archivos y fechas relevantes."},{"id":"block-4","type":"paragraph","text":"La persona anunciante es responsable de confirmar que quien autoriza es adulta y de retirar el acceso cuando corresponda. Aunque Chile3X aplica controles técnicos, ninguna medida puede impedir por completo capturas o copias realizadas por alguien que recibió acceso legítimo. No utilizamos esa galería para entrenar sistemas de inteligencia artificial ni para publicidad."}]},{"id":"muestras","title":"Muestras privadas y personas sin cuenta","blocks":[{"id":"block-1","type":"paragraph","text":"La preparación de muestras privadas trata datos de personas que pueden no estar registradas. Debe existir una autorización o fundamento lícito suficiente para preparar la muestra, conservar los archivos, contactar a la persona y eventualmente convertirla en anuncio. El acceso mediante token y el aviso noindex son medidas de acceso e indexación; no sustituyen esa base jurídica ni el deber de información."},{"id":"block-2","type":"paragraph","text":"La procedencia indicada por administración, la autorización declarada, el enlace, las fechas y el seguimiento de contacto permiten gestionar la muestra. Una declaración administrativa no prueba por sí sola la voluntad de la persona representada. Se deben conservar antecedentes adecuados de la autorización sin recopilar documentos excesivos ni reproducir conversaciones íntimas innecesarias."},{"id":"block-3","type":"paragraph","text":"La persona representada puede ejercer derechos y pedir el retiro aunque no tenga cuenta, escribiendo a [chile3x.site@gmail.com](mailto:chile3x.site@gmail.com). Puede identificar la muestra o aportar la referencia mínima de contacto, sin reenviar fotografías íntimas como requisito automático. Se verificará la identidad con medios proporcionados y se revocarán accesos cuando corresponda."}]},{"id":"comunidad","title":"Reseñas, Telegram, bloqueos, reportes y evidencias","blocks":[{"id":"block-2","type":"paragraph","text":"Las reseñas o comentarios aprobados por el anunciante pueden mostrar el nombre visible de su autor y su contenido. Antes de aprobarse solo pueden consultarlos su autor, el propietario del anuncio y administración. El autor puede retirar su reseña pendiente; el anunciante puede aprobarla, rechazarla o eliminarla, y administración puede consultarla o eliminarla. Favoritos, bloqueos y listas personales no se muestran públicamente. Los reportes y sus capturas son privados y accesibles para el equipo autorizado y para la cuenta que los envió dentro de su panel."},{"id":"block-4","type":"paragraph","text":"Podemos utilizar esos antecedentes para investigar, contactar a las partes cuando sea seguro y necesario, moderar, preservar evidencia, prevenir reiteración y responder a una autoridad. No revelaremos la identidad de quien reporta al perfil denunciado salvo consentimiento, obligación legal o necesidad fundada de defensa, aplicando minimización."},{"id":"block-6","type":"paragraph","text":"Vincular Telegram es opcional. El sitio conserva la relación entre la cuenta y el identificador que entrega Telegram para comprobar acceso, crear invitaciones individuales y aplicar o retirar medidas. Los mensajes procesados por el bot pueden conservarse temporalmente para evitar duplicados, detectar envíos masivos o spam y ejecutar las tareas pendientes; una evidencia breve y la medida aplicada pueden mantenerse mientras sea necesario para revisar el caso y prevenir reincidencia. Desvincular, deshabilitar o eliminar la cuenta retira el acceso a Miembros, pero Telegram puede conservar mensajes conforme a sus propias reglas."},{"id":"block-8","type":"paragraph","text":"El chat interno requiere sesión. Cada participante puede silenciar o bloquear la conversación. Si una de las cuentas se deshabilita o elimina, la otra puede conservar el texto del historial, pero Chile3X sustituye la identidad visible de la persona retirada por “Usuario de Chile3X” y bloquea mensajes nuevos; las relaciones directas con la cuenta eliminada se desprenden de la conversación. Si ya no queda ningún participante con acceso, la conversación se elimina. Los indicadores de no leído y los avisos del navegador se usan solo para comunicar mensajes; Chile3X puede aplicar límites automáticos de frecuencia para reducir spam. No deben enviarse contraseñas, códigos, documentos ni datos bancarios."},{"id":"block-10","type":"paragraph","text":"La sustitución del nombre de una cuenta no anonimiza automáticamente el texto de sus mensajes. Las referencias identificables incorporadas en conversaciones se evalúan conforme a los derechos aplicables y a la finalidad de conservación del historial."},{"id":"block-12","type":"paragraph","text":"El centro de ayuda “Johnny Sins” funciona mediante búsqueda guiada en documentación revisada. Las consultas y valoraciones se mantienen únicamente en la memoria de la pestaña durante la visita; no se guardan como conversación en la base de datos ni se envían a un proveedor de IA generativa. Los enlaces de ayuda pueden referirse a anuncios pertenecientes a la cuenta, consultados con su sesión. Al abrir un WhatsApp de soporte, no se adjunta automáticamente la conversación. No deben ingresarse contraseñas, códigos, documentos ni datos privados de terceros."},{"id":"block-14","type":"paragraph","text":"El foro privado beta se utiliza para desarrollo y pruebas administrativas. Sus contenidos y archivos solo pueden ser consultados por administración habilitada para el foro. Los adjuntos requieren declaración de autorización y consentimiento, están sujetos a cuotas y quedan pendientes de revisión; esto no equivale a una certificación de identidad o legalidad. Las notificaciones se limitan a temas seguidos y a su destinatario; no se envían correos automáticos. Archivar una sección o enviar un tema a papelera no equivale a borrar inmediatamente sus datos. Las denuncias permiten solicitar revisión y rectificación; sus decisiones quedan registradas, sin duplicar los textos de las respuestas en la auditoría. Los contadores de frecuencia ayudan a limitar cargas y publicaciones abusivas."}]},{"id":"medicion","title":"Cookies, almacenamiento local y medición opcional","blocks":[{"id":"block-2","type":"subheading","text":"Funciones necesarias","numbered":true},{"id":"block-4","type":"paragraph","text":"Utilizamos cookies o almacenamiento equivalente para mantener la sesión, recordar la confirmación de mayoría de edad, conservar preferencias de privacidad, proteger formularios, limitar abuso, recordar historias vistas y operar funciones solicitadas. Estas tecnologías son necesarias para que ciertas partes del sitio funcionen y no se utilizan para publicidad conductual."},{"id":"block-6","type":"subheading","text":"Inicio de sesión con Google","numbered":true},{"id":"block-8","type":"paragraph","text":"Si se elige continuar con Google, recibimos el identificador estable de la cuenta de Google, el correo verificado y el nombre que Google comparte. Usamos el identificador y el correo para comprobar la identidad, vincular o crear la cuenta y evitar accesos duplicados; el nombre solo completa inicialmente campos editables durante el registro."},{"id":"block-10","type":"paragraph","text":"No solicitamos acceso a Gmail, Drive, contactos, archivos ni calendario, y no almacenamos tokens de acceso de Google. El correo queda vinculado y no puede modificarse desde la cuenta. Si abandonas el registro, los datos del intento se eliminan automáticamente al vencer el plazo breve de seguridad."},{"id":"block-12","type":"paragraph","text":"La persona titular puede desvincular un proveedor desde Mis datos después de configurar y confirmar una contraseña. Esto no elimina la cuenta ni revierte la verificación de su correo. Conservamos un historial de cambios de acceso, consultable por la persona titular y administración autorizada, para proteger la cuenta."},{"id":"block-14","type":"subheading","text":"Inicio de sesión con Apple preparado, aún inactivo","numbered":true},{"id":"block-16","type":"paragraph","text":"Chile3X muestra un botón de Apple deshabilitado mientras el proveedor no se encuentre habilitado con una configuración completa. En ese estado no se abre Apple ni se le envían datos. Si se habilita en el futuro y la persona elige utilizarlo, recibiremos el identificador estable, correo verificado y, únicamente en la primera autorización, el nombre que Apple comparta. Esos nombres solo completarán campos editables del registro; el correo quedará bloqueado."},{"id":"block-18","type":"paragraph","text":"El flujo rechazará identidades incompatibles, incluido un correo vinculado a otro proveedor o a una identidad administrativa. La autorización de larga duración que Apple entregue se almacenará cifrada y se utilizará para revocarla cuando corresponda, incluida la eliminación permanente de la cuenta. Chile3X no recibirá la contraseña de Apple ni acceso a iCloud, fotos, contactos o archivos."},{"id":"block-20","type":"subheading","text":"Google Tag Manager y Google Analytics","numbered":true},{"id":"block-22","type":"paragraph","text":"Los WhatsApp del equipo usan contadores internos agregados por día, área y acceso: aperturas del panel y clics para abrir WhatsApp. No guardan IP, cuenta, número del visitante ni el contenido de mensajes, y no acreditan que se haya enviado un mensaje. Son independientes de los contactos de anunciantes."},{"id":"block-24","type":"paragraph","text":"El contacto del anunciante destacado dentro del panel de WhatsApp utiliza el registro de contactos del anuncio, no el contador del equipo. El contador de pulsaciones de WhatsApp del anuncio es visible únicamente para administración autorizada. El equipo no recibe el contenido de las conversaciones mantenidas en WhatsApp."},{"id":"block-26","type":"paragraph","text":"La medición es opcional y solo se carga cuando la persona selecciona **“Aceptar medición”** en el aviso de privacidad. Con esa autorización se miden visitas y acciones generales como registros, envíos de anuncios, clics de contacto, favoritos, likes y reseñas para entender el uso y mejorar Chile3X."},{"id":"block-28","type":"paragraph","text":"No configuramos el envío a Google de nombres, correos, teléfonos, RUT, direcciones, archivos privados, texto libre ni identificadores internos de perfiles como parámetros de Analytics. Google puede tratar información técnica como dirección IP, navegador, dispositivo y señales de interacción conforme a sus propias condiciones y medidas disponibles."},{"id":"block-30","type":"paragraph","text":"Al seleccionar **“Solo necesarias”**, el sitio seguirá funcionando sin cargar Google Tag Manager ni Google Analytics. La elección puede retirarse o modificarse en cualquier momento; el cambio no invalida el tratamiento anterior basado en consentimiento."},{"id":"block-32","type":"paragraph","text":"[Cambiar mi elección de medición →](/privacidad?medicion=editar#medicion)"},{"id":"block-34","type":"subheading","text":"Inicio de sesión con X preparado, aún inactivo","numbered":true},{"id":"block-36","type":"paragraph","text":"Mientras el acceso con X esté deshabilitado no se abre ese proveedor ni se le envían datos. Si se habilita y la persona elige utilizarlo, recibiremos su identificador estable, nombre, nombre de usuario y el correo confirmado que X autorice compartir. Si no entrega un correo confirmado, la persona deberá completar y verificar uno mediante el proceso del sitio. El nombre solo completa campos editables del registro."},{"id":"block-38","type":"paragraph","text":"No solicitamos permiso para publicar, enviar mensajes privados ni acceder a mensajes. El token se utiliza únicamente para obtener la identidad y se solicita su revocación al terminar; no se almacena como credencial permanente. X podrá desvincularse con los mismos controles de contraseña e historial que los demás proveedores."},{"id":"block-40","type":"subheading","text":"Mapas referenciales de Google Maps","numbered":true},{"id":"block-42","type":"paragraph","text":"Los anuncios incluyen un mapa referencial de su ciudad, que se carga de forma diferida. Solo enviamos el nombre de la ciudad, región y país: no enviamos el nombre del anunciante, su cuenta, dirección, notas de ubicación ni coordenadas privadas. Al cargarse el mapa o abrir Maps, Google puede recibir información técnica del navegador y aplicar sus propias condiciones y política de privacidad. No solicitamos la ubicación de la persona visitante para mostrar estos mapas."},{"id":"extended-22","type":"paragraph","text":"**Alcance real de los contadores propios:** además de Google, las visitas y pulsaciones de contacto de anuncios utilizan la cookie **chile3x_profile_viewer**, con duración de hasta **365 días**, para reconocer un navegador y evitar o agrupar duplicados por anuncio, fecha y tipo de contacto. Estos registros se generan también cuando la elección de Google es “Solo necesarias”. No contienen la IP en esas tablas, pero el identificador persistente y su relación con anuncios son datos seudonimizados, no anónimos."},{"id":"extended-23","type":"paragraph","text":"Con autorización de medición, los clics de contacto pueden añadir la cuenta iniciada, país, región o ciudad aproximada de la conexión, dispositivo y ruta de origen. Esa información no acredita una visita física, un pago ni el contenido de una conversación externa. El contador diario de WhatsApp del equipo es distinto y no almacena ese identificador de visitante."},{"id":"extended-24","type":"paragraph","text":"La elección de Google se conserva durante **180 días**. Rechazarla impide cargar Tag Manager y Analytics desde el mecanismo del sitio. Retirarla cambia la elección y recarga la página para detener futuras cargas desde ese mecanismo; no garantiza borrar por sí sola cookies ya creadas o registros previos de Google. También se pueden eliminar cookies en el navegador y solicitar atención sobre datos que resulten identificables."},{"id":"extended-25","type":"paragraph","text":"La conservación de una cookie no fija el plazo de conservación de cada evento. Los registros propios de visitas y contactos requieren una revisión específica de minimización, base jurídica y depuración; no se les atribuye un plazo automático que el sistema todavía no aplica. Se puede solicitar acceso, supresión u oposición cuando proceda. La denominación “Solo necesarias” no constituye una autorización adicional para usos sensibles o de seguimiento."},{"id":"extended-26","type":"paragraph","text":"Los mapas se cargan de forma diferida y pueden generar comunicación de datos técnicos a Google aun sin activar Analytics. La autenticación de un proveedor, Turnstile y abrir un enlace externo son operaciones distintas de Analytics. Se limitarán a su finalidad y a lo necesario; no se describe el sitio como libre de toda comunicación a terceros antes del consentimiento de Google."}]},{"id":"proveedores","title":"Proveedores tecnológicos y transferencias internacionales","blocks":[{"id":"block-2","type":"paragraph","text":"Para operar Chile3X utilizamos proveedores que tratan datos por cuenta del portal o prestan infraestructura bajo sus propios términos:"},{"id":"block-4","type":"list","text":"","items":["**Cloudflare:** alojamiento del sitio, base de datos, almacenamiento de archivos, red de entrega, certificados, seguridad, Turnstile para combatir bots y Cloudflare Email cuando sea el proveedor configurado;","**Google:** autenticación cuando se elige “Continuar con Google”, correo transaccional cuando se utilice el relay de Google configurado, mapas referenciales de ciudades y, solo con consentimiento, Google Tag Manager y Google Analytics;","**Telegram:** comunidad pública, vinculación voluntaria de cuentas, invitaciones a Miembros, Novedades y moderación mediante el bot;","**Apple:** solo si el proveedor llega a habilitarse y la persona lo elige, autenticación y revocación de la autorización asociada;","**X:** solo si el acceso llega a habilitarse y la persona lo elige, autenticación e identidad autorizada para crear o vincular su cuenta;","**proveedores de navegador, sistema operativo o redes externas:** únicamente cuando la persona utiliza esas aplicaciones o sigue un enlace."],"ordered":false},{"id":"block-6","type":"paragraph","text":"Estos servicios pueden procesar o respaldar información fuera de Chile. Chile3X procura escoger proveedores reconocidos, limitar los datos enviados, configurar accesos y aplicar salvaguardas contractuales y técnicas razonables. La ubicación de la infraestructura puede cambiar sin que ello signifique una venta de datos."},{"id":"extended-4","type":"paragraph","text":"En el acceso administrativo interviene GitHub para autenticar identidades autorizadas; no concede acceso administrativo por el solo hecho de colaborar en el repositorio. El envío de correo depende del proveedor configurado para esa función. Las eventuales copias externas, subencargados y servicios auxiliares deben incluirse en el inventario de proveedores cuando realmente se utilicen; no se presume que una integración preparada esté operativa."},{"id":"extended-5","type":"paragraph","text":"Debe distinguirse al encargado que actúa siguiendo instrucciones de Chile3X del destinatario que determina sus propios fines, como un proveedor de identidad, banco o red social en las operaciones que le sean propias. Esa calidad depende del servicio y contrato, no solamente de su nombre comercial. El encargo debe documentar objeto, duración, finalidades, datos, titulares, instrucciones, confidencialidad, seguridad, subcontratación autorizada, incidentes, asistencia en derechos y devolución o supresión, de acuerdo con la ley aplicable."},{"id":"extended-6","type":"paragraph","text":"No se garantiza residencia exclusiva en Chile: la infraestructura y el soporte pueden implicar tratamiento internacional, incluido Estados Unidos u otros países utilizados por los proveedores. Desde la vigencia de los artículos 27 y 28 reformados, una transferencia habitual debe apoyarse en un país reconocido como adecuado o en garantías idóneas conforme al régimen chileno. Las cláusulas contractuales, normas corporativas o certificaciones invocadas deben ser aplicables, válidas y suficientes para la operación concreta."},{"id":"extended-7","type":"paragraph","text":"Una excepción para una transferencia específica no habitual no sustituye una garantía para infraestructura continua. El consentimiento general para usar el sitio, una política de un proveedor o unas cláusulas europeas no acreditan por sí solos una transferencia regularizada en Chile. Deben informarse el país o los destinos pertinentes, su nivel de protección y las garantías aplicables; esa información puede solicitarse por el canal de privacidad. No se afirma aquí una decisión de adecuación o un contrato que no haya sido verificado."},{"id":"extended-8","type":"paragraph","text":"Antes de añadir un nuevo proveedor, finalidad o destino que modifique materialmente el tratamiento se revisarán necesidad, riesgo, acceso y fundamento. Se dará la información adicional y se recabará una autorización nueva cuando sea exigible. La responsabilidad del portal no desaparece por contratar infraestructura de un tercero."}]},{"id":"pagos","title":"Datos y seguridad de pagos: aplicación condicionada a su habilitación","blocks":[{"id":"block-1","type":"callout","text":"No existen actualmente cobros integrados por transferencia o pasarela. Las reglas siguientes serán exigibles para la operación que llegue a habilitarse y deberán implementarse antes de recibir datos de pago. No son un anuncio de que el sistema ya procese fondos."},{"id":"block-2","type":"paragraph","text":"El tratamiento se limitará a tramitar la orden, confirmar el pago, activar el servicio propio contratado, conciliar, prevenir fraude de forma proporcionada, atender reclamos y devolver importes, y emitir o conservar documentos exigibles. Se informarán al contratar el prestador, domicilio, banco o pasarela, datos compartidos, países relevantes, fundamento, conservación y canal de soporte. El pago no autoriza publicidad ni publicación de información íntima."},{"id":"block-3","type":"paragraph","text":"Las transferencias utilizarán una referencia de orden y verificación del abono; se evitará guardar comprobantes con movimientos o saldos ajenos. Para tarjetas se utilizará un proveedor con formularios alojados o tokenización, y Chile3X no conservará PAN completo, CVV, PIN, claves bancarias o códigos de autenticación. Solo se almacenarán los identificadores y datos reducidos que sean necesarios, sin atribuirlos automáticamente a un tratamiento anónimo."},{"id":"block-4","type":"paragraph","text":"Antes de habilitar el cobro se deben aplicar conexión cifrada, restricciones de acceso, autenticación de notificaciones del proveedor, prevención de repeticiones y duplicados, conciliación, auditoría minimizada, control de reembolsos y respuesta a incidentes. Se revisarán el contrato, subencargados, admisibilidad del giro y las exigencias de seguridad de medios de pago que correspondan, sin afirmar una certificación PCI DSS obtenida por Chile3X."},{"id":"block-5","type":"paragraph","text":"El banco o la pasarela puede tratar datos como responsable independiente para cumplir obligaciones propias y debe informar sus condiciones. El uso de ese proveedor no exime a Chile3X de proteger los datos que recibe ni de atender sus obligaciones por la contratación. El acceso de soporte se limitará a resolver la operación, sin permitir consultar innecesariamente información íntima de la cuenta."},{"id":"block-6","type":"paragraph","text":"La conservación se definirá por categoría antes de activar pagos: información operativa mientras sea necesaria para la ejecución y reclamaciones; documentos tributarios durante el período exigible según la obligación concreta; evidencias de fraude solo en un expediente justificado; tokens hasta su revocación o vencimiento cuando corresponda. No se aplicará un plazo genérico a todos los datos financieros ni se retendrán comprobantes íntegros por mera conveniencia. Una supresión puede limitarse respecto de un registro legalmente exigible, manteniéndolo separado del uso comercial."}]},{"id":"autoridades","title":"Cuándo podemos comunicar datos","blocks":[{"id":"block-2","type":"paragraph","text":"Podemos comunicar la información mínima necesaria a proveedores que operan el servicio; a asesores sujetos a deberes de confidencialidad; a autoridades judiciales, policiales, administrativas o al Ministerio Público ante una orden o requerimiento válido; o cuando sea necesario para denunciar o prevenir una amenaza seria, explotación, trata, abuso de menores, difusión íntima no consentida, fraude o ataque."},{"id":"block-4","type":"paragraph","text":"No entregamos bases de datos a anunciantes ni permitimos que una agencia acceda a los documentos privados de una escort por el solo hecho de estar vinculadas. Una reorganización futura del negocio deberá proteger los datos, informar el cambio de responsable cuando corresponda y respetar los derechos de sus titulares."}]},{"id":"conservacion","title":"Conservación, publicación temporal y eliminación","blocks":[{"id":"block-2","type":"paragraph","text":"Chile3X establece los siguientes plazos operativos propios, atendiendo a la finalidad y sensibilidad de cada dato. No se presentan como plazos generales exigidos por una ley ni impiden atender antes una solicitud de eliminación procedente."},{"id":"block-4","type":"list","text":"","items":["**Cuenta, anuncios y medios ordinarios:** mientras la persona mantenga su cuenta y publicaciones, incluidas las pausadas o recuperables. Deshabilitar no equivale a eliminar. La eliminación definitiva retira los datos operativos y el acceso al contenido; los archivos asociados se borran al completar el proceso o mediante reintentos restringidos. No se conservan originales adicionales por aplicar marca de agua.","**Historias de fotografías, videos y texto:** 24 horas desde su publicación. La limpieza de registros y archivos se ejecuta normalmente en el siguiente ciclo de cinco minutos. Ante una falla se reintenta sin prolongar su acceso público.","**Archivos de identidad:** hasta 90 días desde su última carga o reemplazo. **Archivos médicos existentes:** plazo técnico de hasta 30 días desde su última carga o reemplazo, sin que ello habilite una finalidad no permitida. La información o estado derivado de salud exige la misma revisión jurídica; no se presume lícito conservarlo mientras dure el anuncio.","**Reportes y pruebas adjuntas:** durante la tramitación y hasta 180 días después de su resolución o desestimación. Los casos pendientes no se eliminan por el mero transcurso de ese plazo.","**Conversaciones internas:** hasta 365 días después del último mensaje, salvo una conservación excepcional fundada. La eliminación de una cuenta puede dejar a la otra persona participante su conversación con la identidad desvinculada; no autoriza conservar indefinidamente ese historial.","**Foro beta privado:** los temas y textos se mantienen mientras se utilicen para el desarrollo o la moderación de la beta, sujetos a solicitudes de eliminación procedentes. Los adjuntos retirados, rechazados o asociados a mensajes o temas en papelera se eliminan al cumplir 30 días en ese estado. Las notificaciones internas se conservan hasta 90 días; las denuncias cerradas, hasta 180 días desde la decisión. Los contadores de frecuencia se depuran tras un día sin actividad. La constancia de aceptación de normas y los seguimientos se mantienen mientras la cuenta participe o siga el tema; dejar de seguirlo elimina ese seguimiento.","**Auditoría administrativa:** hasta 365 días desde cada actuación. **Diagnósticos operativos propios:** hasta 30 días. Los registros de sesiones vencidas se depuran hasta 30 días después de su vencimiento; los enlaces de acceso o recuperación no amplían su vigencia al permanecer transitoriamente registrados.","**Historial de correos transaccionales:** hasta 90 días desde cada intento. Registra destinatario, cuenta asociada cuando exista, asunto, tipo, fecha, servicio utilizado y resultado técnico. Su consulta se restringe a administradores autorizados para gestionar cuentas, auditoría y datos privados. No conserva el cuerpo del mensaje, contraseñas ni enlaces o tokens de recuperación. La aceptación por el servicio de envío no acredita recepción, lectura ni entrega en la bandeja principal. La eliminación definitiva de una cuenta retira los registros asociados y los del correo registrado.","**Constancia mínima de eliminación de cuenta:** hasta 180 días. Contiene una huella del correo y los datos mínimos de la eliminación, no el perfil, documentos ni medios; una huella se trata como dato seudonimizado, no como anonimato absoluto.","**Respaldos automáticos de la base de datos:** la ventana técnica de recuperación de Cloudflare D1 es de 7 a 30 días según el plan del proveedor. Una eliminación no borra simultáneamente cada estado de recuperación. Esos respaldos no se utilizan para volver a publicar contenido eliminado; al restaurar se deben reaplicar eliminaciones y vencimientos.","**Muestras privadas:** vigencia inicial de siete días, susceptible de extensión o renovación autorizada. Al vencer o enviarse a papelera se retira su acceso ordinario y se conserva hasta 30 días desde su entrada en papelera; restaurar concede una nueva vigencia. Las convertidas se conservan durante 30 días, sin borrar los archivos transferidos al anuncio. No se promete borrado definitivo a los siete días.","**Aceptación contractual y consentimientos:** la constancia de versiones y fecha de aceptación de la cuenta se mantiene con ella y se elimina por el flujo de borrado, salvo fundamento específico para una evidencia mínima separada. No se presume una conservación perpetua. Una futura evidencia granular o de contratación deberá tener su propio plazo justificado.","**Visitas y clics de contacto de anuncios:** el plazo de la cookie de navegador es de 365 días; no equivale al vencimiento de los eventos en la base de datos. No se afirma que exista una purga automática ya aplicada a esas tablas. La minimización y eliminación procedente de esos registros forman parte de la revisión de conservación y pueden solicitarse por el canal de privacidad."],"ordered":false},{"id":"block-6","type":"paragraph","text":"Los plazos de conservación y su transición operativa se adoptaron el 14 de octubre de 2026. La depuración ordinaria de los plazos no temporales comienza el 13 de noviembre de 2026, con una transición de 30 días para los datos existentes. Esto no cambia el vencimiento de historias ni posterga las solicitudes de eliminación definitiva realizadas mediante las funciones del sitio."},{"id":"block-8","type":"paragraph","text":"Una orden válida, una investigación documentada o la necesidad concreta de ejercer o defender derechos puede justificar conservar únicamente los antecedentes indispensables por un período mayor. La conservación excepcional se registra, se restringe al caso y debe revisarse al cesar su fundamento. Los errores de almacenamiento pueden requerir reintentos: el contenido afectado no vuelve a quedar accesible por ese motivo."},{"id":"extended-5","type":"paragraph","text":"Los plazos anteriores no son autorizaciones mínimas para conservar datos ni sustituyen las reglas de licitud. Si desaparece la finalidad o se recibe una solicitud procedente, debe evaluarse su eliminación antes del máximo. Si un proceso falla se restringe el acceso y se reintenta; la cola técnica de borrado no habilita volver a usar el contenido."},{"id":"extended-6","type":"paragraph","text":"Los respaldos se limitan a recuperación y no deben convertirse en un archivo de explotación indefinida. La restauración debe respetar eliminaciones, revocaciones y vencimientos. Las copias externas que efectivamente se utilicen deben tener conservación, acceso y destrucción definidos; una ventana técnica de D1 no acredita el plazo de todas las copias ni una prueba de restauración."},{"id":"extended-7","type":"paragraph","text":"Una retención excepcional exige un motivo concreto, datos afectados, acceso restringido, responsable de revisión y cese del fundamento. Una investigación no habilita conservar toda una cuenta o archivo si solo necesita una evidencia. Cerrar una cuenta, retirar publicidad, borrar medios y cancelar cargos futuros son operaciones relacionadas, pero distintas."}]},{"id":"derechos","title":"Derechos actuales y derechos del régimen reformado","blocks":[{"id":"block-1","type":"paragraph","text":"Hasta la entrada en vigor de la reforma, la Ley N.º 19.628 reconoce, según sus requisitos, información y acceso, modificación o rectificación, eliminación o cancelación y bloqueo. Las solicitudes actuales no se postergan hasta la nueva ley. Desde la vigencia de la reforma se aplicarán, además, las reglas siguientes:"},{"id":"block-2","type":"list","text":"","items":["**Acceso:** conocer si se tratan datos propios y acceder a ellos y a información sobre su contenido, origen, finalidades, destinatarios, conservación y demás antecedentes legalmente exigibles. Comprende sistemas y archivos bajo control del responsable, no solo lo visible en el panel.","**Rectificación:** corregir o completar datos inexactos, incompletos o desactualizados, indicando el cambio solicitado y los antecedentes pertinentes cuando corresponda.","**Supresión:** eliminar datos innecesarios, caducos, ilícitos o respecto de los cuales se haya retirado el consentimiento sin otra base legal, o cuando concurra otra causal legal. No equivale siempre a borrar inmediatamente cualquier evidencia exigida por ley o necesaria para una reclamación concreta.","**Oposición:** pedir el cese del tratamiento en los supuestos legales, en particular frente a intereses legítimos, marketing directo o determinados datos de fuentes públicas. En caso de interés legítimo, el responsable deberá acreditar motivos imperiosos prevalentes o la necesidad de reclamaciones para continuar cuando la ley lo permita.","**Portabilidad:** recibir los datos facilitados por la persona en un formato electrónico estructurado, genérico y de uso común cuando el tratamiento sea automatizado y se base en su consentimiento, y pedir transmisión directa a otro responsable si es técnicamente posible. No se extiende automáticamente a cualquier inferencia interna, no debe afectar derechos ajenos y no supone suprimir la copia de origen sin pedirlo.","**Bloqueo temporal:** solicitar fundadamente la suspensión del tratamiento al ejercer rectificación, supresión u oposición, o en las alternativas previstas por la ley. Puede mantenerse el almacenamiento restringido; no equivale a permitir otros usos mientras se resuelve.","**Decisiones automatizadas:** oponerse y solicitar las salvaguardas legales ante decisiones automatizadas que produzcan efectos jurídicos o afecten significativamente, incluidas información, explicación, intervención humana, expresar el propio punto de vista y revisión.","**Retirada del consentimiento:** revocar una autorización sin expresión de causa, gratuitamente y sin efecto retroactivo sobre tratamientos anteriores lícitos."],"ordered":false},{"id":"block-3","type":"paragraph","text":"Estos derechos son personales e irrenunciables. Las limitaciones deben responder a una causal legal concreta y ser proporcionadas; no basta invocar genéricamente seguridad, una política de empresa o derechos de terceros. Si una respuesta incluye información de otras personas se aplicará ocultamiento o entrega parcial cuando permita protegerlas sin vaciar el derecho del solicitante."}]},{"id":"ejercicio","title":"Cómo solicitar derechos, plazos y reclamación","blocks":[{"id":"block-1","type":"paragraph","text":"Puede escribirse a [chile3x.site@gmail.com](mailto:chile3x.site@gmail.com), incluso sin cuenta, indicando el derecho o petición y un correo para la respuesta. Para acceso bastará la individualización necesaria de la persona; no se exigirá conocer todas las tablas, localizar cada registro ni justificar por qué desea acceder. Las referencias de cuenta, anuncio o muestra ayudan a ubicar los datos, pero no son un requisito imposible de cumplir."},{"id":"block-2","type":"paragraph","text":"Para rectificación se deben indicar el dato y la corrección; para supresión u oposición, la causal y antecedentes pertinentes cuando correspondan. Si actúa un representante se comprobará su autorización. La autenticación debe ser proporcionada al riesgo, usando el método menos invasivo adecuado; no se pedirán contraseñas ni una copia íntegra del documento de identidad de forma automática."},{"id":"block-3","type":"paragraph","text":"Se acusará recibo y se responderá por escrito al medio indicado. Si falta información indispensable se solicitará de forma concreta, ayudando a precisar la petición sin obstaculizarla ni reiniciar artificialmente el plazo. La búsqueda debe considerar los sistemas y encargados pertinentes, y la entrega deberá protegerse frente a terceros."},{"id":"block-4","type":"callout","text":"**Régimen vigente hasta el 30 de noviembre de 2026:** el artículo 16 de la Ley N.º 19.628 permite acudir al juez civil competente si el responsable no se pronuncia dentro de dos días hábiles o deniega por una causa distinta de la seguridad de la Nación o del interés nacional; estas últimas hipótesis tienen la vía especial ante la Corte Suprema. No se sustituye ese régimen por el futuro plazo general de treinta días."},{"id":"block-5","type":"callout","text":"**Desde la vigencia del texto reformado:** el artículo 11 fija respuesta dentro de **30 días corridos** desde el ingreso, con una sola prórroga de hasta **30 días corridos**. La prórroga se comunicará antes del vencimiento, con su motivo y nueva fecha. La solicitud fundada de **bloqueo temporal** debe responderse en **2 días hábiles**; mientras no se resuelva no se tratarán los datos comprendidos en ella, sin impedir su almacenamiento restringido."},{"id":"block-6","type":"paragraph","text":"La denegación total o parcial debe explicar su causa legal y antecedentes, y la vía para reclamar. Se conservará evidencia de la remisión, fecha y contenido íntegro de la respuesta en un expediente restringido durante el período necesario para atender la solicitud y las responsabilidades aplicables, sin duplicar por rutina documentos sensibles."},{"id":"block-7","type":"paragraph","text":"En el régimen reformado, ante rechazo o falta de respuesta oportuna puede reclamarse ante la Agencia de Protección de Datos Personales dentro de **30 días hábiles**, contados desde la respuesta negativa o el vencimiento del plazo de respuesta, conforme al artículo 41. El rechazo del bloqueo debe fundarse y comunicarse electrónicamente a la Agencia cuando esa obligación sea aplicable. El acceso a tribunales u otras vías que correspondan no se limita por este canal."},{"id":"block-8","type":"paragraph","text":"Chile3X no establece un cobro por tramitar solicitudes en este canal. La rectificación, supresión y oposición serán siempre gratuitas en los términos legales. La ley reformada solo permite determinados costos directos por acceso o portabilidad reiterados más de una vez en un trimestre, sujetos a sus requisitos e instrucciones aplicables; no se presume ni activa aquí ese cobro."},{"id":"block-9","type":"paragraph","text":"Los datos editables pueden corregirse desde [Mi cuenta](/mi-cuenta). El correo y los datos no editables pueden revisarse por soporte. Las herramientas de ocultar, deshabilitar, eliminar cuenta o retirar medios facilitan actuaciones concretas, pero no sustituyen el derecho a una solicitud más amplia. Cuando proceda se comunicarán rectificaciones, supresiones u oposiciones a quienes hayan recibido los datos."}]},{"id":"seguridad","title":"Medidas de seguridad y respuesta a incidentes","blocks":[{"id":"block-2","type":"paragraph","text":"Aplicamos controles de acceso por rol y titularidad, almacenamiento privado para archivos sensibles, conexiones cifradas HTTPS, contraseñas resumidas criptográficamente, validación de formularios, protección anti-bot, registros de seguridad, copias de respaldo y revisión administrativa."},{"id":"block-4","type":"paragraph","text":"Ningún sistema conectado a Internet es infalible. Si detectamos un incidente que afecte datos personales, investigaremos, limitaremos el daño, preservaremos evidencia y notificaremos a personas o autoridades cuando la ley lo exija o sea razonablemente necesario para reducir riesgos. Puedes informar una vulnerabilidad sin explotar ni divulgar datos ajenos escribiendo al canal oficial."},{"id":"extended-3","type":"paragraph","text":"La seguridad se determina según naturaleza, volumen, contexto, finalidad y gravedad del daño posible, considerando especialmente información íntima y salud. La confidencialidad no se limita a evitar ataques: prohíbe consultar por curiosidad, descargar listados sin necesidad o reutilizar datos fuera de la función autorizada. No se afirma cifrado de extremo a extremo de la mensajería interna."},{"id":"extended-4","type":"paragraph","text":"En el régimen reformado, las vulneraciones con riesgo razonable para derechos y libertades se reportarán a la Agencia por los medios más expeditos y **sin dilaciones indebidas**, conforme al artículo 14 sexies. Si afectan datos sensibles o datos económicos, financieros, bancarios o comerciales, se comunicará también a las personas afectadas en los términos legales; la norma incluye asimismo los datos de menores de catorce años, aunque su registro esté prohibido en este sitio."},{"id":"extended-5","type":"paragraph","text":"La comunicación se realizará en lenguaje claro e identificará los datos afectados, posibles consecuencias y medidas de solución o resguardo; se notificará individualmente y, cuando legalmente corresponda por no ser posible, mediante el mecanismo público previsto en la ley. Se documentarán naturaleza, efectos, categorías, número aproximado de afectados y medidas. No se traslada automáticamente a Chile un plazo europeo de 72 horas ni se restringe una obligación más exigente que resulte aplicable."},{"id":"extended-6","type":"paragraph","text":"Se deben mantener procedimientos para detectar, contener, investigar y resolver incidentes, coordinar encargados, preservar evidencia de manera proporcionada y verificar la eficacia de las medidas. La notificación no reemplaza la corrección del incidente. Las instrucciones internas no deben revelar innecesariamente la vida íntima de personas afectadas."}]},{"id":"gobernanza","title":"Responsabilidad, registro de tratamientos y evaluación del riesgo","blocks":[{"id":"block-1","type":"paragraph","text":"El responsable debe poder explicar y acreditar la licitud, la necesidad y las medidas aplicadas. Para ello corresponde mantener un inventario o registro de actividades de tratamiento con finalidades, personas afectadas, categorías, origen, base jurídica, destinatarios, encargados, transferencias, conservación, accesos y medidas. Se adopta como herramienta de gestión y evidencia, sin afirmar que la ley chilena imponga a toda entidad el formato o las excepciones del artículo 30 del RGPD europeo."},{"id":"block-2","type":"paragraph","text":"Desde la vigencia del artículo 15 ter, si es probable un alto riesgo para los derechos de las personas debe realizarse una evaluación de impacto antes de iniciar el tratamiento, además de los supuestos que la ley exige siempre y las instrucciones aplicables de la Agencia. El riesgo del directorio adulto exige analizar exposición, identificación, discriminación, uso de contactos, muestras, acceso de proveedores y seguimiento, sin asumir que ser una empresa pequeña libera de esas obligaciones."},{"id":"block-3","type":"paragraph","text":"La evaluación debe considerar necesidad, proporcionalidad, riesgos y medidas de mitigación; se revisará ante cambios relevantes de finalidad, tecnología o destinatarios. Las matrices, registros y procedimientos no son por sí solos una certificación. No se declara que el portal cuente ya con un modelo de prevención certificado o un delegado legalmente designado; cualquier designación se informará cuando exista."}]},{"id":"menores","title":"Protección de niñas, niños y adolescentes","blocks":[{"id":"block-2","type":"paragraph","text":"Chile3X no está dirigido a menores de 18 años y no acepta su registro, publicación ni aparición en material. Si tomamos conocimiento o tenemos una sospecha razonable, bloquearemos el contenido o cuenta, podremos preservar la evidencia estrictamente necesaria y actuaremos conforme a la legislación y los requerimientos de las autoridades."},{"id":"block-4","type":"paragraph","text":"La posible presencia de una persona menor de edad debe informarse mediante el botón de reporte, cuando se disponga de una cuenta, o inmediatamente a [chile3x.site@gmail.com](mailto:chile3x.site@gmail.com). No debe descargarse, reenviarse ni difundirse el material."}]},{"id":"automatizacion","title":"Moderación y decisiones automatizadas","blocks":[{"id":"block-2","type":"paragraph","text":"Podemos utilizar validaciones automáticas para detectar formatos inválidos, spam, límites de carga, riesgo técnico o señales de abuso. Las decisiones relevantes de publicación, verificación y sanción contemplan revisión administrativa y no se basan exclusivamente en perfilamiento automatizado con efectos jurídicos equivalentes."},{"id":"block-4","type":"paragraph","text":"Si una validación automática produce un error, puede solicitarse intervención humana y revisión mediante el canal de soporte."},{"id":"block-6","type":"paragraph","text":"Las respuestas del bot de ayuda son orientativas y pueden contener errores. La búsqueda guiada no decide aprobaciones, sanciones, verificaciones ni accesos, y puede ser desactivada por administración. La persona interesada puede solicitar asistencia humana por los canales oficiales."},{"id":"extended-4","type":"paragraph","text":"El catálogo utiliza filtros y ordenación por ciudad, categorías, disponibilidad y señales de actividad o popularidad. Esas reglas organizan anuncios, no acreditan identidad, solvencia o conducta del visitante. No se utilizan para inferir públicamente preferencias íntimas de una cuenta. La moderación de Telegram puede incluir reglas automáticas contra spam o abuso, con posibilidad de solicitar revisión al equipo."},{"id":"extended-5","type":"paragraph","text":"Si una validación automática impide un acceso o una operación, se puede explicar el caso y solicitar revisión humana por soporte. Cuando corresponda el régimen del artículo 8 bis reformado, se garantizarán las salvaguardas aun si la decisión se basa en una excepción legal. Una autorización genérica no implica renunciar a conocer o impugnar una decisión significativa."}]},{"id":"cambios","title":"Vigencia, cambios, bibliografía y webgrafía","blocks":[{"id":"block-1","type":"paragraph","text":"Esta es la revisión documental de **26 de octubre de 2026**. Su fecha y versión se muestran al publicarse en el sitio. La política de retención anterior y su transición operativa al 13 de noviembre de 2026 se conservan expresamente; una nueva fecha editorial no acredita que ya se hayan ejecutado todas las tareas técnicas ni cambia el inicio de vigencia legal de la reforma."},{"id":"block-2","type":"paragraph","text":"Los cambios materiales se informarán por medios adecuados al alcance del tratamiento. Si se modifica una finalidad o se necesita un consentimiento nuevo, deberá obtenerse antes de iniciar ese uso; la sola navegación o el silencio no lo reemplazan. Se conservará el historial pertinente y no se alterará retroactivamente el alcance de una autorización."},{"id":"block-3","type":"sources","text":"Normativa oficial consultada el 26 de octubre de 2026","items":["[Constitución Política, artículo 19 N.º 4: vida privada y datos personales](https://www.bcn.cl/leychile/navegar?idNorma=242302)","[Ley N.º 19.628: régimen vigente hasta el 30 de noviembre de 2026](https://www.bcn.cl/leychile/navegar?idNorma=141599&idVersion=2023-05-09)","[Ley N.º 21.719 y sus disposiciones transitorias](https://www.bcn.cl/leychile/navegar?idNorma=1209272)","[Ley N.º 19.628, texto reformado con vigencia desde el 1 de diciembre de 2026: principios, derechos, consentimiento, seguridad, categorías especiales y transferencias](https://www.bcn.cl/leychile/navegar?idNorma=141599&idVersion=2026-12-01)","[Ley N.º 19.496, texto refundido por DFL N.º 3 de 2019: artículos 3 bis, 4, 12 A, 16 y 28 B, según corresponda](https://www.bcn.cl/leychile/navegar?idNorma=1160403)","[Ley N.º 19.799 sobre documentos electrónicos y firma electrónica](https://www.bcn.cl/leychile/navegar?idNorma=196640)","[Decreto N.º 6 de 2021, Reglamento de Comercio Electrónico](https://www.bcn.cl/leychile/navegar?idNorma=1165504)","[Decreto N.º 52 de 2022, publicado en 2024: comunicación de exclusión del retracto](https://www.bcn.cl/leychile/navegar?idNorma=1206144)"]},{"id":"block-4","type":"sources","text":"Bibliografía de apoyo aportada para la revisión","items":["Fernández, Fernando / AltLegal Ltda. El Registro de Actividades de Tratamiento (RAT): Manual para entrevistadores, 14 de agosto de 2026, versión 1.0, 112 páginas. Fernández Acevedo, Fernando / AltLegal: El Registro de Actividades de Tratamiento (RAT), taller MUTUCAR, 9 de septiembre de 2026. Materiales aportados para esta revisión; no constituyen instrucciones de la autoridad ni una certificación del sitio.","Fernández, Fernando / AltLegal Ltda. (2026). Protección de datos personales aplicado al trabajo universitario: Principios, derechos y obligaciones de la Ley N.º 21.719; y Taller de aplicación: Protección de datos personales en la universidad. Versiones UCN y Universidad de Talca identificadas en los archivos como 21 de agosto y 7 de octubre de 2026. Los supuestos universitarios se utilizan solo en cuanto son pertinentes al directorio.","Fernández, Fernando / AltLegal Ltda. (2026). Protección de datos personales: un imperativo estratégico para la educación superior, Universidad de Talca; archivo identificado como 6 de octubre de 2026. Referencia organizativa y de gestión del riesgo.","Comisión Asesora Ministerial para la Implementación de la Ley N.º 21.719 (2025–2026). Informes y recomendaciones incluidos en la colección aportada, especialmente el Cuarto Informe de 16 de enero de 2026. Son antecedentes consultivos, distintos de una norma vigente o una resolución de la Agencia."]},{"id":"block-5","type":"sources","text":"Referencias técnicas y documentos relacionados","items":["[Cloudflare: ventana de recuperación y respaldos de D1](https://developers.cloudflare.com/d1/reference/time-travel/)","[Política de privacidad de Cloudflare](https://www.cloudflare.com/privacypolicy/)","[Política de privacidad de Google](https://policies.google.com/privacy?hl=es)","[Política de privacidad de Telegram](https://telegram.org/privacy)","[AEPD: guía de cookies, referencia comparada y no norma chilena](https://www.aepd.es/guias/guia-cookies.pdf)","[Términos y condiciones](/terminos)","[Reglas de publicación](/reglas-de-publicacion)","[Preferencias de medición](/privacidad?medicion=editar#medicion)"]},{"id":"block-6","type":"paragraph","text":"Las guías de la colección, incluidos modelos europeos, se usan como apoyo técnico o doctrinal. No se importan automáticamente bases legales, plazos, excepciones o certificaciones extranjeras. La normativa chilena vigente y las instrucciones de su autoridad prevalecen. La inclusión de autores o proveedores en esta bibliografía no expresa un respaldo o certificación de Chile3X."}]}]}' WHERE document_id='privacy';

UPDATE _legal_release_20261026 SET reviewed_version='2026.10.17.1',reviewed_json='{"title":"Política de privacidad y tratamiento de datos","description":"Cómo Chile3X recopila, utiliza, protege, publica y elimina datos de visitantes, cuentas y anunciantes.","summary":"Esta política informa los datos tratados por Chile3X, sus finalidades, la información que puede hacerse pública y los mecanismos para ejercer los derechos de sus titulares. Describe el funcionamiento actual del directorio y distingue los datos públicos de los archivos privados.","notice":"**Canal de privacidad:** las solicitudes de acceso, rectificación, eliminación, bloqueo y consultas se reciben en [chile3x.site@gmail.com](mailto:chile3x.site@gmail.com). No deben enviarse contraseñas ni documentos completos por correo; si se requieren antecedentes, el equipo deberá indicar un canal adecuado.","sections":[{"id":"responsable","title":"Responsable, contacto y alcance","blocks":[{"id":"block-2","type":"paragraph","text":"**Chile3X**, nombre comercial del portal disponible en **chile3x.cl**, es responsable del tratamiento descrito en esta política. El canal oficial para consultas y ejercicio de derechos es [chile3x.site@gmail.com](mailto:chile3x.site@gmail.com)."},{"id":"block-4","type":"paragraph","text":"Esta política se aplica a visitantes, personas registradas, anunciantes, agencias, responsables de arriendos, personas que aparecen en publicaciones, quienes reportan contenido y quienes interactúan con las funciones del sitio. Los servicios externos enlazados, como WhatsApp, Telegram, Instagram, Arsmate u OnlyFans, tienen políticas propias."}]},{"id":"principios","title":"Principios que aplicamos","blocks":[{"id":"block-2","type":"paragraph","text":"Chile3X procura tratar datos de forma lícita, leal y transparente; limitar su uso a finalidades informadas; solicitar solo lo necesario; mantenerlos razonablemente actualizados; protegerlos frente a accesos no autorizados y conservarlos únicamente mientras exista una finalidad legítima o una obligación aplicable."},{"id":"block-4","type":"paragraph","text":"No vendemos bases de datos personales. Tampoco utilizamos documentos de identidad, antecedentes médicos, mensajes de reportes ni contenido privado para publicidad dirigida."}]},{"id":"datos","title":"Categorías de datos que tratamos","blocks":[{"id":"block-2","type":"subheading","text":"Visitantes","numbered":true},{"id":"block-4","type":"list","text":"","items":["dirección IP, fecha y hora, ruta solicitada, navegador, dispositivo, registros de error y señales técnicas de seguridad;","confirmación de mayoría de edad, preferencias de privacidad y datos mínimos para mantener la sesión;","datos generales de navegación y eventos únicamente con consentimiento de medición opcional."],"ordered":false},{"id":"block-6","type":"subheading","text":"Cuentas","numbered":true},{"id":"block-8","type":"list","text":"","items":["correo electrónico, nombre visible, nombre completo opcional, tipo y número de documento, país del documento extranjero cuando corresponda, fecha de nacimiento, ciudad y teléfono opcional;","contraseña protegida mediante un resumen criptográfico; Chile3X no almacena contraseñas en texto legible;","estado de verificación del correo, rol, estado de la cuenta, fechas de creación y actividad administrativa;","historial de cambios en métodos de acceso y desvinculación de proveedores, sin contraseñas ni secretos legibles."],"ordered":false},{"id":"block-10","type":"subheading","text":"Anuncios","numbered":true},{"id":"block-12","type":"list","text":"","items":["tipo de perfil, nombre público, alias, URL personalizada, ciudad y región, descripción, características, servicios, idiomas, horarios, precios, agenda de viajes y disponibilidad;","teléfono, WhatsApp y las redes o plataformas que el anunciante decida publicar;","foto de perfil, galería, videos, historias, estados, archivos privados y contenido exclusivo;","estado de publicación, revisión, verificación, moderación, pausa y relaciones autorizadas entre agencias y escorts."],"ordered":false},{"id":"block-14","type":"subheading","text":"Interacciones y seguridad","numbered":true},{"id":"block-16","type":"list","text":"","items":["favoritos, likes, bloqueos, reseñas, comentarios y su estado de moderación;","reportes, motivo, texto y capturas de evidencia, además de las actuaciones administrativas asociadas;","visualizaciones de anuncios y clics en botones de contacto, agrupados por fecha y tipo de acción, incluyendo el número agregado de pulsaciones. Solo con consentimiento de medición, un clic de WhatsApp puede asociarse a la cuenta iniciada y agregar país, región o ciudad aproximada entregada por Cloudflare, tipo de dispositivo y ruta de origen. Sin ese permiso se conserva únicamente un identificador opaco para el conteo diario y nunca se guarda la IP en ese registro;","mensajes privados enviados dentro de Chile3X, anuncio de origen, participantes, fecha, estado de lectura, silencio y bloqueos necesarios para mantener el historial y prevenir abuso;","última actividad reciente de cuentas con anuncios, utilizada únicamente para mostrar un indicador temporal “Online”; el público no recibe la fecha exacta;","si se vincula Telegram: identificador numérico, usuario y nombre que Telegram comparte, estado de vinculación y membresía, invitaciones, medidas de moderación y registros técnicos necesarios para operar el bot;","si se elige Apple una vez habilitado: identificador estable, correo verificado —incluido un posible correo privado de retransmisión—, nombre compartido la primera vez y autorización cifrada necesaria para revocar el acceso al eliminar la cuenta;","actuaciones administrativas: identidad de quien intervino, fecha, operación, elemento afectado, resultado y cambios relevantes. Incluyen aprobación de archivos, modificaciones de anuncios, publicación de historias por administración y configuración. No se duplican archivos de identidad, contraseñas, secretos ni cuerpos de historias en esos registros;","en el foro privado beta: identificador y nombre administrativo de autoría, sección, título, texto, fechas, estados de edición y moderación, versión de las normas aceptadas, declaración de derechos y consentimiento para adjuntos, temas seguidos, notificaciones internas propias y denuncias con su decisión. Esta información no se publica ni se ofrece a usuarios generales; no se deben cargar documentos privados."],"ordered":false}]},{"id":"sensibles","title":"Datos sensibles, íntimos y de especial protección","blocks":[{"id":"block-2","type":"paragraph","text":"Por la naturaleza del directorio, una publicación puede revelar o permitir inferir información sobre vida sexual, identidad o expresión de género, preferencias, apariencia y salud. Además, un anunciante puede cargar voluntariamente antecedentes médicos o material íntimo. Chile3X trata estas categorías con acceso restringido y para las finalidades concretas descritas en esta política."},{"id":"block-4","type":"paragraph","text":"Publicar una etiqueta, descripción o imagen es una decisión de la persona titular del anuncio. Los documentos de identidad, fechas de nacimiento, antecedentes médicos, reportes y galerías exclusivas **no se hacen públicos por defecto**. La persona puede retirar contenido público o solicitar su revisión, sin afectar tratamientos anteriores realizados lícitamente."}]},{"id":"origen","title":"De dónde obtenemos los datos","blocks":[{"id":"block-2","type":"paragraph","text":"Recibimos datos directamente de la persona que visita, se registra, publica, comenta o reporta; de una agencia cuando invita a vincular un perfil, sujeto a aceptación de la escort; del funcionamiento técnico del sitio; y de proveedores que confirman entregas de correo, seguridad o funcionamiento."},{"id":"block-4","type":"paragraph","text":"Si alguien entrega datos de otra persona, declara tener autorización suficiente y debe informarle este tratamiento. Chile3X puede solicitar prueba de esa autorización y eliminar el contenido si no se acredita."}]},{"id":"finalidades","title":"Para qué utilizamos la información","blocks":[{"id":"block-2","type":"list","text":"","items":["crear, autenticar, recuperar, administrar, suspender o cerrar cuentas;","comprobar mayoría de edad y, cuando corresponda, revisar identidad o antecedentes voluntarios;","crear borradores, moderar cambios, publicar, ordenar, buscar, pausar y mostrar anuncios;","gestionar historias, galerías, medios, relaciones agencia–escort y accesos exclusivos;","habilitar favoritos, likes, reseñas, comentarios, mensajería privada, bloqueos, reportes y paneles de rendimiento;","ordenar anuncios según la ciudad o comuna de cobertura seleccionada manualmente; la persona usuaria puede borrar esa preferencia y volver a Todo Chile. Esta función no solicita coordenadas GPS;","vincular voluntariamente Telegram, administrar el acceso a Miembros, sincronizar Novedades, moderar la comunidad y avisar al equipo sobre medidas relevantes;","enviar correos transaccionales como verificación, recuperación, aprobación, rechazo, suspensión y avisos importantes de la cuenta;","prevenir fraude, spam, suplantación, explotación, contenido ilícito, ataques y uso indebido;","resolver solicitudes, cumplir obligaciones legales, colaborar con autoridades competentes y ejercer o defender derechos;","medir y mejorar el sitio con datos generales cuando exista consentimiento para Analytics."],"ordered":false}]},{"id":"bases","title":"Fundamentos del tratamiento","blocks":[{"id":"block-2","type":"paragraph","text":"Según el dato y la finalidad, el tratamiento se apoya en el consentimiento de su titular; la ejecución de las funciones solicitadas al crear una cuenta o publicación; el cumplimiento de obligaciones legales; y la necesidad de proteger la seguridad, prevenir abuso y ejercer o defender derechos, dentro de los límites admitidos por la legislación aplicable."},{"id":"block-4","type":"paragraph","text":"El consentimiento para medición es separado y opcional. La carga voluntaria de documentos médicos o material íntimo requiere una decisión afirmativa de quien lo aporta y puede retirarse para usos futuros. Cuando la ley exija una autorización específica adicional, Chile3X la solicitará antes del tratamiento correspondiente."}]},{"id":"publicos","title":"Perfiles públicos, buscadores y redes sociales","blocks":[{"id":"block-2","type":"paragraph","text":"Una publicación aprobada puede mostrar su nombre público, alias, ciudad, descripción, atributos, disponibilidad, precios, agenda, contactos, imágenes, videos, historias, distintivos, reseñas aprobadas y demás campos que el anunciante haya destinado al perfil público."},{"id":"block-4","type":"paragraph","text":"Las páginas públicas pueden ser encontradas por buscadores, guardadas en caché y generar vistas previas al compartir enlaces. Incluso después de despublicar o modificar una página, Google, redes sociales y otros terceros pueden tardar en actualizar o eliminar sus copias. Chile3X puede solicitar una actualización, pero no controla esos plazos."},{"id":"block-6","type":"paragraph","text":"No publicamos el número de documento, fecha de nacimiento, nombre legal opcional, teléfono privado de la cuenta, carnet, antecedentes médicos ni evidencia de reportes, salvo que la propia persona incorpore voluntariamente un dato equivalente en un campo público."}]},{"id":"documentos","title":"Documentos de identidad y antecedentes médicos opcionales","blocks":[{"id":"block-2","type":"paragraph","text":"Una persona anunciante puede adjuntar imágenes o PDF de un documento de identidad y antecedentes médicos (opcionales)  para revisión interna. Estos archivos se almacenan de forma privada, no tienen una URL pública de listado, no se indexan y solo pueden ser consultados por la persona dueña del anuncio y administradores autorizados que los necesiten para revisar."},{"id":"block-4","type":"paragraph","text":"Un archivo nuevo puede reemplazar al anterior y la persona puede eliminarlo desde las funciones disponibles o pedir su retiro. Chile3X no diagnostica, no certifica vigencia médica ni garantiza que un documento refleje el estado actual de una persona. El resultado de una revisión puede conservarse separadamente como registro de moderación."},{"id":"block-6","type":"paragraph","text":"El acceso a documentos y las actuaciones de carga, reemplazo o eliminación se registran para trazabilidad. El historial no contiene una segunda copia del documento. Los permisos administrativos se asignan por función; disponer de acceso general al panel no autoriza por sí solo la consulta de todos los archivos privados."}]},{"id":"exclusivo","title":"Galería privada y autorizaciones de acceso","blocks":[{"id":"block-2","type":"paragraph","text":"El material exclusivo permanece bloqueado para el público. La persona dueña del anuncio administra el acceso añadiendo el correo de una cuenta registrada. Para operar la función tratamos la relación entre anuncio, cuenta autorizada, archivos y fechas relevantes."},{"id":"block-4","type":"paragraph","text":"La persona anunciante es responsable de confirmar que quien autoriza es adulta y de retirar el acceso cuando corresponda. Aunque Chile3X aplica controles técnicos, ninguna medida puede impedir por completo capturas o copias realizadas por alguien que recibió acceso legítimo. No utilizamos esa galería para entrenar sistemas de inteligencia artificial ni para publicidad."}]},{"id":"comunidad","title":"Reseñas, Telegram, bloqueos, reportes y evidencias","blocks":[{"id":"block-2","type":"paragraph","text":"Las reseñas o comentarios aprobados por el anunciante pueden mostrar el nombre visible de su autor y su contenido. Antes de aprobarse solo pueden consultarlos su autor, el propietario del anuncio y administración. El autor puede retirar su reseña pendiente; el anunciante puede aprobarla, rechazarla o eliminarla, y administración puede consultarla o eliminarla. Favoritos, bloqueos y listas personales no se muestran públicamente. Los reportes y sus capturas son privados y accesibles para el equipo autorizado y para la cuenta que los envió dentro de su panel."},{"id":"block-4","type":"paragraph","text":"Podemos utilizar esos antecedentes para investigar, contactar a las partes cuando sea seguro y necesario, moderar, preservar evidencia, prevenir reiteración y responder a una autoridad. No revelaremos la identidad de quien reporta al perfil denunciado salvo consentimiento, obligación legal o necesidad fundada de defensa, aplicando minimización."},{"id":"block-6","type":"paragraph","text":"Vincular Telegram es opcional. El sitio conserva la relación entre la cuenta y el identificador que entrega Telegram para comprobar acceso, crear invitaciones individuales y aplicar o retirar medidas. Los mensajes procesados por el bot pueden conservarse temporalmente para evitar duplicados, detectar envíos masivos o spam y ejecutar las tareas pendientes; una evidencia breve y la medida aplicada pueden mantenerse mientras sea necesario para revisar el caso y prevenir reincidencia. Desvincular, deshabilitar o eliminar la cuenta retira el acceso a Miembros, pero Telegram puede conservar mensajes conforme a sus propias reglas."},{"id":"block-8","type":"paragraph","text":"El chat interno requiere sesión. Cada participante puede silenciar o bloquear la conversación. Si una de las cuentas se deshabilita o elimina, la otra puede conservar el texto del historial, pero Chile3X sustituye la identidad visible de la persona retirada por “Usuario de Chile3X” y bloquea mensajes nuevos; las relaciones directas con la cuenta eliminada se desprenden de la conversación. Si ya no queda ningún participante con acceso, la conversación se elimina. Los indicadores de no leído y los avisos del navegador se usan solo para comunicar mensajes; Chile3X puede aplicar límites automáticos de frecuencia para reducir spam. No deben enviarse contraseñas, códigos, documentos ni datos bancarios."},{"id":"block-10","type":"paragraph","text":"La sustitución del nombre de una cuenta no anonimiza automáticamente el texto de sus mensajes. Las referencias identificables incorporadas en conversaciones se evalúan conforme a los derechos aplicables y a la finalidad de conservación del historial."},{"id":"block-12","type":"paragraph","text":"El centro de ayuda “Johnny Sins” funciona mediante búsqueda guiada en documentación revisada. Las consultas y valoraciones se mantienen únicamente en la memoria de la pestaña durante la visita; no se guardan como conversación en la base de datos ni se envían a un proveedor de IA generativa. Los enlaces de ayuda pueden referirse a anuncios pertenecientes a la cuenta, consultados con su sesión. Al abrir un WhatsApp de soporte, no se adjunta automáticamente la conversación. No deben ingresarse contraseñas, códigos, documentos ni datos privados de terceros."},{"id":"block-14","type":"paragraph","text":"El foro privado beta se utiliza para desarrollo y pruebas administrativas. Sus contenidos y archivos solo pueden ser consultados por administración habilitada para el foro. Los adjuntos requieren declaración de autorización y consentimiento, están sujetos a cuotas y quedan pendientes de revisión; esto no equivale a una certificación de identidad o legalidad. Las notificaciones se limitan a temas seguidos y a su destinatario; no se envían correos automáticos. Archivar una sección o enviar un tema a papelera no equivale a borrar inmediatamente sus datos. Las denuncias permiten solicitar revisión y rectificación; sus decisiones quedan registradas, sin duplicar los textos de las respuestas en la auditoría. Los contadores de frecuencia ayudan a limitar cargas y publicaciones abusivas."}]},{"id":"medicion","title":"Cookies, almacenamiento local y medición opcional","blocks":[{"id":"block-2","type":"subheading","text":"Funciones necesarias","numbered":true},{"id":"block-4","type":"paragraph","text":"Utilizamos cookies o almacenamiento equivalente para mantener la sesión, recordar la confirmación de mayoría de edad, conservar preferencias de privacidad, proteger formularios, limitar abuso, recordar historias vistas y operar funciones solicitadas. Estas tecnologías son necesarias para que ciertas partes del sitio funcionen y no se utilizan para publicidad conductual."},{"id":"block-6","type":"subheading","text":"Inicio de sesión con Google","numbered":true},{"id":"block-8","type":"paragraph","text":"Si se elige continuar con Google, recibimos el identificador estable de la cuenta de Google, el correo verificado y el nombre que Google comparte. Usamos el identificador y el correo para comprobar la identidad, vincular o crear la cuenta y evitar accesos duplicados; el nombre solo completa inicialmente campos editables durante el registro."},{"id":"block-10","type":"paragraph","text":"No solicitamos acceso a Gmail, Drive, contactos, archivos ni calendario, y no almacenamos tokens de acceso de Google. El correo queda vinculado y no puede modificarse desde la cuenta. Si abandonas el registro, los datos del intento se eliminan automáticamente al vencer el plazo breve de seguridad."},{"id":"block-12","type":"paragraph","text":"La persona titular puede desvincular un proveedor desde Mis datos después de configurar y confirmar una contraseña. Esto no elimina la cuenta ni revierte la verificación de su correo. Conservamos un historial de cambios de acceso, consultable por la persona titular y administración autorizada, para proteger la cuenta."},{"id":"block-14","type":"subheading","text":"Inicio de sesión con Apple preparado, aún inactivo","numbered":true},{"id":"block-16","type":"paragraph","text":"Chile3X muestra un botón de Apple deshabilitado mientras el proveedor no se encuentre habilitado con una configuración completa. En ese estado no se abre Apple ni se le envían datos. Si se habilita en el futuro y la persona elige utilizarlo, recibiremos el identificador estable, correo verificado y, únicamente en la primera autorización, el nombre que Apple comparta. Esos nombres solo completarán campos editables del registro; el correo quedará bloqueado."},{"id":"block-18","type":"paragraph","text":"El flujo rechazará identidades incompatibles, incluido un correo vinculado a otro proveedor o a una identidad administrativa. La autorización de larga duración que Apple entregue se almacenará cifrada y se utilizará para revocarla cuando corresponda, incluida la eliminación permanente de la cuenta. Chile3X no recibirá la contraseña de Apple ni acceso a iCloud, fotos, contactos o archivos."},{"id":"block-20","type":"subheading","text":"Google Tag Manager y Google Analytics","numbered":true},{"id":"block-22","type":"paragraph","text":"Los WhatsApp del equipo usan contadores internos agregados por día, área y acceso: aperturas del panel y clics para abrir WhatsApp. No guardan IP, cuenta, número del visitante ni el contenido de mensajes, y no acreditan que se haya enviado un mensaje. Son independientes de los contactos de anunciantes."},{"id":"block-24","type":"paragraph","text":"El contacto del anunciante destacado dentro del panel de WhatsApp utiliza el registro de contactos del anuncio, no el contador del equipo. El contador de pulsaciones de WhatsApp del anuncio es visible únicamente para administración autorizada. El equipo no recibe el contenido de las conversaciones mantenidas en WhatsApp."},{"id":"block-26","type":"paragraph","text":"La medición es opcional y solo se carga cuando la persona selecciona **“Aceptar medición”** en el aviso de privacidad. Con esa autorización se miden visitas y acciones generales como registros, envíos de anuncios, clics de contacto, favoritos, likes y reseñas para entender el uso y mejorar Chile3X."},{"id":"block-28","type":"paragraph","text":"No configuramos el envío a Google de nombres, correos, teléfonos, RUT, direcciones, archivos privados, texto libre ni identificadores internos de perfiles como parámetros de Analytics. Google puede tratar información técnica como dirección IP, navegador, dispositivo y señales de interacción conforme a sus propias condiciones y medidas disponibles."},{"id":"block-30","type":"paragraph","text":"Al seleccionar **“Solo necesarias”**, el sitio seguirá funcionando sin cargar Google Tag Manager ni Google Analytics. La elección puede retirarse o modificarse en cualquier momento; el cambio no invalida el tratamiento anterior basado en consentimiento."},{"id":"block-32","type":"paragraph","text":"[Cambiar mi elección de medición →](/privacidad?medicion=editar#medicion)"},{"id":"block-34","type":"subheading","text":"Inicio de sesión con X preparado, aún inactivo","numbered":true},{"id":"block-36","type":"paragraph","text":"Mientras el acceso con X esté deshabilitado no se abre ese proveedor ni se le envían datos. Si se habilita y la persona elige utilizarlo, recibiremos su identificador estable, nombre, nombre de usuario y el correo confirmado que X autorice compartir. Si no entrega un correo confirmado, la persona deberá completar y verificar uno mediante el proceso del sitio. El nombre solo completa campos editables del registro."},{"id":"block-38","type":"paragraph","text":"No solicitamos permiso para publicar, enviar mensajes privados ni acceder a mensajes. El token se utiliza únicamente para obtener la identidad y se solicita su revocación al terminar; no se almacena como credencial permanente. X podrá desvincularse con los mismos controles de contraseña e historial que los demás proveedores."},{"id":"block-40","type":"subheading","text":"Mapas referenciales de Google Maps","numbered":true},{"id":"block-42","type":"paragraph","text":"Los anuncios incluyen un mapa referencial de su ciudad, que se carga de forma diferida. Solo enviamos el nombre de la ciudad, región y país: no enviamos el nombre del anunciante, su cuenta, dirección, notas de ubicación ni coordenadas privadas. Al cargarse el mapa o abrir Maps, Google puede recibir información técnica del navegador y aplicar sus propias condiciones y política de privacidad. No solicitamos la ubicación de la persona visitante para mostrar estos mapas."}]},{"id":"proveedores","title":"Proveedores tecnológicos y transferencias internacionales","blocks":[{"id":"block-2","type":"paragraph","text":"Para operar Chile3X utilizamos proveedores que tratan datos por cuenta del portal o prestan infraestructura bajo sus propios términos:"},{"id":"block-4","type":"list","text":"","items":["**Cloudflare:** alojamiento del sitio, base de datos, almacenamiento de archivos, red de entrega, certificados, seguridad y Turnstile para combatir bots;","**Google:** autenticación cuando se elige “Continuar con Google”, correo transaccional, mapas referenciales de ciudades y, solo con consentimiento, Google Tag Manager y Google Analytics;","**Telegram:** comunidad pública, vinculación voluntaria de cuentas, invitaciones a Miembros, Novedades y moderación mediante el bot;","**Apple:** solo si el proveedor llega a habilitarse y la persona lo elige, autenticación y revocación de la autorización asociada;","**X:** solo si el acceso llega a habilitarse y la persona lo elige, autenticación e identidad autorizada para crear o vincular su cuenta;","**proveedores de navegador, sistema operativo o redes externas:** únicamente cuando la persona utiliza esas aplicaciones o sigue un enlace."],"ordered":false},{"id":"block-6","type":"paragraph","text":"Estos servicios pueden procesar o respaldar información fuera de Chile. Chile3X procura escoger proveedores reconocidos, limitar los datos enviados, configurar accesos y aplicar salvaguardas contractuales y técnicas razonables. La ubicación de la infraestructura puede cambiar sin que ello signifique una venta de datos."}]},{"id":"autoridades","title":"Cuándo podemos comunicar datos","blocks":[{"id":"block-2","type":"paragraph","text":"Podemos comunicar la información mínima necesaria a proveedores que operan el servicio; a asesores sujetos a deberes de confidencialidad; a autoridades judiciales, policiales, administrativas o al Ministerio Público ante una orden o requerimiento válido; o cuando sea necesario para denunciar o prevenir una amenaza seria, explotación, trata, abuso de menores, difusión íntima no consentida, fraude o ataque."},{"id":"block-4","type":"paragraph","text":"No entregamos bases de datos a anunciantes ni permitimos que una agencia acceda a los documentos privados de una escort por el solo hecho de estar vinculadas. Una reorganización futura del negocio deberá proteger los datos, informar el cambio de responsable cuando corresponda y respetar los derechos de sus titulares."}]},{"id":"conservacion","title":"Conservación, publicación temporal y eliminación","blocks":[{"id":"block-2","type":"paragraph","text":"Chile3X establece los siguientes plazos operativos propios, atendiendo a la finalidad y sensibilidad de cada dato. No se presentan como plazos generales exigidos por una ley ni impiden atender antes una solicitud de eliminación procedente."},{"id":"block-4","type":"list","text":"","items":["**Cuenta, anuncios y medios ordinarios:** mientras la persona mantenga su cuenta y publicaciones, incluidas las pausadas o recuperables. Deshabilitar no equivale a eliminar. La eliminación definitiva retira los datos operativos y el acceso al contenido; los archivos asociados se borran al completar el proceso o mediante reintentos restringidos. No se conservan originales adicionales por aplicar marca de agua.","**Historias de fotografías, videos y texto:** 24 horas desde su publicación. La limpieza de registros y archivos se ejecuta normalmente en el siguiente ciclo de cinco minutos. Ante una falla se reintenta sin prolongar su acceso público.","**Archivos de identidad:** hasta 90 días desde su última carga o reemplazo. **Exámenes y certificados médicos:** hasta 30 días desde su última carga o reemplazo. Después se restringe su consulta y se elimina el archivo; el resultado y fecha de la revisión pueden mantenerse mientras exista el anuncio, sin conservar el documento original ni constituir una garantía de salud.","**Reportes y pruebas adjuntas:** durante la tramitación y hasta 180 días después de su resolución o desestimación. Los casos pendientes no se eliminan por el mero transcurso de ese plazo.","**Conversaciones internas:** hasta 365 días después del último mensaje, salvo una conservación excepcional fundada. La eliminación de una cuenta puede dejar a la otra persona participante su conversación con la identidad desvinculada; no autoriza conservar indefinidamente ese historial.","**Foro beta privado:** los temas y textos se mantienen mientras se utilicen para el desarrollo o la moderación de la beta, sujetos a solicitudes de eliminación procedentes. Los adjuntos retirados, rechazados o asociados a mensajes o temas en papelera se eliminan al cumplir 30 días en ese estado. Las notificaciones internas se conservan hasta 90 días; las denuncias cerradas, hasta 180 días desde la decisión. Los contadores de frecuencia se depuran tras un día sin actividad. La constancia de aceptación de normas y los seguimientos se mantienen mientras la cuenta participe o siga el tema; dejar de seguirlo elimina ese seguimiento.","**Auditoría administrativa:** hasta 365 días desde cada actuación. **Diagnósticos operativos propios:** hasta 30 días. Los registros de sesiones vencidas se depuran hasta 30 días después de su vencimiento; los enlaces de acceso o recuperación no amplían su vigencia al permanecer transitoriamente registrados.","**Historial de correos transaccionales:** hasta 90 días desde cada intento. Registra destinatario, cuenta asociada cuando exista, asunto, tipo, fecha, servicio utilizado y resultado técnico. Su consulta se restringe a administradores autorizados para gestionar cuentas, auditoría y datos privados. No conserva el cuerpo del mensaje, contraseñas ni enlaces o tokens de recuperación. La aceptación por el servicio de envío no acredita recepción, lectura ni entrega en la bandeja principal. La eliminación definitiva de una cuenta retira los registros asociados y los del correo registrado.","**Constancia mínima de eliminación de cuenta:** hasta 180 días. Contiene una huella del correo y los datos mínimos de la eliminación, no el perfil, documentos ni medios; una huella se trata como dato seudonimizado, no como anonimato absoluto.","**Respaldos automáticos de la base de datos:** la ventana técnica de recuperación de Cloudflare D1 es de 7 a 30 días según el plan del proveedor. Una eliminación no borra simultáneamente cada estado de recuperación. Esos respaldos no se utilizan para volver a publicar contenido eliminado; al restaurar se deben reaplicar eliminaciones y vencimientos."],"ordered":false},{"id":"block-6","type":"paragraph","text":"La política se aplica desde el 14 de octubre de 2026. La depuración ordinaria de los plazos no temporales comienza el 13 de noviembre de 2026, con una transición de 30 días para los datos existentes. Esto no cambia el vencimiento de historias ni posterga las solicitudes de eliminación definitiva realizadas mediante las funciones del sitio."},{"id":"block-8","type":"paragraph","text":"Una orden válida, una investigación documentada o la necesidad concreta de ejercer o defender derechos puede justificar conservar únicamente los antecedentes indispensables por un período mayor. La conservación excepcional se registra, se restringe al caso y debe revisarse al cesar su fundamento. Los errores de almacenamiento pueden requerir reintentos: el contenido afectado no vuelve a quedar accesible por ese motivo."}]},{"id":"derechos","title":"Derechos de la persona titular","blocks":[{"id":"block-2","type":"paragraph","text":"De acuerdo con la Ley N.º 19.628 vigente, la persona titular puede solicitar información y acceso a sus datos, su rectificación cuando sean inexactos o estén desactualizados, su eliminación o cancelación cuando proceda y el bloqueo de determinados tratamientos en los casos legales."},{"id":"block-4","type":"paragraph","text":"La Ley N.º 21.719 prevé su entrada en vigor el **1 de diciembre de 2026**, conforme al texto legal publicado consultado para esta versión. Refuerza el marco chileno e incorpora derechos de acceso, rectificación, supresión, oposición, portabilidad y bloqueo temporal, junto con reglas sobre decisiones automatizadas. Su aplicación se realizará conforme a la vigencia y exigencias legales efectivas; una propuesta de modificación de plazos no altera por sí sola la ley publicada."},{"id":"block-6","type":"paragraph","text":"Estos derechos no son absolutos: una solicitud puede limitarse cuando sea necesario conservar antecedentes para obligaciones legales, seguridad, derechos de terceros, libertad de expresión, investigación de ilícitos o defensa de reclamaciones, explicando el fundamento aplicable."}]},{"id":"ejercicio","title":"Ejercicio de los derechos","blocks":[{"id":"block-2","type":"paragraph","text":"La persona titular puede editar parte de su información desde [Mi cuenta](/mi-cuenta) o presentar una solicitud en [chile3x.site@gmail.com](mailto:chile3x.site@gmail.com) indicando:"},{"id":"block-4","type":"list","text":"","items":["el derecho o solicitud que desea ejercer;","el correo asociado a su cuenta y los datos necesarios para ubicar el anuncio;","una explicación clara y, si corresponde, el dato correcto o el contenido cuya eliminación solicitas."],"ordered":false},{"id":"block-6","type":"paragraph","text":"Podemos verificar la identidad mediante el método menos invasivo razonablemente disponible antes de entregar o modificar información. No debe enviarse una contraseña. Las solicitudes se responderán dentro de los plazos de la ley vigente y serán gratuitas en los casos legalmente previstos."},{"id":"block-8","type":"paragraph","text":"También puede retirarse el consentimiento de medición desde esta página, revocarse el acceso a la galería exclusiva, ocultarse un anuncio, eliminarse historias o solicitarse el cierre de la cuenta mediante las opciones disponibles. Si la respuesta resulta insatisfactoria, la persona titular puede acudir a tribunales o a la autoridad competente, incluida la Agencia de Protección de Datos Personales una vez que ejerza sus atribuciones."}]},{"id":"seguridad","title":"Medidas de seguridad y respuesta a incidentes","blocks":[{"id":"block-2","type":"paragraph","text":"Aplicamos controles de acceso por rol y titularidad, almacenamiento privado para archivos sensibles, conexiones cifradas HTTPS, contraseñas resumidas criptográficamente, validación de formularios, protección anti-bot, registros de seguridad, copias de respaldo y revisión administrativa."},{"id":"block-4","type":"paragraph","text":"Ningún sistema conectado a Internet es infalible. Si detectamos un incidente que afecte datos personales, investigaremos, limitaremos el daño, preservaremos evidencia y notificaremos a personas o autoridades cuando la ley lo exija o sea razonablemente necesario para reducir riesgos. Puedes informar una vulnerabilidad sin explotar ni divulgar datos ajenos escribiendo al canal oficial."}]},{"id":"menores","title":"Protección de niñas, niños y adolescentes","blocks":[{"id":"block-2","type":"paragraph","text":"Chile3X no está dirigido a menores de 18 años y no acepta su registro, publicación ni aparición en material. Si tomamos conocimiento o tenemos una sospecha razonable, bloquearemos el contenido o cuenta, podremos preservar la evidencia estrictamente necesaria y actuaremos conforme a la legislación y los requerimientos de las autoridades."},{"id":"block-4","type":"paragraph","text":"La posible presencia de una persona menor de edad debe informarse mediante el botón de reporte, cuando se disponga de una cuenta, o inmediatamente a [chile3x.site@gmail.com](mailto:chile3x.site@gmail.com). No debe descargarse, reenviarse ni difundirse el material."}]},{"id":"automatizacion","title":"Moderación y decisiones automatizadas","blocks":[{"id":"block-2","type":"paragraph","text":"Podemos utilizar validaciones automáticas para detectar formatos inválidos, spam, límites de carga, riesgo técnico o señales de abuso. Las decisiones relevantes de publicación, verificación y sanción contemplan revisión administrativa y no se basan exclusivamente en perfilamiento automatizado con efectos jurídicos equivalentes."},{"id":"block-4","type":"paragraph","text":"Si una validación automática produce un error, puede solicitarse intervención humana y revisión mediante el canal de soporte."},{"id":"block-6","type":"paragraph","text":"Las respuestas del bot de ayuda son orientativas y pueden contener errores. La búsqueda guiada no decide aprobaciones, sanciones, verificaciones ni accesos, y puede ser desactivada por administración. La persona interesada puede solicitar asistencia humana por los canales oficiales."}]},{"id":"cambios","title":"Vigencia, cambios y legislación aplicable","blocks":[{"id":"block-2","type":"paragraph","text":"Esta política se rige por la legislación chilena, especialmente la Ley N.º 19.628 y, desde el 1 de diciembre de 2026, sus modificaciones introducidas por la Ley N.º 21.719. También pueden resultar aplicables la Ley N.º 19.496, la Ley N.º 19.799, el Código Penal y otras normas sectoriales."},{"id":"block-4","type":"paragraph","text":"Podemos actualizar la política por cambios legales, técnicos o funcionales. Mostraremos la versión y fecha vigentes; si el cambio altera materialmente una finalidad o requiere consentimiento, lo informaremos y solicitaremos la autorización correspondiente antes de aplicarlo."},{"id":"block-6","type":"sources","text":"Fuentes legales y políticas relacionadas","items":["[Ley N.º 19.628 sobre protección de la vida privada](https://www.bcn.cl/leychile/navegar?idNorma=141599)","[Ley N.º 21.719 sobre protección de datos personales](https://www.bcn.cl/leychile/navegar?idNorma=1209272)","[Ley N.º 19.496 sobre protección de los derechos de los consumidores](https://www.bcn.cl/leychile/navegar?idNorma=61438)","[Términos y condiciones de Chile3X](/terminos)","[Reglas de publicación](/reglas-de-publicacion)"]}]}]}' WHERE document_id='privacy';

UPDATE _legal_release_20261026 SET eligible=1
WHERE EXISTS (
 SELECT 1 FROM legal_documents d
 WHERE d.id=_legal_release_20261026.document_id AND (
  (d.version='2026.10.14.3' AND (d.published_json IS NULL OR CASE WHEN json_valid(d.published_json) THEN json(d.published_json)=json(_legal_release_20261026.previous_json) ELSE 0 END))
  OR (d.version=_legal_release_20261026.reviewed_version AND CASE WHEN json_valid(d.published_json) THEN json(d.published_json)=json(_legal_release_20261026.reviewed_json) ELSE 0 END)
 )
)
AND NOT EXISTS (
 SELECT 1 FROM legal_document_versions v
 WHERE v.document_id=_legal_release_20261026.document_id AND v.version='2026.10.26.1'
 AND CASE WHEN json_valid(v.document_json) THEN json(v.document_json)<>json(_legal_release_20261026.next_json) ELSE 1 END
);

INSERT INTO legal_document_versions(id,document_id,version,document_json,published_at,published_by)
SELECT 'legal-20261026-previous-'||d.id,d.id,d.version,coalesce(d.published_json,r.previous_json),d.published_at,d.updated_by
FROM legal_documents d JOIN _legal_release_20261026 r ON r.document_id=d.id
WHERE r.eligible=1
ON CONFLICT(document_id,version) DO NOTHING;

INSERT INTO legal_document_versions(id,document_id,version,document_json,published_at,published_by)
SELECT 'legal-20261026-current-'||r.document_id,r.document_id,'2026.10.26.1',r.next_json,'2026-10-26',NULL
FROM _legal_release_20261026 r WHERE r.eligible=1
ON CONFLICT(document_id,version) DO NOTHING;

UPDATE legal_documents
SET published_json=(SELECT r.next_json FROM _legal_release_20261026 r WHERE r.document_id=legal_documents.id),
 version='2026.10.26.1', published_at='2026-10-26', updated_at=CURRENT_TIMESTAMP, updated_by=NULL
WHERE id IN (SELECT document_id FROM _legal_release_20261026 WHERE eligible=1);
-- draft_json se conserva. El trigger existente incrementa la revisión para rechazar guardados obsoletos.

DROP TABLE _legal_release_20261026;
